WORKER_PING = "import time,json\nfrom app.workers.celery_app import celery_app\nuntil=time.monotonic()+35\nwhile True:\n    replies=celery_app.control.inspect(timeout=2).ping() or {}\n    good=[k for k,v in replies.items() if isinstance(v,dict) and v.get('ok')=='pong']\n    if len(good)>=2 and any(k.startswith('discovery@') for k in good) and any(k.startswith('celery@') for k in good):\n        print('WORKERS_RESPONDING:',json.dumps(good),flush=True)\n        break\n    if time.monotonic()>=until:raise SystemExit('WORKER_READINESS_NOT_CONFIRMED: Beat not started; inspect worker logs')\n    time.sleep(1)\n"
REVIEW_BUTTON_PATCHES = {'app/main.py': [('    external_id: str = Field(min_length=1, max_length=200, pattern=r"^[A-Za-z0-9_-]+$")', '    external_id: str = Field(min_length=1, max_length=200, pattern=r"^[A-Za-z0-9_-]+(?::[0-9]+)?$")')], 'app/api/manual_analysis.py': [(" external_id:str=Field(pattern=r'^[A-Za-z0-9_-]+$',max_length=200)", " external_id:str=Field(pattern=r'^[A-Za-z0-9_-]+(?::[0-9]+)?$',max_length=200)")], 'app/static/index.html': [('async function analyzeReview(row, button) {', "async function reviewResponseError(response) {\n  let detail;\n  try { const body = await response.json(); detail = body.detail; } catch (_) {}\n  if (Array.isArray(detail)) {\n    detail = detail.map(item => {\n      const field = Array.isArray(item.loc) ? item.loc.filter(x => x !== 'body').join('.') : '';\n      return (field ? field + ': ' : '') + String(item.msg || 'Некорректное значение');\n    }).join('; ');\n  }\n  if (typeof detail !== 'string' || !detail.trim()) detail = 'Сервер не выполнил действие';\n  return new Error('HTTP ' + response.status + ': ' + detail.slice(0, 1200));\n}\n\nasync function analyzeReview(row, button) {"), ("    if (!response.ok) { const error = await response.json(); throw new Error(error.detail || 'Ошибка запуска'); }", '    if (!response.ok) throw await reviewResponseError(response);'), ("\n  if (!response.ok) throw new Error('Save failed');\n", '\n  if (!response.ok) throw await reviewResponseError(response);\n'), ("  } catch(e) { status.textContent='Не удалось убрать запись. Попробуйте снова.'; button.disabled=false; }", "  } catch(e) { status.textContent='Не удалось убрать запись. ' + String(e.message || e); button.disabled=false; }"), ("      catch(e) { undo.disabled=false; alert('Не удалось восстановить запись'); }", "      catch(e) { undo.disabled=false; status.textContent='Не удалось восстановить запись. ' + String(e.message || e); }")]}
REVIEW_BUTTON_TESTS = "# Offline route regression tests: real validation/selection store, mocked broker/DB.\nimport ast as _rba\nimport tempfile as _rbt\nfrom pathlib import Path as _rbp\nfrom datetime import datetime as _rbd, timezone as _rbz, timedelta as _rbdelta\nfrom unittest.mock import patch as _rbpatch, MagicMock as _rbmock\nfrom fastapi import FastAPI as _rbapp, Request as _rbrequest, HTTPException as _rbhttp\nfrom fastapi.testclient import TestClient as _rbclient\nfrom pydantic import BaseModel as _rbbase, Field as _rbfield, ValidationError as _rbvalidation\nfrom app.core.config import settings as _rbsettings\nimport app.api.manual_analysis as _rbmanual\nimport app.marketplace_discovery.review_store as _rbstore\nimport app.reports.review_dismissals as _rbdismiss\nimport app.reports.manual_analysis as _rbselection\nfrom app.workers.tasks_manual_analysis import analyze_selected as _rbtask\n\n_rbtree=_rba.parse(_rbp('app/main.py').read_text())\n_rbnodes=[n for n in _rbtree.body if isinstance(n,(_rba.ClassDef,_rba.FunctionDef)) and n.name in ('ReviewDismissalRequest','dismiss_review_item')]\nassert len(_rbnodes)==2\n_rbns={'app':_rbapp(),'BaseModel':_rbbase,'Field':_rbfield,'Request':_rbrequest,'HTTPException':_rbhttp}\nexec(compile(_rba.Module(body=_rbnodes,type_ignores=[]),'actual_review_routes','exec'),_rbns)\n_rbns['app'].include_router(_rbmanual.router)\n_rbmodels=(_rbns['ReviewDismissalRequest'],_rbmanual.Selection)\n_rbnumber='B2310261308594:1'\nfor _rbmodel in _rbmodels:\n for _rbid in (_rbnumber,'B2210261539117:12','2077557','01a1446f-e58b-7ffa-bdef-070a3b8cb0f1'):\n  assert _rbmodel(source='roseltorg',external_id=_rbid).external_id==_rbid\n for _rbid in ('', '../x', 'B:1:2','B:abc','B:','B/1','B?x=1','x'*201):\n  try:_rbmodel(source='roseltorg',external_id=_rbid)\n  except _rbvalidation:pass\n  else:raise AssertionError(('invalid identity accepted',_rbid))\n\n_rbheaders={'X-Review-Action':'manual','Origin':'http://testserver'}\n_rbbody={'source':'roseltorg','external_id':_rbnumber}\n_rbfuture=(_rbd.now(_rbz.utc)+_rbdelta(days=10)).isoformat()\n_rbcandidate={**_rbbody,'title':'Алюминиевый профиль','source_url':'https://www.roseltorg.ru/procedure/B2310261308594/1','submission_deadline':_rbfuture,'raw_payload':{'procurement_status':'Прием заявок'}}\n_rbdb=_rbmock();_rbdb.__enter__.return_value=_rbdb\n_rbdb.execute.return_value.scalar_one_or_none.return_value=None\nwith _rbt.TemporaryDirectory() as _rbtmp, _rbpatch.object(_rbsettings,'storage_path',_rbtmp), _rbpatch.object(_rbmanual,'SyncSessionLocal',return_value=_rbdb), _rbpatch.object(_rbstore,'list_review_candidates',return_value=[_rbcandidate]), _rbpatch.object(_rbtask,'apply_async') as _rbsend:\n with _rbclient(_rbns['app']) as _rbc:\n  for _rburl in ('/tenders/review/dismiss','/tenders/manual-analysis'):\n   assert _rbc.post(_rburl,json=_rbbody).status_code==403\n   assert _rbc.post(_rburl,json=_rbbody,headers={**_rbheaders,'Origin':'https://other.invalid'}).status_code==403\n   assert _rbc.post(_rburl,json={**_rbbody,'external_id':'B:abc'},headers=_rbheaders).status_code==422\n  _rbsend.assert_not_called()\n  assert _rbc.post('/tenders/review/dismiss',json=_rbbody,headers=_rbheaders).status_code==200\n  assert _rbdismiss.is_dismissed('roseltorg',_rbnumber)\n  assert not _rbdismiss.is_dismissed('roseltorg','B2310261308594:2')\n  assert _rbc.post('/tenders/manual-analysis',json=_rbbody,headers=_rbheaders).status_code==409\n  _rbsend.assert_not_called()\n  assert _rbc.post('/tenders/review/dismiss',json={**_rbbody,'dismissed':False},headers=_rbheaders).status_code==200\n  assert not _rbdismiss.is_dismissed('roseltorg',_rbnumber)\n  _rbfirst=_rbc.post('/tenders/manual-analysis',json=_rbbody,headers=_rbheaders)\n  assert _rbfirst.status_code==200,_rbfirst.text\n  _rbsecond=_rbc.post('/tenders/manual-analysis',json=_rbbody,headers=_rbheaders)\n  assert _rbsecond.status_code==200 and _rbfirst.json()['task_id']==_rbsecond.json()['task_id']\n  _rbsend.assert_called_once()\n  assert _rbsend.call_args.kwargs['args'][0]['external_id']==_rbnumber\n  assert _rbsend.call_args.kwargs['queue']=='celery'\n  assert _rbc.post('/tenders/manual-analysis',json={**_rbbody,'external_id':'B999:1'},headers=_rbheaders).status_code==404\n  assert _rbsend.call_count==1\n  with _rbpatch.object(_rbstore,'list_review_candidates',return_value=[{**_rbcandidate,'external_id':'BOLD:1','submission_deadline':(_rbd.now(_rbz.utc)-_rbdelta(days=1)).isoformat()}]):\n   assert _rbc.post('/tenders/manual-analysis',json={**_rbbody,'external_id':'BOLD:1'},headers=_rbheaders).status_code==409\n  assert _rbsend.call_count==1\n_rbhtml=_rbp('app/static/index.html').read_text()\nassert _rbhtml.count('async function reviewResponseError(')==1\nassert _rbhtml.count('throw await reviewResponseError(response);')==2\nassert 'String(e.message || e)' in _rbhtml\nprint('REVIEW_BUTTON_TESTS_OK: real request schemas/routes; lot IDs retained; dismiss/undo; selected queue mocked; duplicate protection; 403/404/409/422; no live DB, broker or LLM',flush=True)\n"
