import argparse,ast,hashlib,json,os,shutil,subprocess,tempfile,time,sys
from pathlib import Path
from datetime import datetime,timezone

def run(cmd,**kwargs):return subprocess.run(cmd,check=True,**kwargs)
def digest(b):return hashlib.sha256(b).hexdigest()
def image_function(source):
 tree=ast.parse(source)
 nodes=[n for n in tree.body if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef)) and n.name=='extract_image']
 stores=[n for n in ast.walk(tree) if isinstance(n,ast.Name) and n.id=='extract_image' and isinstance(n.ctx,ast.Store)]
 if len(nodes)!=1 or stores or nodes[0].decorator_list:
  raise SystemExit('OCR_FUNCTION_LAYOUT_UNSUPPORTED: no files changed')
 return nodes[0]

def image_ast(node):
 # Formatting and the documentation string do not change function behavior.
 node=ast.parse(ast.unparse(node)).body[0]
 if node.body and isinstance(node.body[0],ast.Expr) and isinstance(node.body[0].value,ast.Constant) and isinstance(node.body[0].value.value,str):node.body=node.body[1:]
 return ast.dump(node,include_attributes=False)

def patch_image_only(current,desired):
 source=current.decode('utf-8')
 actual=image_function(source);old=image_function(OLD_IMAGE_SOURCE);new=image_function(desired)
 if image_ast(actual)==image_ast(new):return source
 if image_ast(actual)!=image_ast(old):
  print('OCR_CURRENT_SHA256:',digest(current),flush=True)
  print('OCR_CURRENT_FUNCTION:\n'+ast.get_source_segment(source,actual),flush=True)
  raise SystemExit('OCR_FUNCTION_VERSION_MISMATCH: no files changed; current function printed above')
 helpers=[n for n in ast.parse(source).body if isinstance(n,ast.FunctionDef) and n.name=='_ocr_image']
 if len(helpers)!=1 or len(helpers[0].args.args)<2 or helpers[0].args.args[1].arg!='page_number':
  raise SystemExit('OCR_HELPER_SIGNATURE_MISMATCH: no files changed')
 lines=source.splitlines(keepends=True)
 replacement=ast.get_source_segment(desired,new)+'\n'
 patched=''.join(lines[:actual.lineno-1])+replacement+''.join(lines[actual.end_lineno:])
 compile(patched,'app/ocr/pipeline.py','exec')
 return patched

def patch_known_function(current,desired,name,original):
 source=current.decode('utf8')
 def find(text):
  tree=ast.parse(text)
  body=tree.body
  parts=name.split('.')
  for part in parts[:-1]:
   classes=[n for n in body if isinstance(n,ast.ClassDef) and n.name==part]
   if len(classes)!=1:raise SystemExit('FUNCTION_LAYOUT_UNSUPPORTED: '+name)
   body=classes[0].body
  nodes=[n for n in body if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef)) and n.name==parts[-1]]
  if len(nodes)!=1:raise SystemExit('FUNCTION_LAYOUT_UNSUPPORTED: '+name)
  return nodes[0]
 actual=find(source);new=find(desired)
 originals=original if isinstance(original,(tuple,list)) else (original,)
 olds=[find(item) for item in originals]
 if image_ast(actual)==image_ast(new):return source
 if not any(image_ast(actual)==image_ast(old) for old in olds):raise SystemExit('FUNCTION_VERSION_MISMATCH: '+name+'; no files changed')
 lines=source.splitlines(keepends=True)
 start=min([actual.lineno]+[d.lineno for d in actual.decorator_list])-1
 newstart=min([new.lineno]+[d.lineno for d in new.decorator_list])-1
 newlines=desired.splitlines(keepends=True)
 patched=''.join(lines[:start])+''.join(newlines[newstart:new.end_lineno])+''.join(lines[actual.end_lineno:])
 compile(patched,name,'exec')
 return patched

def check_files(root):
 pending=[]
 for rel,expected,content in FILES:
  p=root/rel
  if p.is_symlink():raise SystemExit('SYMLINK_NOT_SUPPORTED: '+rel)
  current=p.read_bytes() if p.is_file() else None
  if rel in TEXT_PATCHES:
   if current is None:raise SystemExit('FILE_MISSING: '+rel+'; no files changed')
   text=current.decode('utf8')
   for before,after in TEXT_PATCHES[rel]:
    if text.count(after)==1:continue
    if text.count(before)!=1:raise SystemExit('TEXT_VERSION_MISMATCH: '+rel+'; no files changed')
    text=text.replace(before,after,1)
   if text.encode('utf8')!=current:pending.append((rel,text,current))
   continue
  if rel in FOCUSED_FUNCTIONS and current is not None:
   names,original=FOCUSED_FUNCTIONS[rel]
   names=names if isinstance(names,(tuple,list)) else (names,)
   desired=content;patched=current
   for name in names:patched=patch_known_function(patched,desired,name,original).encode('utf8')
   content=patched.decode('utf8')
   if patched!=current:pending.append((rel,content,current))
   continue
  if rel=='app/ocr/pipeline.py' and current is not None:
   content=patch_image_only(current,content)
   if content.encode('utf8')!=current:pending.append((rel,content,current))
   continue
  wanted=content.encode('utf8')
  if current==wanted:continue
  if (current is None and expected is not None) or (current is not None and digest(current) not in {expected,*ACCEPTED_PREVIOUS.get(rel,[])}):
   raise SystemExit('VERSION_MISMATCH: '+rel+'; no files changed. Send this line; do not bypass.')
  compile(content,rel,'exec')
  pending.append((rel,content,current))
 return pending

def atomic(path,data):
 path.parent.mkdir(parents=True,exist_ok=True)
 fd,tmp=tempfile.mkstemp(dir=path.parent,prefix=path.name+'.')
 try:
  with os.fdopen(fd,'wb') as f:f.write(data)
  if path.exists():shutil.copymode(path,tmp)
  os.replace(tmp,path)
 finally:
  if os.path.exists(tmp):os.unlink(tmp)

def compare_network():
 for label,cmd in [('host',['python3','-']),('celery_discovery',['docker','compose','exec','-T','celery_discovery','python','-'])]:
  print('TENDER_PRO_NETWORK:',label,flush=True)
  try:
   run(cmd,input=NETWORK_PROBE,text=True,timeout=35)
  except subprocess.TimeoutExpired:
   print(json.dumps({'environment':label,'status':'probe_timeout','phase':'unknown; probe exceeded 35s'}),flush=True)
  except (OSError,subprocess.CalledProcessError) as exc:
   print(json.dumps({'environment':label,'status':'probe_unavailable','error_type':type(exc).__name__}),flush=True)
 print('NETWORK_COMPARE_FINISHED: no HTTP API, credentials, DB changes, queues, OCR or LLM',flush=True)

def check_tender_pro_public():
 try:
  run(['docker','compose','exec','-T','celery_discovery','python','-'],input=CHECK_TENDER_PRO_PUBLIC,text=True,timeout=90)
 except subprocess.TimeoutExpired:
  print('TENDER_PRO_PUBLIC_CHECK_TIMEOUT: completion not confirmed; no automatic retry',flush=True)
 except (OSError,subprocess.CalledProcessError) as exc:
  print('TENDER_PRO_PUBLIC_CHECK_UNAVAILABLE:',type(exc).__name__,flush=True)

def check_new_platforms():
 try:
  run(['docker','compose','exec','-T','celery_discovery','python','-'],input=CHECK_NEW_PLATFORMS,text=True,timeout=300)
 except subprocess.TimeoutExpired:
  print('NEW_PLATFORMS_CHECK_TIMEOUT: completion/report not confirmed; no automatic retry',flush=True)
 except (OSError,subprocess.CalledProcessError) as exc:
  print('NEW_PLATFORMS_CHECK_UNAVAILABLE:',type(exc).__name__,flush=True)

def review_button_changes(root):
 pending=[]
 for rel,pairs in REVIEW_BUTTON_PATCHES.items():
  path=root/rel
  if path.is_symlink() or not path.is_file():raise SystemExit('REVIEW_SOURCE_MISSING_OR_SYMLINK: '+rel+'; no changes')
  old=path.read_bytes();value=old.decode('utf8')
  for before,after in pairs:
   if value.count(after)==1:continue
   if value.count(before)!=1:raise SystemExit('REVIEW_TEXT_VERSION_MISMATCH: '+rel+'; no changes')
   value=value.replace(before,after,1)
  if rel.endswith('.py'):compile(value,rel,'exec')
  if value.encode()!=old:pending.append((rel,value,old))
 return pending

def repair_review_buttons(root):
 pending=review_button_changes(root)
 print('REVIEW_BUTTON_SOURCE_GUARDS_OK; CHANGES:',len(pending),flush=True)
 backup=root/'backups'/('review-buttons-'+datetime.now(timezone.utc).strftime('%Y%m%d-%H%M%S-%f'))
 try:
  for rel,value,old in pending:atomic(backup/rel,old)
  for rel,value,old in pending:atomic(root/rel,value.encode('utf8'))
  if pending:print('BACKUP:',backup,flush=True)
  run(['docker','compose','build','app'])
  run(['docker','compose','run','--rm','--no-deps','-T','app','python','-'],input=REVIEW_BUTTON_TESTS,text=True,timeout=90)
 except BaseException:
  for rel,_,old in pending:atomic(root/rel,old)
  print('REVIEW_BUILD_OR_TEST_FAILED: source restored; running app not restarted',flush=True)
  raise
 run(['docker','compose','up','-d','--no-deps','app'])
 run(['docker','compose','exec','-T','app','python','-'],input=REVIEW_BUTTON_VERIFY,text=True,timeout=60)
 print('REVIEW_BUTTONS_INSTALLED: app updated; refresh browser; no DB edits, manual exclusions changed, tasks or LLM calls by installer; workers and Beat untouched',flush=True)


SBER_CARD_CHECK = '"""Read one public Sber purchase using its observed read-only APL contract.\nNo business ingestion, state edits, queues, OCR, LLM or authentication.\n"""\nimport hashlib\nimport io\nimport json\nimport re\nimport signal\nimport time\nimport zipfile\nfrom datetime import datetime, timezone\nfrom pathlib import PurePosixPath\nfrom urllib.parse import urljoin, urlsplit, parse_qsl, urlencode\nfrom uuid import UUID\nfrom xml.etree import ElementTree\nfrom xml.parsers import expat\n\nORIGIN = \'https://utp.sberbank-ast.ru\'\nCARD_PATH = \'/Transneft/NBT/PurchaseView/5/0/0/4268910\'\nCARD = ORIGIN + CARD_PATH\nEXPECTED_ID = \'4268910\'\nEXPECTED_NUMBER = \'SBR043-2610260077.100254290\'\nVERSION = \'sber-public-purchase-read-20261028-4\'\n\n\nclass Stop(ValueError):\n    pass\n\n\ndef allowed(url):\n    try:\n        p = urlsplit(url)\n        return (p.scheme == \'https\' and p.hostname == \'utp.sberbank-ast.ru\'\n                and not p.username and not p.password and not p.fragment\n                and p.port in (None,443)\n                and not re.search(r\'/(?:auth|login|logout|captcha|register)(?:/|\\.|$)\',p.path,re.I)\n                and not any(re.search(r\'token|secret|session|password|auth|key|signature\',k,re.I) for k,v in parse_qsl(p.query)))\n    except ValueError:\n        return False\n\n\ndef location(url):\n    p=urlsplit(url)\n    return p._replace(query=\'\',fragment=\'\').geturl()\n\n\nclass Reader:\n    def __init__(self,fetch=None,transport=None):\n        self.fetch=fetch\n        self.requests=[]\n        self.started=time.monotonic()\n        self.stopped=False\n        self.file_urls=set()\n        self.asset_urls=set()\n        self.retries_used=0\n        self.transport=transport\n        self._client=None\n        self.session_cookie_count=0\n        self.auth_cookies_discarded=0\n\n    def get(self,url,*,payload=None,limit=2_000_000):\n        if self.stopped:\n            raise Stop(\'source_stopped_after_error\')\n        if not allowed(url):\n            raise Stop(\'unapproved_url\')\n        if payload is not None:\n            if url != ORIGIN+\'/api/Processing/main\' or payload != {\'windowCode\':CARD_PATH,\'actionType\':\'TEMPLATE\',\'actionCode\':CARD_PATH}:\n                raise Stop(\'non_read_operation_refused\')\n        elif url not in {CARD,ORIGIN+\'/build/apl_config.json\'}|self.asset_urls|self.file_urls:\n            raise Stop(\'unobserved_get_refused\')\n        # Retry only a read timeout of a public page/config/script. Never retry\n        # API reads, document transfers, HTTP refusals or challenge responses.\n        import httpx\n        retryable_get = payload is None and url in {CARD,ORIGIN+\'/build/apl_config.json\'}|self.asset_urls\n        for attempt in (1,2):\n            if len(self.requests)>=9 or time.monotonic()-self.started>=180:\n                self.stopped=True\n                raise Stop(\'request_budget_exhausted\')\n            row={\'method\':\'POST\' if payload is not None else \'GET\',\'url\':location(url),\'attempt\':attempt}\n            self.requests.append(row)\n            try:\n                result=self.fetch(url,payload=payload,limit=limit) if self.fetch else self.http(url,payload,limit)\n                row[\'http\']=result[\'http\']\n                if result[\'http\']!=200:\n                    raise Stop(\'http_\'+str(result[\'http\']))\n                if not result[\'body\'] or len(result[\'body\'])>limit:\n                    raise Stop(\'empty_or_oversized_response\')\n                row.update(bytes=len(result[\'body\']),sha256=hashlib.sha256(result[\'body\']).hexdigest())\n                return result\n            except Exception as exc:\n                reason=\'read_timeout\' if isinstance(exc,httpx.ReadTimeout) else (str(exc) if isinstance(exc,Stop) else \'transport_error\')\n                retry=(isinstance(exc,httpx.ReadTimeout) and retryable_get and attempt==1\n                       and self.retries_used<2 and len(self.requests)<9\n                       and time.monotonic()-self.started<140)\n                row.update(error_type=type(exc).__name__,reason=reason,retry_scheduled=retry)\n                if retry:\n                    self.retries_used+=1\n                    time.sleep(2)\n                    continue\n                self.stopped=True\n                raise\n\n    def close(self):\n        if self._client is not None:\n            self._client.cookies.clear()\n            self._client.close()\n            self._client=None\n\n    def http(self,url,payload,limit):\n        import httpx\n        headers={\'Accept\':\'application/json\' if payload else \'*/*\',\n                 \'Accept-Encoding\':\'identity\',\'Accept-Language\':\'ru-RU\'}\n        if url!=CARD:headers[\'Referer\']=CARD\n        if payload:\n            headers.update({\'Content-Type\':\'application/json\',\'Origin\':ORIGIN,\n                            \'X-AST-WINDOWCODE\':CARD_PATH,\'X-AST-ACTIONCODE\':CARD_PATH,\n                            \'X-AST-ACTIONTYPE\':\'TEMPLATE\',\'X-AST-PAGEURL\':CARD})\n        if self._client is None:\n            # A fresh anonymous visitor for this probe only. The public card,\n            # scripts and data request share the server-issued session in memory.\n            # No cookies or tokens are imported from a browser, disk or account.\n            self._client=httpx.Client(verify=True,follow_redirects=False,\n                                      timeout=httpx.Timeout(30,connect=5),transport=self.transport)\n        start=time.monotonic()\n        with self._client.stream(\'POST\' if payload else \'GET\',url,json=payload,headers=headers) as response:\n            # A public visit must never transition into authenticated processing.\n            for cookie in list(self._client.cookies.jar):\n                if re.search(r\'auth|token|identity|jwt|aspnet.*cookies\',cookie.name,re.I):\n                    self._client.cookies.delete(cookie.name,domain=cookie.domain,path=cookie.path)\n                    self.auth_cookies_discarded+=1\n            self.session_cookie_count=len(self._client.cookies.jar)\n            if response.status_code!=200:raise Stop(\'http_\'+str(response.status_code))\n            declared=response.headers.get(\'content-length\')\n            if declared and declared.isdigit() and int(declared)>limit:raise Stop(\'response_too_large\')\n            content=bytearray()\n            for block in response.iter_bytes():\n                content.extend(block)\n                if len(content)>limit:raise Stop(\'response_too_large\')\n                if time.monotonic()-start>45:raise Stop(\'body_time_limit\')\n                if time.monotonic()-self.started>=180:raise Stop(\'request_budget_exhausted\')\n            return {\'http\':200,\'body\':bytes(content),\'content_type\':response.headers.get(\'content-type\',\'\')}\n\n\ndef check_html(body):\n    from bs4 import BeautifulSoup\n    soup=BeautifulSoup(body,\'html.parser\')\n    for tag in soup([\'script\',\'style\']):tag.decompose()\n    text=soup.get_text(\' \',strip=True)\n    if re.search(r\'anti.bot verification|verify you are human|проверка.{0,25}робот|подтвердите.{0,25}человек|access denied|техническая поддержка\\s+UUID\',text[:30000],re.I):\n        raise Stop(\'access_challenge\')\n    if soup.select(\'input[type=password]\'):raise Stop(\'interactive_access_required\')\n\n\ndef contract(body,core,form,config):\n    from bs4 import BeautifulSoup\n    check_html(body)\n    soup=BeautifulSoup(body,\'html.parser\')\n    tag=soup.find(\'a-form\',attrs={\'ref\':\'form\'})\n    if tag is None or tag.get(\':window-code\')!=\'formProps.windowCode\' or tag.get(\':action-code\')!=\'formProps.windowCode\':\n        raise Stop(\'card_form_contract_changed\')\n    if tag.has_attr(\'action-type\') or tag.has_attr(\':action-type\') or tag.has_attr(\'parm\') or tag.has_attr(\':parm\'):\n        raise Stop(\'card_form_override_requires_review\')\n    if not re.search(r"xmlRootName\\s*:\\s*[\'\\"]purchase[\'\\"]",body.decode(\'utf-8\',\'replace\')):\n        raise Stop(\'purchase_root_not_observed\')\n    if not re.search(r\'this\\.formProps\\.windowCode\\s*=\\s*new URL\\(window\\.location\\.href\\)\\.pathname\',form):\n        raise Stop(\'window_code_loader_changed\')\n    if not re.search(r\'formOptions\\s*:\\s*\\{\\s*\\}\',form):raise Stop(\'form_options_require_review\')\n    # Validate both the modern form default and the shared JSON read transport.\n    binding=re.search(r\'name:"AForm2023"\\},\\{props:\\{\\.\\.\\.([A-Za-z_$][\\w$]*)\',core)\n    if not binding:raise Stop(\'modern_form_binding_changed\')\n    declaration=re.search(r\'\\b\'+re.escape(binding[1])+r\'=\\{\',core)\n    if not declaration:raise Stop(\'modern_form_props_missing\')\n    modern=core[declaration.start():declaration.start()+7500]\n    if not all(x in core for x in (\'Processing/main\',\'Processing/file\',\'X-AST-WINDOWCODE\',\'getData:\',\'keysToLowerCase\')):\n        raise Stop(\'core_read_transport_changed\')\n    if \'actionType:{type:String,default:"TEMPLATE"}\' not in modern:\n        raise Stop(\'template_default_changed\')\n    if not re.search(r\'windowCode:[\\w$]+\\.value,actionType:[\\w$]+\\.value,actionCode:[\\w$]+\\.value\',core) or \'.default.data.post(\' not in core:\n        raise Stop(\'template_payload_changed\')\n    if not re.search(r\'([A-Za-z_$][\\w$]*)=\\1\\[Object\\.getOwnPropertyNames\\(\\1\\)\\[0\\]\\]\',core):\n        raise Stop(\'response_envelope_loader_changed\')\n    if not isinstance(config,dict) or config.get(\'API_BASE_URL\') not in (\'/api/\',ORIGIN+\'/api/\'):\n        raise Stop(\'production_api_config_unconfirmed\')\n    return {\'windowCode\':CARD_PATH,\'actionType\':\'TEMPLATE\',\'actionCode\':CARD_PATH}\n\n\ndef lower_keys(value,depth=0):\n    if depth>40:raise Stop(\'response_nesting_limit\')\n    if isinstance(value,dict):\n        out={}\n        for k,v in value.items():\n            key=k.casefold()\n            if key in out:raise Stop(\'case_colliding_keys\')\n            out[key]=lower_keys(v,depth+1)\n        return out\n    if isinstance(value,list):return [lower_keys(v,depth+1) for v in value]\n    return value\n\n\nSENSITIVE_KEY = re.compile(r\'token|secret|session|password|authorization|cookie|credential|signature\',re.I)\nSERVICE_KEYS = {\'error\',\'message\',\'reason\',\'code\',\'statuscode\',\'status\',\'title\',\'main\',\'errorcode\',\'errormessage\',\'description\'}\n\n\ndef safe_service_text(value):\n    text=str(value)\n    text=re.sub(r\'https?://[^\\s\\\'"<>]+\',\'[URL]\',text,flags=re.I)\n    text=re.sub(r\'(?i)\\bBearer\\s+[^\\s,;<>]+\',\'Bearer [hidden]\',text)\n    text=re.sub(r"(?i)(token|secret|session(?:id)?|password|authorization|cookie|credential|signature)[\\"\']?\\s*[:=]\\s*(?:\\"[^\\"]*\\"|\'[^\']*\'|[^\\s,;<>]+)",r\'\\1=[hidden]\',text)\n    text=re.sub(r\'[\\w.+-]+@[\\w.-]+\\.[A-Za-z]{2,}\',\'[EMAIL]\',text)\n    text=re.sub(r\'<[^>]{0,1000}>\',\' \',text)\n    return \' \'.join(text.split())[:800]\n\n\ndef response_object(body):\n    # Mirror the public UI\'s JSON decoding; never parse XML or execute a reply.\n    value=json.loads(body)\n    for _ in range(2):\n        if not isinstance(value,str):break\n        value=json.loads(value)\n    if not isinstance(value,dict):raise Stop(\'purchase_response_not_object\')\n    return lower_keys(value)\n\n\ndef response_evidence(value):\n    """Bounded schema plus service messages, never the full purchase or tokens."""\n    result={\'root_keys\':[], \'nodes\':[], \'service_messages\':[]}\n    for k in list(value)[:30]:\n        result[\'root_keys\'].append(\'[sensitive_key]\' if SENSITIVE_KEY.search(k) else k[:100])\n    def visit(node,path,depth=0):\n        if depth>5 or len(result[\'nodes\'])>=80:return\n        result[\'nodes\'].append({\'path\':path,\'type\':type(node).__name__,\n                                **({\'length\':len(node)} if isinstance(node,(str,list,dict)) else {})})\n        if isinstance(node,dict):\n            for k,v in list(node.items())[:30]:\n                if SENSITIVE_KEY.search(k):continue\n                child=path+\'.\'+k[:100]\n                if k in SERVICE_KEYS and isinstance(v,(str,int,float,bool)) and len(result[\'service_messages\'])<10:\n                    result[\'service_messages\'].append({\'path\':child,\'value\':safe_service_text(v)})\n                visit(v,child,depth+1)\n        elif isinstance(node,list):\n            for i,v in enumerate(node[:2]):visit(v,path+\'[\'+str(i)+\']\',depth+1)\n    visit(value,\'$\')\n    return result\n\n\ndef envelope_error(value):\n    # Check only response/control envelopes. Nested lot/document business fields\n    # such as status must not be interpreted as an API failure.\n    checks=[value]\n    if value:\n        first=next(iter(value.values()))\n        if isinstance(first,dict):checks.append(first)\n    for node in checks:\n        if node.get(\'error\') or node.get(\'errors\') or node.get(\'errormessage\'):\n            return \'purchase_response_service_error\'\n        if node.get(\'statuscode\') in (401,403,\'401\',\'403\'):\n            return \'purchase_response_refused\'\n        if node.get(\'success\') is False or node.get(\'isauthorized\') is False:\n            return \'purchase_response_not_successful\'\n    return None\n\n\ndef select_purchase(value):\n    reason=envelope_error(value)\n    if reason:raise Stop(reason)\n    # AForm2023 in the observed core.js selects the first JSON property before\n    # keysToLowerCase(). xmlRootName is a form name, not a guaranteed JSON key.\n    if not value:raise Stop(\'purchase_response_empty_object\')\n    key=next(iter(value))\n    purchase=value[key]\n    if not isinstance(purchase,dict):raise Stop(\'purchase_envelope_not_object\')\n    if set(purchase)=={\'aplformprops\'}:\n        raise Stop(\'form_settings_only_no_purchase_data\')\n    info=purchase.get(\'purchaseinfo\')\n    if not isinstance(info,dict):raise Stop(\'purchase_info_missing_in_first_envelope\')\n    if str(info.get(\'purchaseid\'))!=EXPECTED_ID or str(info.get(\'purchasecode\'))!=EXPECTED_NUMBER:\n        raise Stop(\'purchase_identity_mismatch\')\n    return purchase,key\n\n\ndef decode(body):\n    return select_purchase(response_object(body))[0]\n\n\ndef rows(value,label):\n    if value is None or value==\'\':return []\n    if isinstance(value,dict):return [value]\n    if not isinstance(value,list) or not all(isinstance(x,dict) for x in value):raise Stop(label+\'_shape\')\n    return value\n\n\ndef summarize(purchase):\n    info=purchase[\'purchaseinfo\'];tender=purchase.get(\'tenderinfo\') or {}\n    if not isinstance(tender,dict):raise Stop(\'tender_info_shape\')\n    bids=purchase.get(\'bids\') or {}\n    if not isinstance(bids,dict):raise Stop(\'bids_shape\')\n    lots=[];seen=set()\n    for bid in rows(bids.get(\'bid\') or purchase.get(\'bid\'),\'bids\'):\n        data=bid.get(\'bidinfo\')\n        if not isinstance(data,dict):raise Stop(\'bid_info_shape\')\n        bidid=str(data.get(\'bidid\') or \'\')\n        if not bidid or bidid in seen:raise Stop(\'missing_or_duplicate_bid_id\')\n        seen.add(bidid)\n        positions=data.get(\'positions\') or {}\n        if not isinstance(positions,dict):raise Stop(\'positions_shape\')\n        ps=rows(positions.get(\'position\'),\'positions\')\n        lots.append({\'bid_id\':bidid,\'number\':data.get(\'bidno\'),\'title\':data.get(\'bidname\'),\n                     \'positions_count\':len(ps), \'positions_preview_truncated\':len(ps)>30,\n                     \'positions\':[{k:p.get(k) for k in (\'positionid\',\'positionno\',\'positionname\',\'positionquantity\',\'positionokei\',\'positionoosokpd2\',\'positiondopinfo\')} for p in ps[:30]]})\n    return {\'external_id\':EXPECTED_ID,\'number\':info[\'purchasecode\'],\'title\':info.get(\'purchasename\'),\n            \'stage_raw\':info.get(\'purchasestatusname\'),\'deadline_raw\':tender.get(\'requeststopdate\'),\n            \'deadline_timezone_verified\':False,\'identity_verified\':True,\n            \'lots_count\':len(lots),\'lots\':lots,\'raw_root_keys\':sorted(purchase)}\n\n\ndef document_list(purchase):\n    # Only the public documentation binding observed in the purchase HTML.\n    docs=purchase.get(\'docs\')\n    if not isinstance(docs,dict):raise Stop(\'documents_block_missing\')\n    container=docs.get(\'auctiondocs\')\n    if not isinstance(container,dict):raise Stop(\'documents_binding_shape\')\n    files=rows(container.get(\'file\'),\'documents\')\n    result=[];seen={}\n    for f in files:\n        guid=f.get(\'fileid\') or f.get(\'guid\')\n        try:guid=str(UUID(str(guid)))\n        except (ValueError,TypeError,AttributeError):raise Stop(\'document_guid_invalid\')\n        if f.get(\'fileid\') and f.get(\'guid\') and str(UUID(str(f[\'fileid\'])))!=str(UUID(str(f[\'guid\']))):raise Stop(\'document_guid_conflict\')\n        name=f.get(\'filename\')\n        if not isinstance(name,str) or not name.strip():raise Stop(\'document_name_missing\')\n        if guid in seen:\n            if seen[guid]!=name:raise Stop(\'document_name_conflict\')\n            continue\n        seen[guid]=name\n        result.append({\'file_id\':guid,\'filename\':name,\'url\':ORIGIN+\'/api/Processing/file?\'+urlencode({\'fileGuid\':guid})})\n    if not result:raise Stop(\'no_public_documents\')\n    return result\n\n\ndef safe_xml(raw):\n    def reject(*args):raise Stop(\'xml_dtd_entity_refused\')\n    parser=expat.ParserCreate()\n    parser.StartDoctypeDeclHandler=reject\n    parser.EntityDeclHandler=reject\n    parser.ExternalEntityRefHandler=reject\n    parser.Parse(raw,True)\n    return ElementTree.fromstring(raw)\n\n\ndef file_check(body,name):\n    suffix=PurePosixPath(name.replace(\'\\\\\',\'/\')).suffix.lower()\n    if suffix not in (\'.docx\',\'.xlsx\',\'.pdf\',\'.doc\',\'.xls\',\'.zip\',\'.rar\',\'.7z\',\'.tif\',\'.tiff\',\'.jpg\',\'.jpeg\',\'.png\'):\n        raise Stop(\'unsupported_document_format\')\n    from app.sources.gpb.archives import validate_bytes\n    validate_bytes(body,suffix)\n    result={\'bytes\':len(body),\'sha256\':hashlib.sha256(body).hexdigest(),\'format\':suffix,\'full_download_verified\':True,\'text_extraction\':\'not_run\'}\n    if suffix in (\'.docx\',\'.xlsx\'):\n        with zipfile.ZipFile(io.BytesIO(body)) as z:\n            entries=z.infolist()\n            if len(entries)>3000 or sum(i.file_size for i in entries)>40_000_000:raise Stop(\'office_expansion_limit\')\n            if any(i.flag_bits&1 for i in entries):raise Stop(\'encrypted_office\')\n            if z.testzip() is not None:raise Stop(\'office_crc_error\')\n            if \'[Content_Types].xml\' not in z.namelist():raise Stop(\'not_office_package\')\n            member=\'word/document.xml\' if suffix==\'.docx\' else \'xl/workbook.xml\'\n            raw=z.read(member)\n            if re.search(br\'<!\\s*(?:DOCTYPE|ENTITY)\\b\',raw,re.I):raise Stop(\'xml_dtd_entity_refused\')\n            tree=safe_xml(raw)\n            if suffix==\'.docx\':\n                text=\' \'.join(e.text or \'\' for e in tree.iter() if e.tag.endswith(\'}t\'))\n                result.update(text_extraction=\'office_xml_read_only\',text_characters=len(text),text_excerpt=text[:3500])\n            else:result.update(workbook_sheets=[e.attrib.get(\'name\') for e in tree.iter() if e.tag.endswith(\'}sheet\')])\n    return result\n\n\ndef probe(reader=None):\n    from bs4 import BeautifulSoup\n    reader=reader or Reader()\n    report={\'version\':VERSION,\'checked_at\':datetime.now(timezone.utc).isoformat(),\'source\':\'sberbank_ast\',\n            \'card\':CARD,\'pipeline_ready\':False,\'queued_count\':0,\'status\':\'not_checked\',\'errors\':[]}\n    phase=\'card_html\'\n    try:\n        html=reader.get(CARD)[\'body\'];check_html(html)\n        soup=BeautifulSoup(html,\'html.parser\')\n        linked={urlsplit(urljoin(CARD,t[\'src\'])).path:urljoin(CARD,t[\'src\']) for t in soup.select(\'script[src]\')}\n        core_url=linked.get(\'/CoreApl/core.js\');form_url=linked.get(\'/js/apl/aplFormScript.js\')\n        if not core_url or not form_url or not allowed(core_url) or not allowed(form_url):raise Stop(\'observed_loader_scripts_missing\')\n        reader.asset_urls.update((core_url,form_url))\n        phase=\'production_config\';config=json.loads(reader.get(ORIGIN+\'/build/apl_config.json\')[\'body\'])\n        phase=\'core_script\';core=reader.get(core_url,limit=8_000_000)[\'body\'].decode(\'utf-8-sig\')\n        phase=\'form_script\';form=reader.get(form_url,limit=500_000)[\'body\'].decode(\'utf-8-sig\')\n        phase=\'read_contract\';payload=contract(html,core,form,config)\n        report[\'read_contract_verified\']=True\n        phase=\'purchase_data\';response=reader.get(ORIGIN+\'/api/Processing/main\',payload=payload,limit=4_000_000)\n        raw=response[\'body\']\n        report[\'response_sha256\']=hashlib.sha256(raw).hexdigest()\n        report[\'response_content_type\']=response.get(\'content_type\',\'\')[:150]\n        phase=\'purchase_response_decode\';value=response_object(raw)\n        phase=\'purchase_identity\';purchase,envelope=select_purchase(value)\n        report[\'response_envelope\']=envelope\n        report[\'purchase\']=summarize(purchase)\n        phase=\'public_document_list\';docs=document_list(purchase)\n        report[\'public_documents_total\']=len(docs)\n        report[\'documents_scope\']=\'docs.auctiondocs only; other bindings not verified\'\n        report[\'documents\']=[{k:d[k] for k in (\'file_id\',\'filename\')} for d in docs]\n        report[\'document_checks\']=[]\n        # Two full samples only. All remaining files still need production integration.\n        for doc in docs[:2]:\n            phase=\'document_download\';reader.file_urls.add(doc[\'url\'])\n            response=reader.get(doc[\'url\'],limit=20_000_000)\n            phase=\'document_validation\';checked=file_check(response[\'body\'],doc[\'filename\'])\n            report[\'document_checks\'].append({\'file_id\':doc[\'file_id\'],\'filename\':doc[\'filename\'],**checked})\n        report[\'all_listed_documents_download_checked\']=len(docs)==len(report[\'document_checks\'])\n        report[\'status\']=\'public_purchase_and_document_samples_verified\'\n    except Exception as exc:\n        report[\'status\']=\'incomplete\'\n        report[\'errors\'].append({\'phase\':phase,\'error_type\':type(exc).__name__, \'reason\':(\'read_timeout\' if type(exc).__name__==\'ReadTimeout\' else str(exc) if isinstance(exc,Stop) else \'check_failed\')})\n        if \'value\' in locals():report[\'response_evidence\']=response_evidence(value)\n        # Shape evidence without dumping personal details or arbitrary response text.\n        if \'purchase\' in locals():\n            report[\'schema_evidence\']={\'root_keys\':sorted(purchase), \'docs_keys\':sorted(purchase.get(\'docs\',{})) if isinstance(purchase.get(\'docs\'),dict) else None}\n    finally:\n        reader.close()\n    report[\'requests\']=reader.requests\n    report[\'public_session\']={\'mode\':\'fresh_anonymous_in_memory\',\'cookies_received_count\':reader.session_cookie_count,\n                              \'authentication_cookies_discarded\':reader.auth_cookies_discarded,\n                              \'cookies_imported\':False,\'session_closed\':reader._client is None}\n    report[\'transport_policy\']={\'max_requests\':9,\'max_extra_attempts\':2,\'read_timeout_seconds\':30,\'retry_scope\':\'public_page_config_scripts_read_timeout_only\',\'retries_used\':reader.retries_used}\n    report[\'completion_note\']=\'Public data/document check only. Volume, freshness, all attachments and automatic OCR/LLM handoff still require validation.\'\n    return report\n\n\ndef main():\n    signal.signal(signal.SIGALRM,lambda *_: (_ for _ in ()).throw(SystemExit(\'SBER_CARD_CHECK_TIMEOUT: incomplete; request budget stopped; no business tasks\')))\n    signal.alarm(210)\n    print(\'SBER_PURCHASE_READ_CHECK_BEGIN: one known public purchase; up to two document samples\',flush=True)\n    print(json.dumps(probe(),ensure_ascii=False,indent=2,default=str),flush=True)\n    signal.alarm(0)\n    print(\'READ_ONLY_SBER_CARD: no saved files, DB edits, tasks, OCR, LLM, authentication, installs or restarts\',flush=True)\n\n\nif __name__==\'__main__\':main()\n'

def check_sber_card():
 services=run(['docker','compose','ps','--services','--status','running'],capture_output=True,text=True,timeout=20).stdout.splitlines()
 if 'app' not in services:raise SystemExit('APP_NOT_RUNNING: no services started; Sber card not checked')
 try:
  run(['docker','compose','exec','-T','app','python','-'],input=SBER_CARD_CHECK,text=True,timeout=240)
 except (subprocess.TimeoutExpired,subprocess.CalledProcessError,OSError) as exc:
  raise SystemExit('SBER_CARD_CHECK_INCOMPLETE: '+type(exc).__name__+'; no automatic retry or business tasks')


QUEUE_AUDIT = '"""Observation only. No business task submissions, acknowledgements or DB writes."""\nimport ast,base64,json,re,signal\nfrom datetime import datetime,timezone\nfrom pathlib import Path\nfrom uuid import UUID\n\nLIMIT_KEYS=20000\nLIMIT_MESSAGES=2000\nLIMIT_PREVIEW=200\n\ndef val(x):return getattr(x,\'value\',x)\ndef uuid_text(x):\n try:return str(UUID(str(x)))\n except (ValueError,TypeError,AttributeError):return None\n\ndef args_value(x):\n if isinstance(x,str):\n  if len(x)>65536:return None\n  try:return ast.literal_eval(x)\n  except (ValueError,SyntaxError,MemoryError,RecursionError):return None\n return x\n\ndef task_brief(task):\n name=str(task.get(\'name\') or task.get(\'task\') or task.get(\'type\') or \'\')[:240]\n args=args_value(task.get(\'args\',[]));kwargs=args_value(task.get(\'kwargs\',{}))\n tid=(kwargs or {}).get(\'tender_id\') if isinstance(kwargs,dict) else None\n if tid is None and isinstance(args,(list,tuple)) and args and name.endswith((\'.analyze_tender\',\'.process_tender_documents\')):tid=args[0]\n return {\'task_id\':uuid_text(task.get(\'id\')),\'task_name\':name,\n         \'llm_task\':bool(re.search(r\'scoring|analyz|llm|extraction\',name,re.I)),\n         \'tender_id\':uuid_text(tid)}\n\ndef decode(raw):\n if isinstance(raw,(str,bytes)):\n  if len(raw)>2_000_000:raise ValueError(\'message_size\')\n  raw=json.loads(raw)\n if isinstance(raw,list) and len(raw)==3 and isinstance(raw[0],dict):raw=raw[0]\n if not isinstance(raw,dict):raise ValueError(\'envelope\')\n headers=raw.get(\'headers\') or {};prop=raw.get(\'properties\') or {}\n if raw.get(\'content-type\')!=\'application/json\' or headers.get(\'compression\'):raise ValueError(\'encoding\')\n body=raw.get(\'body\')\n if prop.get(\'body_encoding\')==\'base64\':body=base64.b64decode(body,validate=True)\n if isinstance(body,(str,bytes)):body=json.loads(body)\n if isinstance(body,list) and len(body)>=2:\n  task={\'id\':headers.get(\'id\'),\'task\':headers.get(\'task\'),\'args\':body[0],\'kwargs\':body[1]}\n elif isinstance(body,dict):task={**body,\'id\':headers.get(\'id\') or body.get(\'id\'),\'task\':headers.get(\'task\') or body.get(\'task\')}\n else:raise ValueError(\'body\')\n if not task.get(\'task\'):raise ValueError(\'not_task\')\n return task_brief(task)\n\ndef scan_lists(client,prefix):\n # Physical keys via a plain Redis client: no accidental double-prefix or\n # unprefixed HSCAN/LRANGE when Kombu uses global_keyprefix.\n prefix=prefix.encode() if isinstance(prefix,str) else prefix\n pattern=bytes().join((b\'\\\\\'+bytes([b]) if b in b\'*?[]\\\\\' else bytes([b])) for b in prefix)+b\'*\'\n result={};seen=set()\n for key in client.scan_iter(match=pattern,count=100):\n  if key in seen:continue\n  seen.add(key)\n  if len(seen)>LIMIT_KEYS:raise ValueError(\'key_scan_limit\')\n  if client.type(key) in (\'list\',b\'list\'):result[key]=int(client.llen(key))\n return result\n\ndef conclusion(out):\n b=out.get(\'broker\',{});w=out.get(\'workers\',{})\n observed=any(v for v in b.get(\'list_counts\',{}).values()) or b.get(\'unacked_count\',0)>0 or b.get(\'unacked_index_count\',0)>0\n observed=observed or any(n for m in (\'active\',\'reserved\',\'scheduled\') for n in (w.get(m,{}).get(\'counts\') or {}).values())\n if observed:return \'TASKS_OR_MESSAGES_PRESENT\'\n if b.get(\'complete\') and out.get(\'worker_observation_complete\'):return \'NO_TASKS_OBSERVED_IN_SNAPSHOT\'\n return \'EMPTY_NOT_CONFIRMED\'\n\ndef main():\n from app.workers.celery_app import celery_app\n signal.signal(signal.SIGALRM,lambda *_: (_ for _ in ()).throw(SystemExit(\'QUEUE_AUDIT_TIMEOUT: EMPTY_NOT_CONFIRMED\')))\n signal.alarm(85)\n out={\'checked_at_utc\':datetime.now(timezone.utc).isoformat(),\'version\':\'queue-observation-20261026-1\',\'workers\':{},\'tasks\':[],\'errors\':[],\n      \'note\':\'Momentary non-atomic observation. Beat can enqueue later. DB failed/ingested and discovery backlog are not broker queues. No business task submissions or removals.\'}\n print(\'QUEUE_AUDIT_BEGIN: configured application broker and DB; no marketplace HTTP, OCR or LLM\',flush=True)\n names=set(celery_app.amqp.queues.keys());names.add(celery_app.conf.task_default_queue or \'celery\')\n sets=[];total_seen=0;ids=set()\n def add(task,location):\n  nonlocal total_seen\n  total_seen+=1\n  if task.get(\'tender_id\'):ids.add(task[\'tender_id\'])\n  if len(out[\'tasks\'])<LIMIT_PREVIEW:out[\'tasks\'].append({**task,\'location\':location})\n for method in (\'active\',\'reserved\',\'scheduled\',\'active_queues\'):\n  try:\n   reply=getattr(celery_app.control.inspect(timeout=3),method)()\n   out[\'workers\'][method]={\'responded\':bool(reply),\'counts\':{k:len(v or []) for k,v in (reply or {}).items()}}\n   sets.append(set(reply or {}))\n   for worker,rows in (reply or {}).items():\n    for row in rows or []:\n     if method==\'active_queues\':\n      if row.get(\'name\'):names.add(row[\'name\'])\n     else:add(task_brief(row.get(\'request\',row)),method+\':\'+worker)\n  except Exception as exc:\n   sets.append(set());out[\'workers\'][method]={\'responded\':False,\'error_type\':type(exc).__name__}\n expected=globals().get(\'EXPECTED_WORKER_SERVICES\',[])\n out[\'expected_running_worker_services\']=expected\n expected_hosts=set(globals().get(\'EXPECTED_WORKER_HOSTNAMES\',[]))\n out[\'expected_worker_hostnames\']=sorted(expected_hosts)\n responded_hosts={name.rsplit(\'@\',1)[-1] for name in (sets[0] if sets else set())}\n out[\'worker_observation_complete\']=bool(expected and expected_hosts and sets and all(s==sets[0] for s in sets) and expected_hosts.issubset(responded_hosts))\n try:\n  import redis\n  with celery_app.connection_for_read() as conn:\n   conn.ensure_connection(max_retries=0);channel=conn.channel()\n   try:\n    if conn.transport.driver_type!=\'redis\':raise ValueError(\'unsupported_broker_transport\')\n    pool=channel.client.connection_pool\n    options=dict(pool.connection_kwargs);options.update(socket_timeout=5,socket_connect_timeout=5)\n    raw=redis.Redis(connection_pool=redis.ConnectionPool(connection_class=pool.connection_class,**options))\n    prefix=getattr(channel,\'global_keyprefix\',\'\') or \'\'\n    prefix=prefix.encode() if isinstance(prefix,str) else prefix\n    known={prefix+channel._q_for_pri(name,priority).encode() for name in names for priority in channel.priority_steps}\n    as_bytes=lambda x:x.encode() if isinstance(x,str) else x\n    u=prefix+as_bytes(channel.unacked_key);ui=prefix+as_bytes(channel.unacked_index_key)\n    before=scan_lists(raw,prefix);counts={k:int(raw.llen(k)) for k in known}\n    counts.update(before)\n    unacked_count=int(raw.hlen(u));index_count=int(raw.zcard(ui));scanned=0;unparsed=0\n    for key,count in sorted(counts.items()):\n     take=min(count,max(0,LIMIT_MESSAGES-scanned))\n     for start in range(0,take,40):\n      for message in raw.lrange(key,start,min(start+39,take-1)):\n       scanned+=1\n       try:add(decode(message),\'redis_ready:\'+key.decode(\'utf-8\',\'backslashreplace\'))\n       except Exception:unparsed+=1\n    us=0;seen_tags=set()\n    for tag,message in raw.hscan_iter(u,count=100):\n     if tag in seen_tags:continue\n     seen_tags.add(tag)\n     if us>=LIMIT_MESSAGES:break\n     us+=1\n     try:add(decode(message),\'redis_unacked\')\n     except Exception:unparsed+=1\n    after=scan_lists(raw,prefix)\n    # Remove empty keys from comparison; drained keys may be deleted by Redis.\n    stable={k:v for k,v in before.items() if v}=={k:v for k,v in after.items() if v}\n    stable=stable and unacked_count==int(raw.hlen(u)) and index_count==int(raw.zcard(ui))\n    remaining=max(0,sum(counts.values())-scanned)+max(0,unacked_count-us)\n    out[\'broker\']={\'list_counts\':{k.decode(\'utf-8\',\'backslashreplace\'):v for k,v in counts.items()},\'unacked_count\':unacked_count,\n      \'unacked_index_count\':index_count,\'messages_decoded_or_attempted\':scanned+us,\'unparsed\':unparsed,\'unread_at_least\':remaining,\n      \'counts_stable_between_reads\':stable,\'complete\':stable and not unparsed and not remaining and unacked_count==index_count,\n      \'unknown_list_keys\':[k.decode(\'utf-8\',\'backslashreplace\') for k in before if k not in known]}\n   finally:\n    if \'raw\' in locals():raw.connection_pool.disconnect()\n    channel.close()\n except Exception as exc:out[\'broker\']={\'complete\':False,\'error_type\':type(exc).__name__}\n try:\n  from sqlalchemy import select,func,text\n  from app.db.session import SyncSessionLocal\n  from app.models.database import Tender\n  with SyncSessionLocal() as db:\n   db.execute(text(\'SET TRANSACTION READ ONLY\'));db.execute(text("SET LOCAL statement_timeout = \'15000\'"))\n   counts=db.execute(select(Tender.source,Tender.processing_status,func.count()).group_by(Tender.source,Tender.processing_status)).all()\n   out[\'db_state_counts\']=[{\'source\':s,\'processing\':val(p),\'count\':n} for s,p,n in counts]\n   out[\'db_pending_total\']=sum(n for s,p,n in counts if val(p) in (\'analyzing\',\'documents_pending\',\'documents_ready\'))\n   from app.models.database import ProcessingStatus\n   states=[x for x in ProcessingStatus if val(x) in (\'analyzing\',\'documents_pending\',\'documents_ready\')]\n   rows=db.execute(select(Tender).where(Tender.processing_status.in_(states)).order_by(Tender.updated_at).limit(201)).scalars().all()\n   out[\'db_pending_preview_truncated\']=len(rows)>200\n   out[\'db_pending_preview\']=[{\'id\':str(t.id),\'source\':t.source,\'external_id\':t.external_id,\'processing\':val(t.processing_status),\'analysis_done\':t.analysis_done,\'updated_at\':str(t.updated_at),\'task_observed_for_tender\':str(t.id) in ids} for t in rows[:200]]\n   linked=db.execute(select(Tender).where(Tender.id.in_(sorted(ids)))).scalars().all() if ids else []\n   out[\'queued_tenders\']=[{\'id\':str(t.id),\'source\':t.source,\'external_id\':t.external_id,\'title\':t.title,\'processing\':val(t.processing_status),\'analysis_done\':t.analysis_done} for t in linked]\n   db.rollback()\n except Exception as exc:out[\'errors\'].append({\'phase\':\'db\',\'error_type\':type(exc).__name__})\n out[\'db_note\']=\'DB states are not queues. No matching observed task does not prove an orphan; messages may be unread, unmapped or in transit.\'\n out[\'task_observations\']=total_seen;out[\'task_preview_truncated\']=total_seen>len(out[\'tasks\'])\n out[\'queue_result\']=conclusion(out)\n out[\'finished_at_utc\']=datetime.now(timezone.utc).isoformat()\n print(json.dumps(out,ensure_ascii=False,indent=2,default=str),flush=True)\n print(\'QUEUE_RESULT:\',out[\'queue_result\'],flush=True)\n print(\'DB_PENDING_RESULT:\',(\'PENDING_STATES_PRESENT\' if out[\'db_pending_total\'] else \'NO_PENDING_STATES\') if \'db_pending_total\' in out and not out[\'errors\'] else \'UNKNOWN\',flush=True)\n signal.alarm(0)\n print(\'READ_ONLY: no DB edits, task submission, queue purge/revoke, OCR, LLM or notifications; worker inspect uses control messages only\',flush=True)\n\nif __name__==\'__main__\':main()\n'
PUBLIC_NEXT = 'import argparse, ast, hashlib, html, io, ipaddress, json, os, re, socket, ssl\n\nimport subprocess, sys, tempfile, time, unittest, urllib.request, urllib.error\n\nimport zipfile\n\nfrom datetime import datetime, timezone\n\nfrom html.parser import HTMLParser\n\nfrom pathlib import Path\n\nfrom urllib.parse import urlsplit, urljoin, urlencode, quote, parse_qsl\n\nSBER_SCRIPTS=(\'/CoreApl/core.js\',\'/CoreApl/core_ext.js\',\'/js/apl/aplFormScript.js\')\n\nSECRET=re.compile(r\'token|password|passwd|secret|authorization|cookie|session|csrf|api.?key\',re.I)\n\nCHALLENGE=re.compile(r\'verify you are human|anti.bot verification|проверка.{0,20}робот|подтвердите.{0,30}человек|access denied|checking your browser\',re.I)\n\nCARDPATH=re.compile(r\'/(?:trades|tenders?|procedures?|purchases?)/[^?#]*\\d|PurchaseView/|view\\.php\\?ID=|tender-\\d\',re.I)\n\nTARGET=re.compile(r\'алюм|\\bАМ[гц]\\d*|\\bАД(?:0|1|31)\\b\',re.I)\n\nLINKWORDS=re.compile(r\'тендер|закуп|поставщик|торги|procurement|tender|purchase|supplier\',re.I)\n\nDOCUMENT=re.compile(r\'\\.(?:pdf|docx?|xlsx?|zip|rar|7z|tiff?)(?:\\?|$)|DocumentView|/files?/|imported-file\',re.I)\n\nclass Stop(Exception): pass\n\ndef public_url(url):\n p=urlsplit(url)\n if p.username or p.password:return \'[credentials-in-url]\'\n return p._replace(query=urlencode([(k,v) for k,v in parse_qsl(p.query) if not SECRET.search(k)]),fragment=\'\').geturl()\n\ndef safe_url(url,hosts):\n try:\n  p=urlsplit(url)\n  return (p.scheme==\'https\' and p.hostname in hosts and not p.username and not p.password\n    and p.port in (None,443) and not p.fragment\n    and not any(SECRET.search(k) for k,v in parse_qsl(p.query))\n    and not re.search(r\'/(?:login|logout|auth|captcha|register)(?:/|\\.|$)\',p.path,re.I))\n except ValueError:return False\n\ndef scrub(text):\n # Public sources only; never save response headers or cookies.\n text=re.sub(r\'(?is)<input\\b(?=[^>]*\\btype=["\\\']?hidden\\b)[^>]*>\', \'<!-- hidden input omitted -->\',text)\n text=re.sub(r\'(?i)((?:[\\w]*token|password|secret|authorization|cookie|api_key)\\s*["\\\']?\\s*[:=]\\s*)["\\\'][^"\\\']*["\\\']\',r\'\\1"[redacted]"\',text)\n return text\n\nclass Page(HTMLParser):\n def __init__(self,base):\n  super().__init__(convert_charrefs=True);self.base=base;self.links=[];self.scripts=[];self.forms=[]\n  self.text=[];self.title=[];self.skip=0;self.intitle=False;self.a=None;self.form=None;self.password=False\n def handle_starttag(self,tag,attrs):\n  d=dict(attrs)\n  if tag in (\'script\',\'style\'):self.skip+=1\n  if tag==\'script\' and d.get(\'src\'):self.scripts.append(urljoin(self.base,d[\'src\']))\n  if tag==\'title\':self.intitle=True\n  if tag==\'a\':self.a=[urljoin(self.base,d.get(\'href\',\'\')),\'\']\n  if tag==\'form\':self.form={\'action\':urljoin(self.base,d.get(\'action\') or self.base),\'method\':d.get(\'method\',\'get\').lower(),\'fields\':[],\'password\':False}\n  if tag==\'input\':\n   if d.get(\'type\',\'\').lower()==\'password\':\n    self.password=True\n    if self.form:self.form[\'password\']=True\n   if self.form and d.get(\'name\'):self.form[\'fields\'].append({\'name\':d[\'name\'],\'type\':d.get(\'type\',\'text\').lower()})\n def handle_endtag(self,tag):\n  if tag in (\'script\',\'style\'):self.skip=max(0,self.skip-1)\n  if tag==\'title\':self.intitle=False\n  if tag==\'a\' and self.a:self.links.append(self.a);self.a=None\n  if tag==\'form\' and self.form:self.forms.append(self.form);self.form=None\n def handle_data(self,data):\n  if not self.skip:\n   self.text.append(data)\n   if self.a:self.a[1]+=data\n   if self.intitle:self.title.append(data)\n def summary(self):\n  title=\' \'.join(self.title).strip();visible=\' \'.join(self.text)\n  challenge=bool(CHALLENGE.search(title+\' \'+visible[:16000]))\n  return {\'title\':title,\'visible_characters\':len(visible),\'access_challenge\':challenge,\'login_form_present\':self.password,\n   \'keyword_mentions_in_page\':sorted(set(m.group(0) for m in TARGET.finditer(visible)))[:20],\n   \'forms\':self.forms,\'scripts\':self.scripts,\n   \'procurement_links\':[{\'url\':u,\'label\':t.strip()[:250]} for u,t in self.links if LINKWORDS.search(t+\' \'+u)][:60],\n   \'candidate_links\':[{\'url\':u,\'title\':t.strip()[:250],\'eligibility\':\'unverified\'} for u,t in self.links if CARDPATH.search(u) and TARGET.search(t)][:12],\n   \'document_links\':[{\'url\':u,\'label\':t.strip()[:200],\'identity_verified\':False} for u,t in self.links if DOCUMENT.search(u)][:30]}\n\nclass NoRedirect(urllib.request.HTTPRedirectHandler):\n def redirect_request(self,*args,**kwargs):return None\n\nclass Reader:\n def __init__(self,directory):\n  self.directory=directory;self.requests=0;self.total=0;self.started=time.monotonic();self.evidence=[]\n  self.opener=urllib.request.build_opener(urllib.request.ProxyHandler({}),NoRedirect(),urllib.request.HTTPSHandler(context=ssl.create_default_context()))\n def get(self,url,hosts,source,limit=3_000_000,_hops=0,_visited=()):\n  if not safe_url(url,hosts):raise Stop(\'unapproved_or_interactive_url\')\n  if url in _visited:raise Stop(\'redirect_loop_stop:\'+public_url(url))\n  _visited=(*_visited,url)\n  if self.requests>=15 or self.total>=80_000_000 or time.monotonic()-self.started>260:raise Stop(\'global_budget_exhausted\')\n  # Refuse local/private destinations even if DNS changes unexpectedly.\n  for addr in socket.getaddrinfo(urlsplit(url).hostname,443,type=socket.SOCK_STREAM):\n   if not ipaddress.ip_address(addr[4][0]).is_global:raise Stop(\'non_public_dns\')\n  self.requests+=1;start=time.monotonic()\n  req=urllib.request.Request(url,headers={\'User-Agent\':\'TenderAssistant-Audit/1.0\',\'Accept-Encoding\':\'identity\'})\n  try:r=self.opener.open(req,timeout=8)\n  except urllib.error.HTTPError as exc:\n   if 300<=exc.code<400:\n    target=urljoin(url,exc.headers.get(\'Location\',\'\'))\n    if _hops>=5 or not safe_url(target,hosts):raise Stop(\'redirect_requires_review:\'+public_url(target))\n    return self.get(target,hosts,source,limit,_hops+1,_visited)\n   raise Stop(\'http_\'+str(exc.code)) from None\n  with r:\n   body=bytearray()\n   while True:\n    chunk=r.read(65536)\n    if not chunk:break\n    self.total+=len(chunk);body.extend(chunk)\n    if len(body)>limit or self.total>80_000_000:raise Stop(\'body_limit_incomplete\')\n    if time.monotonic()-start>45:raise Stop(\'body_timeout_incomplete\')\n   if not body:raise Stop(\'empty_response\')\n   if r.headers.get(\'Content-Encoding\',\'identity\').lower() not in (\'\',\'identity\'):raise Stop(\'unexpected_content_encoding\')\n   ctype=r.headers.get(\'Content-Type\',\'\')\n   if not any(k in ctype.lower() for k in (\'html\',\'javascript\',\'json\',\'text/\')):raise Stop(\'unexpected_non_text_response\')\n   encoding=r.headers.get_content_charset() or \'utf-8\'\n   try:text=body.decode(encoding)\n   except (UnicodeError,LookupError):\n    try:text=body.decode(\'cp1251\')\n    except UnicodeError:raise Stop(\'unknown_encoding\')\n  content=scrub(text);name=source+\'-\'+str(self.requests)+(\'.js\' if \'javascript\' in ctype or urlsplit(url).path.endswith(\'.js\') else \'.html\')\n  (self.directory/name).write_text(content,encoding=\'utf-8\')\n  row={\'url\':public_url(url),\'http\':200,\'bytes\':len(body),\'content_type\':ctype,\n       \'response_sha256\':hashlib.sha256(body).hexdigest(),\'evidence_file\':name,\n       \'saved_sha256\':hashlib.sha256(content.encode()).hexdigest(),\'sanitized\':True,\'complete\':True}\n  self.evidence.append(row);return text,row\n\ndef scripts_for(page,sber=False):\n if sber:\n  return [next((u for u in page.scripts if urlsplit(u).path==p),None) for p in SBER_SCRIPTS]\n # Save complete application bundles; third-party chat/analytics are excluded.\n urls=[u for u in page.scripts if re.search(r\'\\.js(?:\\?|$)\',u) and not re.search(r\'jquery|analytics|metrika|chat|polyfills|runtime|bootstrap|captcha\',u,re.I)]\n return sorted(dict.fromkeys(urls),key=lambda u:not bool(re.search(r\'main|app|bundle|core\',urlsplit(u).path,re.I)))[:2]\n\nSEEDS={\n \'sberbank_ast\':\'https://utp.sberbank-ast.ru/build/apl_config.json\',\n \'tatneft\':\'https://etp.tatneft.ru/pls/tzp/f?p=220:1\',\n \'pik\':\'https://etp.pik.ru/trades\',\n \'akvilon\':\'https://etp.group-akvilon.ru/\',\n \'level\':\'https://etp.level.ru/frame/index.html\',\n}\n\ndef challenge_body(text):\n # Ordinary CAPTCHA configuration/widgets in an otherwise public app are not a refusal.\n page=Page(\'https://diagnostic.invalid/\');page.feed(text)\n visible=\' \'.join(page.title+page.text)[:30000]\n if CHALLENGE.search(visible):return True\n if re.search(r\'__js_p_|get_jhash\',text[:30000],re.I):return True\n return bool(re.search(r\'введите\\s+(?:код\\s+с\\s+картинки|капчу)|подтвердите,?\\s+что\\s+вы\\s+не\\s+робот|complete\\s+the\\s+captcha|security\\s+verification\\s+required\',visible,re.I))\n\ndef console_excerpt(text):\n text=scrub(text)\n text=re.sub(r\'(?i)([\\w]*(?:token|secret|password|authorization|cookie|session|api[_-]?key)[\\w]*["\\\']?\\s*[:=]\\s*)["\\\'][^"\\\']*["\\\']\',r\'\\1"[redacted]"\',text)\n text=re.sub(r\'https?://[^\\s"\\\'<>]+\',lambda m:public_url(m.group()),text)\n return text\n\ndef contract_evidence(text):\n # Quoted source excerpts only: downloaded JavaScript is never executed.\n patterns=((\'graphql_read\',r\'\\bquery\\s+(?:trades|getTradeInfo|[A-Za-z_]*(?:Trade|Tender|Purchase)[A-Za-z_]*)\\s*[({]\'),\n           (\'transport\',r\'/graphql|API_BASE_URL|Processing/main|api/tender/tenders|tradeQueryDto\'),\n           (\'documents\',r\'getTradeInfo|originalFileName|attachmentFiles|tradeDocuments\'))\n result=[];spans=[]\n for label,pattern in patterns:\n  for m in list(re.finditer(pattern,text,re.I))[:4]:\n   if any(a<=m.start()<b for a,b in spans):continue\n   a=max(0,m.start()-100);b=min(len(text),m.end()+1050);spans.append((a,b))\n   result.append({\'kind\':label,\'offset\':m.start(),\'excerpt\':console_excerpt(text[a:b])})\n   if len(result)>=10:return result\n return result\n\ndef console_row(row):\n result={k:row[k] for k in (\'source\',\'status\',\'requests\',\'errors\',\'pipeline_ready\')}\n for k in (\'api_base_url\',\'contract_evidence\',\'contract_markers\'): \n  if k in row:result[k]=row[k]\n if row.get(\'page_summary\'):\n  v=row[\'page_summary\']\n  result[\'page_summary\']={k:v.get(k) for k in (\'title\',\'visible_characters\',\'access_challenge\',\'login_form_present\',\'forms\',\'candidate_links\')}\n for name in (\'page\',\'script_evidence\'):\n  values=row.get(name)\n  if values:\n   result[name]=[{k:x.get(k) for k in (\'url\',\'http\',\'bytes\',\'saved_sha256\',\'complete\')} for x in (values if isinstance(values,list) else [values])]\n return result\n\ndef check_one(source,reader):\n url=SEEDS[source];hosts={urlsplit(url).hostname};before=reader.requests\n row={\'source\':source,\'status\':\'not_checked\',\'pipeline_ready\':False,\'requests\':0,\'errors\':[],\n      \'keyword_search\':\'not_verified\',\'documents\':\'not_verified\',\'llm\':\'not_run\'}\n try:\n  text,ev=reader.get(url,hosts,source);row[\'page\']=ev\n  if challenge_body(text):raise Stop(\'access_challenge_stop\')\n  if source==\'sberbank_ast\':\n   config=json.loads(text)\n   if not isinstance(config,dict):raise Stop(\'config_shape\')\n   base=config.get(\'API_BASE_URL\')\n   row[\'config_keys\']=sorted(k for k in config if not SECRET.search(k))\n   row[\'api_base_url\']=public_url(base) if isinstance(base,str) else None\n   row[\'status\']=\'production_config_observed_adapter_not_verified\'\n   if not isinstance(base,str):row[\'status\']=\'api_base_not_present\'\n   elif re.search(r\'psi\\.|test|localhost\',base,re.I):row[\'status\']=\'test_environment_config_requires_review\'\n   # Do not call API_BASE_URL: read operations/parameters are not yet verified.\n  else:\n   page=Page(ev[\'url\']);page.feed(text);info=page.summary();row[\'page_summary\']=info\n   if info[\'access_challenge\']:raise Stop(\'access_challenge_stop\')\n   row[\'script_evidence\']=[]\n   if source in (\'pik\',\'akvilon\',\'level\'):\n    candidates=[u for u in page.scripts if re.search(r\'/main[.-][^/]+\\.js(?:\\?|$)\',u)]\n    if len(candidates)!=1:raise Stop(\'main_script_not_unique_in_current_page\')\n    script=candidates[0]\n    if not safe_url(script,hosts):raise Stop(\'main_script_external_or_interactive\')\n    body,script_ev=reader.get(script,hosts,source,20_000_000)\n    if \'html\' in script_ev[\'content_type\'].lower() or re.match(r\'\\s*<(?:html|!doctype)\',body,re.I):raise Stop(\'script_returned_html\')\n    row[\'script_evidence\'].append(script_ev)\n    row[\'contract_evidence\']=contract_evidence(body)\n    row[\'contract_markers\']={m:body.count(m) for m in (\'graphql\',\'query \',\'operationName\',\'tradeSearch\',\'searchTrades\',\'GetTrade\',\'positions\',\'documents\')}\n    row[\'status\']=\'complete_bundle_collected_adapter_not_verified\'\n   else:row[\'status\']=\'public_page_collected_registry_not_verified\'\n except Exception as exc:\n  row[\'status\']=\'incomplete\';row[\'errors\'].append(str(exc) if isinstance(exc,Stop) else type(exc).__name__)\n finally:row[\'requests\']=reader.requests-before\n return row\n\ndef main():\n stamp=datetime.now(timezone.utc).strftime(\'%Y%m%dT%H%M%S\')\n directory=Path(tempfile.mkdtemp(prefix=\'tender-next-\'+stamp+\'-\',dir=Path.cwd()))\n reader=Reader(directory)\n report={\'version\':\'targeted-public-evidence-20261026-2-console\',\'checked_at\':datetime.now(timezone.utc).isoformat(),\n         \'sources\':[], \'scope\':\'GET only; missing evidence from prior audit; no adapter installation or business tasks\'}\n for source in SEEDS:\n  print(\'CHECKING:\',source,flush=True)\n  row=check_one(source,reader);report[\'sources\'].append(row)\n  print(json.dumps(console_row(row),ensure_ascii=False,indent=2),flush=True)\n report[\'evidence\']=reader.evidence\n (directory/\'report.json\').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding=\'utf-8\')\n archive=directory.with_suffix(\'.zip\')\n with zipfile.ZipFile(archive,\'w\',zipfile.ZIP_DEFLATED) as z:\n  for p in sorted(directory.iterdir()):\n   if p.is_file():z.write(p,p.name)\n print(\'REPORT:\',directory/\'report.json\',flush=True)\n print(\'ARCHIVE:\',archive,flush=True)\n print(\'CONSOLE_REPORT_READY: copy this output; downloading the archive is optional\',flush=True)\n print(\'PUBLIC_CHECK_FINISHED: diagnostic files only; no DB, queues, documents, OCR, LLM, installation or restarts\',flush=True)\n\nif __name__==\'__main__\':main()\n'
PREFLIGHT_TESTS = 'import base64,contextlib,io,json,types,unittest\nfrom unittest.mock import patch,MagicMock\n\nq={};exec(compile(QUEUE_AUDIT,\'embedded_queue_audit\',\'exec\'),q)\np={};exec(compile(PUBLIC_NEXT,\'embedded_public_next\',\'exec\'),p)\nTASK=\'7e13fd7c-874f-4445-8159-4a2c1482468d\'\nTENDER=\'0680c799-2720-4aae-8cc0-9b5a04e0db82\'\n\ndef envelope():\n return {\'content-type\':\'application/json\',\'properties\':{\'body_encoding\':\'base64\'},\n \'headers\':{\'id\':TASK,\'task\':\'app.workers.tasks_scoring.analyze_tender\'},\n \'body\':base64.b64encode(json.dumps([[TENDER],{},{}]).encode()).decode()}\n\nclass Tests(unittest.TestCase):\n def test_decode_v2_unacked(self):\n  for data in (envelope(),[envelope(),\'celery\',\'celery\']):\n   out=q[\'decode\'](json.dumps(data));self.assertEqual(out[\'tender_id\'],TENDER);self.assertTrue(out[\'llm_task\']);self.assertEqual(out[\'task_id\'],TASK)\n def test_decode_v1(self):\n  d=envelope();d[\'headers\']={};d[\'body\']=base64.b64encode(json.dumps({\'task\':\'app.workers.tasks_scoring.analyze_tender\',\'id\':TASK,\'args\':[TENDER],\'kwargs\':{}}).encode()).decode()\n  self.assertEqual(q[\'decode\'](d)[\'tender_id\'],TENDER)\n def test_non_json_never_deserialized(self):\n  for kind in (\'application/x-python-serialize\',\'application/x-yaml\'):\n   d=envelope();d[\'content-type\']=kind\n   with self.assertRaises(ValueError):q[\'decode\'](d)\n  d=envelope();d[\'headers\'][\'compression\']=\'application/x-gzip\'\n  with self.assertRaises(ValueError):q[\'decode\'](d)\n def test_inspect_args_and_secrets(self):\n  d=q[\'task_brief\']({\'id\':TASK,\'name\':\'app.workers.tasks_scoring.analyze_tender\',\'args\':repr((TENDER,)), \'kwargs\':{\'token\':\'do-not-print\'}})\n  self.assertEqual(d[\'tender_id\'],TENDER);self.assertNotIn(\'do-not-print\',json.dumps(d))\n  self.assertIsNone(q[\'args_value\']("__import__(\'os\').system(\'false\')"))\n def test_conclusions(self):\n  c=q[\'conclusion\'];self.assertEqual(c({}),\'EMPTY_NOT_CONFIRMED\')\n  base={\'broker\':{\'complete\':True,\'list_counts\':{}},\'worker_observation_complete\':True}\n  self.assertEqual(c(base),\'NO_TASKS_OBSERVED_IN_SNAPSHOT\')\n  base[\'broker\'][\'unacked_index_count\']=1\n  self.assertEqual(c(base),\'TASKS_OR_MESSAGES_PRESENT\')\n  self.assertEqual(c({\'workers\':{\'active\':{\'counts\':{\'w\':1}}}}),\'TASKS_OR_MESSAGES_PRESENT\')\n  self.assertEqual(c({\'broker\':{\'complete\':False}}),\'EMPTY_NOT_CONFIRMED\')\n def test_scan_prefix_escaped(self):\n  r=MagicMock();r.scan_iter.return_value=[b\'x[*]celery\'];r.type.return_value=b\'list\';r.llen.return_value=1\n  self.assertEqual(q[\'scan_lists\'](r,b\'x[*]\'),{b\'x[*]celery\':1})\n  self.assertEqual(r.scan_iter.call_args.kwargs[\'match\'],b\'x\\\\[\\\\*\\\\]*\')\n def fake_main(self,ready=0,unacked=0,respond=True,changing=False,unparsed=False,db_ok=False):\n  prefix=b\'app:\';key=prefix+b\'celery\';u=prefix+b\'unacked\';ui=prefix+b\'unacked_index\'\n  raw=MagicMock();raw.type.return_value=b\'list\'\n  raw.scan_iter.side_effect=[[key] if ready else [],[key] if ready or changing else []]\n  raw.llen.side_effect=lambda k:ready if k==key else 0\n  raw.hlen.side_effect=lambda k:unacked if k==u else (_ for _ in ()).throw(AssertionError(k))\n  raw.zcard.side_effect=lambda k:unacked if k==ui else (_ for _ in ()).throw(AssertionError(k))\n  msg=b\'invalid\' if unparsed else json.dumps(envelope()).encode()\n  raw.lrange.side_effect=lambda k,a,b:[msg]*(min(b+1,ready)-a) if k==key else []\n  raw.hscan_iter.side_effect=lambda k,count:[(b\'tag\',json.dumps([envelope(),\'celery\',\'celery\']))] if unacked and k==u else []\n  channel=MagicMock();channel.global_keyprefix=\'app:\';channel.priority_steps=[0,3,6,9]\n  channel._q_for_pri.side_effect=lambda name,pri:name+((\'\\x06\\x16\'+str(pri)) if pri else \'\')\n  channel.unacked_key=\'unacked\';channel.unacked_index_key=\'unacked_index\'\n  channel.client.connection_pool.connection_kwargs={\'host\':\'configured-secret-host\'}\n  conn=MagicMock();conn.__enter__.return_value=conn;conn.channel.return_value=channel;conn.transport.driver_type=\'redis\'\n  app=MagicMock();app.connection_for_read.return_value=conn;app.amqp.queues={\'celery\':object()};app.conf.task_default_queue=\'celery\'\n  ins=app.control.inspect.return_value\n  for method in (\'active\',\'reserved\',\'scheduled\',\'active_queues\'):getattr(ins,method).return_value={\'worker\':[]} if respond else None\n  redis=types.ModuleType(\'redis\');redis.Redis=MagicMock(return_value=raw);redis.ConnectionPool=MagicMock()\n  mod=types.ModuleType(\'app.workers.celery_app\');mod.celery_app=app\n  # Force DB unavailable and ensure broker audit still returns safely.\n  sql=types.ModuleType(\'sqlalchemy\')\n  imports={\'app\':types.ModuleType(\'app\'),\'app.workers\':types.ModuleType(\'app.workers\'),\'app.workers.celery_app\':mod,\'redis\':redis,\'sqlalchemy\':sql}\n  if db_ok:\n   sql.select=MagicMock();sql.func=MagicMock();sql.text=lambda x:x\n   db=MagicMock();db.__enter__.return_value=db;db.execute.return_value.all.return_value=[];db.execute.return_value.scalars.return_value.all.return_value=[]\n   session=types.ModuleType(\'app.db.session\');session.SyncSessionLocal=lambda:db\n   models=types.ModuleType(\'app.models.database\');models.Tender=MagicMock();models.ProcessingStatus=[]\n   imports.update({\'app.db\':types.ModuleType(\'app.db\'),\'app.db.session\':session,\'app.models\':types.ModuleType(\'app.models\'),\'app.models.database\':models})\n  output=io.StringIO();q[\'EXPECTED_WORKER_SERVICES\']=[\'celery_worker\'];q[\'EXPECTED_WORKER_HOSTNAMES\']=[\'worker\']\n  with patch.dict(\'sys.modules\',imports),patch.object(q[\'signal\'],\'signal\'),patch.object(q[\'signal\'],\'alarm\'),contextlib.redirect_stdout(output):q[\'main\']()\n  text=output.getvalue();start=text.index(\'{\');result,_=json.JSONDecoder().raw_decode(text[start:])\n  self.assertNotIn(\'configured-secret-host\',text)\n  if db_ok:\n   self.assertEqual(result[\'errors\'],[]);self.assertEqual(db.execute.call_args_list[0].args[0],\'SET TRANSACTION READ ONLY\');db.commit.assert_not_called();db.rollback.assert_called_once()\n  else:self.assertEqual(result[\'errors\'],[{\'phase\':\'db\',\'error_type\':\'ImportError\'}])\n  self.assertEqual(redis.ConnectionPool.call_args.kwargs[\'socket_timeout\'],5)\n  return result,raw\n def test_prefixed_queue_and_unacked(self):\n  result,raw=self.fake_main(ready=1,unacked=1)\n  self.assertEqual(result[\'queue_result\'],\'TASKS_OR_MESSAGES_PRESENT\')\n  self.assertEqual(result[\'broker\'][\'unacked_count\'],1);self.assertTrue(result[\'broker\'][\'complete\'])\n  self.assertEqual(len(result[\'tasks\']),2)\n  self.assertEqual(raw.lrange.call_args.args[0],b\'app:celery\')\n def test_db_read_only_transaction(self):\n  result,_=self.fake_main(db_ok=True);self.assertEqual(result[\'db_pending_total\'],0)\n def test_empty_live_workers(self):\n  result,_=self.fake_main();self.assertEqual(result[\'queue_result\'],\'NO_TASKS_OBSERVED_IN_SNAPSHOT\')\n def test_no_workers_not_empty_proof(self):\n  result,_=self.fake_main(respond=False);self.assertEqual(result[\'queue_result\'],\'EMPTY_NOT_CONFIRMED\')\n def test_decode_failure_not_complete(self):\n  result,_=self.fake_main(ready=1,unparsed=True);self.assertFalse(result[\'broker\'][\'complete\']);self.assertEqual(result[\'broker\'][\'unparsed\'],1)\n def test_read_budget(self):\n  result,raw=self.fake_main(ready=2100);self.assertEqual(result[\'broker\'][\'unread_at_least\'],100);self.assertFalse(result[\'broker\'][\'complete\'])\n  self.assertEqual(sum(b-a+1 for k,a,b in (x.args for x in raw.lrange.call_args_list)),2000)\n def test_no_business_mutation(self):\n  import ast\n  forbidden={\'delay\',\'apply_async\',\'send_task\',\'purge\',\'revoke\',\'delete\',\'lrem\',\'lpop\',\'rpop\',\'brpop\',\'hdel\',\'zrem\',\'save\',\'commit\',\'upsert\',\'bulk_update_mappings\'}\n  for code in (QUEUE_AUDIT,PUBLIC_NEXT):\n   calls={n.func.attr for n in ast.walk(ast.parse(code)) if isinstance(n,ast.Call) and isinstance(n.func,ast.Attribute)}\n   self.assertFalse(calls&forbidden,calls&forbidden)\n def test_challenge_detection(self):\n  self.assertTrue(p[\'challenge_body\'](\'<script>get_jhash(get_param("__js_p_"))</script>\'))\n  self.assertFalse(p[\'challenge_body\'](\'<title>Закупки</title>\'))\n def test_public_known_urls_and_stop(self):\n  for source,url in p[\'SEEDS\'].items():self.assertTrue(p[\'safe_url\'](url,{p[\'urlsplit\'](url).hostname}))\n  reader=MagicMock();reader.requests=1;reader.get.return_value=(\'<script>get_jhash(1)</script>\',{\'url\':p[\'SEEDS\'][\'tatneft\']})\n  result=p[\'check_one\'](\'tatneft\',reader);self.assertEqual(result[\'errors\'],[\'access_challenge_stop\']);self.assertEqual(reader.get.call_count,1)\n def test_bundle_only_if_current_linked(self):\n  r=MagicMock();r.requests=0;url=p[\'SEEDS\'][\'pik\'];r.get.side_effect=[(\'<script src="/main.current.js"></script>\',{\'url\':url}),(\'query GetTrade { positions documents }\',{\'content_type\':\'application/javascript\',\'complete\':True})]\n  row=p[\'check_one\'](\'pik\',r);self.assertFalse(row[\'pipeline_ready\']);self.assertEqual(row[\'status\'],\'complete_bundle_collected_adapter_not_verified\')\n  self.assertEqual(r.get.call_args.args[0],\'https://etp.pik.ru/main.current.js\');self.assertEqual(r.get.call_args.args[-1],20_000_000)\n def test_unknown_api_never_called(self):\n  r=MagicMock();r.requests=0;r.get.return_value=(\'{"API_BASE_URL":"https://psi.sberbank-ast.ru/api/"}\',{\'url\':p[\'SEEDS\'][\'sberbank_ast\']})\n  row=p[\'check_one\'](\'sberbank_ast\',r);self.assertEqual(row[\'status\'],\'test_environment_config_requires_review\');self.assertEqual(r.get.call_count,1)\n\n def test_config_is_not_challenge(self):\n  for body in (\'<script>window.config={"captcha":{"enabled":true,"name":"yandex"}}</script><title>Закупки</title>\', \'<script src="https://captcha.example/widget.js"></script><div>Торги</div>\'):\n   self.assertFalse(p[\'challenge_body\'](body))\n def test_real_challenges_still_stop(self):\n  for body in (\'<title>Anti-bot verification</title>\',\'<div>Введите капчу</div>\',\'<script>get_jhash(get_param("__js_p_"))</script>\'):\n   self.assertTrue(p[\'challenge_body\'](body))\n def test_contract_output_sanitized(self):\n  out=p[\'contract_evidence\'](\'query trades { id } clientSecret="do-not-disclose"; apiToken="hidden-value";\')\n  self.assertTrue(out);self.assertNotIn(\'do-not-disclose\',json.dumps(out));self.assertNotIn(\'hidden-value\',json.dumps(out))\n def test_redirect_loop_stops_before_request(self):\n  r=p[\'Reader\'](None)\n  with self.assertRaises(p[\'Stop\']):r.get(\'https://etp.tatneft.ru/\',{\'etp.tatneft.ru\'},\'tatneft\',_visited=(\'https://etp.tatneft.ru/\',))\n  self.assertEqual(r.requests,0)\n\nresult=unittest.TextTestRunner(verbosity=2).run(unittest.defaultTestLoader.loadTestsFromTestCase(Tests))\nif not result.wasSuccessful():raise SystemExit(1)\nprint(\'PREFLIGHT_TESTS_OK: offline broker/worker scenarios, prefix, priorities, unacked, bounds, no mutation; public checks mocked\')\n'

def audit_queues():
 services=run(['docker','compose','ps','--services','--status','running'],capture_output=True,text=True,timeout=20).stdout.splitlines()
 if 'app' not in services:raise SystemExit('APP_NOT_RUNNING: queue state unknown; no services started. Run docker compose ps --all.')
 workers=sorted(set(services)&{'celery_worker','celery_discovery'})
 hosts=[]
 if workers:
  ids=run(['docker','compose','ps','--status','running','-q',*workers],capture_output=True,text=True,timeout=20).stdout.splitlines()
  if ids:
   host_rows=run(['docker','inspect','--format','{{.Config.Hostname}}',*ids],capture_output=True,text=True,timeout=20).stdout.splitlines()
   hosts=sorted(set(x.strip() for x in host_rows if x.strip()))
 script='EXPECTED_WORKER_SERVICES = '+repr(workers)+'\nEXPECTED_WORKER_HOSTNAMES = '+repr(hosts)+'\n'+QUEUE_AUDIT
 try:
  run(['docker','compose','exec','-T','app','python','-'],input=script,text=True,timeout=100)
 except (subprocess.TimeoutExpired,subprocess.CalledProcessError):
  raise SystemExit('QUEUE_AUDIT_INCOMPLETE: EMPTY_NOT_CONFIRMED; no business tasks submitted or removed')

def check_next_platforms():
 # Host network matches the prior archive. No app/business imports or container startup.
 try:
  run([sys.executable,'-'],input=PUBLIC_NEXT,text=True,timeout=300)
 except (subprocess.TimeoutExpired,subprocess.CalledProcessError):
  raise SystemExit('NEXT_PLATFORM_CHECK_INCOMPLETE: no source connected or business tasks submitted')


SEARCH_FILTER_MEMO = 'ТЕНДЕРНЫЙ АССИСТЕНТ СТД — ПОИСК И ОТБОР ЗАКУПОК\nСрез кода: 26.10.2026. Памятка к install-tender-sources.py.\n\nОснование: исходный код единого пакета, локальная копия ранее подключённых\nадаптеров и предоставленные серверные отчёты. Это описание действующей логики,\nа не обещание полного охвата всех закупок. Фактические определения в работающем\nконтейнере и запросы последнего сбора выводит --show-search-filters.\nДанная доработка диагностики не меняет коммерческие критерии и ключи поиска.\n\n1. ОБЩИЕ ПОИСКОВЫЕ ФРАЗЫ\n\nалюминий\nалюминиевый прокат\nцветной металлопрокат\nалюминиевая лента\nалюминиевый лист\nалюминиевый профиль\nалюминиевая труба\nалюминиевый пруток\nалюминиевая шина\nалюминиевая плита\nалюминиевая полоса\nалюминиевая катанка\nалюминиевая фольга\n\nОбщий список FALLBACK_QUERIES используется адаптерами по-разному. Он не означает,\nчто все 13 фраз отправляются на каждую площадку при каждом запуске.\n\nПрефиксы ОКПД2 в общей политике:\n24.42.11; 24.42.22; 24.42.23; 24.42.24; 24.42.25; 24.42.26.\nЭто буквальные значения из кода. Наличие кодов в настройках не подтверждает\nиспользование штатного фильтра ОКПД2 площадки. На части источников код передаётся\nкак текстовый запрос или проверяется уже в полученной карточке.\n\n2. ОСОБЕННОСТИ ПО ПЛОЩАДКАМ\n\nЭТП ГПБ\nЗапрос «алюминий» плюс одна фраза по ротации:\nалюминиевая лента; алюминиевый лист; алюминиевый профиль; алюминиевая труба;\nалюминиевый пруток; алюминиевая шина; алюминиевая фольга.\nШтатный параметр стадии: accepting. Далее проверяются срок приёма, предмет\nзакупки и публичные позиции. Неясное название само по себе не подтверждает\nцелевую закупку. Общий перечень 13 фраз здесь полностью не используется.\nОбычно первая страница плюс две страницы сохранённого курсора; до 10 проверок\nкарточек и двух передач на дальнейшую обработку за запуск.\n\nMETAL-IT\n«алюм» плюс одна фраза из общего списка по ротации. Проверка открытой процедуры,\nпозиций, материала и объёма. Native ОКПД2 не подтверждён.\nПервая страница плюс до двух страниц курсора. Объём проверяется по общей\nполитике 500 кг / 200 шт., без суммирования разных позиций.\n\nТЭК-Торг\n«алюминий» плюс одна фраза общего списка, кроме «алюминий», по ротации.\nПоиск по названию; максимум три страницы на запрос за запуск.\nОткрытый приём заявок и будущий срок; исключаются продажа, отдельные разделы\nреализации и мониторинг цен. Признаки товара проверяются в названии либо\nпо ОКПД2 карточки. Штатный поисковый параметр ОКПД2 не подтверждён.\n\nФабрикант\nШесть ранее выбранных групп внутренних идентификаторов рубрикатора;\nдополнительно «Алюминий» и «алюминиевый лист».\nПоисковый статус statuses[]=1, затем проверка стадии и срока в карточке.\nСоответствие непрозрачных идентификаторов числовым ОКПД2 не подтверждено;\nих нельзя автоматически переименовать в коды общей политики.\nДо первой и двух следующих страниц на фильтр, с общим лимитом запросов.\n\nРосэлторг\n«алюминий» плюс один элемент ротации: общие ОКПД2 и поисковые фразы.\nЗначение передаётся в текстовое поле query_field; status[]=0.\nДалее требуется подтверждённый приём заявок. Код в текстовом поле не равен\nштатному фильтру классификатора. Неподтверждённая пагинация отмечается как\nнеполный охват. Сохраняются номер закупки и номер лота.\n\nГлавстрой\nТекстовый запрос «алюм». Проверяются открытая стадия, срок и признаки\nалюминиевой продукции в выдаче. Отсутствие признаков в кратком заголовке\nможет ограничивать полноту поиска: содержимое всех документов не просматривается.\n\nСамолёт\n«алюм» плюс один корень по ротации:\nпрофил; лист; лент; плит; фольг; труб; прут; шин; полос; катанк; слит; прокат.\nКаждый запрос проверяется отдельно для состояний CONFIRM_PARTICIPATION и\nACCEPT_PROPOSALS. Курсоры независимы для пары «запрос + состояние».\nОбщие слова «лист» или «профил» могут дать неалюминиевые результаты;\nони не являются основанием для автоматического допуска к анализу.\n\nBidzaar\n«алюм» плюс один запрос по ротации:\nалюминиевый лист; алюминиевая лента; алюминиевый профиль; алюминиевая фольга;\nалюминиевая труба; алюминиевая шина; АМГ; Д16; АД31; алюминиевый прокат.\nПубличная выдача: status in [1], procedureType = 1; результат дополнительно\nпроверяется на стороне ассистента. Первая страница и до двух страниц курсора.\nДо 10 детальных проверок и двух передач на обработку за запуск.\n\nЕИС\nВ доступной локальной копии адаптера SEARCH_QUERIES составлен из общих\nпрефиксов ОКПД2 и всех FALLBACK_QUERIES. SEARCH_PAGES=3,\nRECORDS_PER_PAGE=50. Эти значения необходимо сопоставлять с работающим\nконтейнером: --show-search-filters выводит определения без запуска поиска.\n\nЕСТП и другие источники\nДля источника estp ранее подтверждены расписание и отчёт сборщика.\nПолный набор его ключей в этой памятке не подтверждён; универсальный список\nему не приписывается. Для B2B ранее наблюдалась CAPTCHA. Tender.Pro оставлен\nна паузе по решению пользователя. Для новых площадок Сбербанк-АСТ, Татнефть,\nПИК, Аквилон и Level готовность полного сбора/анализа ещё не подтверждена.\n\n3. КРИТЕРИИ ОБЪЁМА — ПО ОДНОЙ ПОЗИЦИИ\n\n• Известная масса: минимум 500 кг включительно. 499 кг или 44 кг не проходят.\n• Если масса неизвестна: минимум 200 целых штук включительно.\n• 4000 штук при неизвестной массе проходят объёмный критерий.\n• Если масса известна и меньше 500 кг, число штук не отменяет отказ по массе.\n• При некорректно указанной массе нельзя автоматически заменить её штуками.\n• 300 кг одной позиции + 300 кг другой не дают проходную позицию.\n• Преобразование тонн в килограммы допускается. Метры и м² не считаются штуками.\n\nРасчётная масса допускается отдельно для сплошного плоского алюминиевого\nпроката при структурированных площади, толщине и распознанном сплаве:\nплощадь × толщина в метрах × номинальная плотность.\nВ коде плотности заданы для 3003, 3004, 3005, 3105, 5005, 5052, 5083, 5754.\nРасчёт помечается как оценочный; заявленная заказчиком масса не подменяется.\nДля АКП, сотовых/перфорированных изделий, профилей и других исключённых форм\nтакой расчёт не используется. Покрытие и допуски в номинальной массе не учтены.\n\n4. МАТЕРИАЛ И ПРЕДМЕТ ЗАКУПКИ\n\nДля прохода требуется одновременно признак подходящей формы продукции\nи подтверждение алюминия или распознанного алюминиевого сплава.\nСлово «алюминий» в общем описании не делает всю закупку целевой.\nСтальной профиль не подходит; алюминиевый профиль может подходить.\n\nПредусмотрены исключения для явно нецелевых товаров: стальных, медных,\nлатунных, бронзовых изделий; кабелей/проводов; лестниц, стремянок, посуды.\nДополнительный фильтр ГПБ/Bidzaar исключает закупки офисных принадлежностей,\nканцелярии, готовой мебели и соответствующих готовых изделий; клейких лент;\nработ/ремонта/монтажа, где материал — лишь часть сметы, а не отдельная поставка.\n\nОбработка неоднозначных и смешанных лотов зависит от адаптера. В специальной\nполитике ГПБ/Bidzaar смешанный предмет может быть остановлен для уточнения.\nНельзя описывать действующий код как правило «отбрасываем только по документам»:\nчасть фильтров действительно действует уже по заголовку и названию позиции.\n\n5. ДОПУСК К АНАЛИЗУ И НА ДАШБОРД\n\nПеред анализом проверяются актуальность, ручные исключения, предмет закупки,\nдоступность документов и качество извлечения/OCR. Низкая уверенность OCR\nне считается успешно подготовленным документом. Отказ провайдера LLM\nсохраняется отдельно, без бесконечного повторного запроса.\n\nВ «Подходящие» может попасть закупка с завершённым анализом и хотя бы одной\nцелевой позицией достаточного объёма. Результат участия can_apply,\nmanual_review или needs_clarification показывается отдельно с рейтингом\nи причинами. Статус not_suitable не проходит этот допуск.\nАктуальность и ручные исключения также учитываются при формировании каталога.\n\nПриоритет цены в общей политике:\nот 1 000 000 руб. — высокий; от 500 000 руб. — обычный; ниже — низкий.\nНеизвестная цена допускается, другая валюта требует проверки.\nЭто приоритет, а не универсальный запрет участия по минимальной цене.\n\nВ общей политике заявлены РФ и СНГ, все заказчики и отрасли, 44-ФЗ,\n223-ФЗ и коммерческие закупки. Это область отбора, а не доказательство\nгеографического охвата или реализации всех фильтров на каждой площадке.\n\n6. ИЗВЕСТНЫЕ ОГРАНИЧЕНИЯ, КОТОРЫЕ НЕ НУЖНО СКРЫВАТЬ\n\n• Общий перечень поисковых фраз не включает отдельные запросы «поковки»,\n  «штамповки», «металлокассеты», «алюминиевый уголок», «алюминиевый швеллер».\n• Распознаватель продукции ГПБ знает поковки, но общий PRODUCT в политике\n  отбора не содержит явного шаблона «поковки»/«штамповки». Это несогласованность,\n  требующая отдельной доработки и проверки бизнес-правил, а не молчаливого\n  объявления всего ассортимента уже покрытым поиском.\n• Сплавы как отдельные поисковые запросы явно используются у Bidzaar;\n  наличие распознавателя сплавов не означает поиск каждого сплава на всех ЭТП.\n• Ротация, лимиты страниц и проверки карточек означают постепенный обход.\n  Ноль найденных в текущем запуске не доказывает отсутствие закупок на площадке.\n• Ручные исключения и завершённые анализы сохраняются; данная памятка\n  и диагностическое исправление не запускают повторную обработку.\n\nКОМАНДЫ ИЗ КОРНЯ ПРОЕКТА\npython3 /tmp/install-tender-sources.py --show-search-filters\npython3 /tmp/install-tender-sources.py --audit-queues\npython3 /tmp/install-tender-sources.py --check-next-platforms\n\nПервая команда выводит эту памятку и фактические определения работающего app.\nВторая читает состояние очередей и БД. Третья проверяет пять следующих площадок\nи выводит необходимые диагностические сведения в терминал. Архив создаётся\nлокально для сохранности, но скачивать его с сервера для обычного разбора не нужно.\nБез флага файл по-прежнему выполняет установку; для этой проверки используйте\nименно указанные диагностические режимы.\n\nДОПОЛНЕНИЕ 27.10.2026: ПИК / Аквилон / Level. Публичный GraphQL, алюм + одна фраза из общей ротации. Первая страница и две страницы курсора по 5 записей, до 10 карточек и двух передач за запуск. Только открытая закупка, ближайший срок подтверждения/подачи, подтверждённая позиция алюминиевого материала и общий порог 500 кг / 200 шт. Отдельные лоты не объединяются, изделия/работы не подтверждают поставку сырья. Документы целиком, затем существующие OCR/LLM/дашборд. Новые расписания 56/57/58 минут каждые четыре часа Europe/Moscow.\n'
SEARCH_FILTER_RUNTIME = '"""Print whitelisted search definitions from running app files; no imports of adapters."""\nimport ast,hashlib,json\nfrom pathlib import Path\nfrom datetime import datetime,timezone\nSPECS={\n \'app/sources/developer_graphql.py\':{\'VERSION\',\'HOSTS\',\'LIMIT\',\'MAX_DETAILS\',\'MAX_REQUESTS\',\'ASSEMBLY\',\'FOREIGN_MATERIAL\',\'WORKS\'},\n \'app/scoring/selection_policy.py\':{\'VERSION\',\'MIN_WEIGHT_KG\',\'MIN_PIECES\',\'OKPD2_PREFIXES\',\'FALLBACK_QUERIES\',\'PRODUCT\',\'NON_TARGET\',\'ALUMINIUM\',\'ALLOY\'},\n \'app/marketplace_discovery/primary/gpb_search.py\':{\'QUERIES\'},\n \'app/sources/bidzaar.py\':{\'TERMS\',\'SIZE\'},\n \'app/sources/samolet_search.py\':{\'TERMS\',\'STATES\',\'LIMIT\'},\n \'app/marketplace_discovery/primary/fabrikant_search.py\':{\'FILTERS\'},\n \'app/sources/zakupki_gov_public/adapter.py\':{\'SEARCH_QUERIES\',\'SEARCH_PAGES\',\'RECORDS_PER_PAGE\'},\n \'app/scoring/area_mass.py\':{\'DENSITIES_KG_M3\',\'AREA_UNITS\'},\n}\nprint(\'SERVER_SEARCH_FILTERS_UTC:\',datetime.now(timezone.utc).isoformat(),flush=True)\nfor name,wanted in SPECS.items():\n path=Path(\'/app\')/name\n try:\n  if path.stat().st_size>1_000_000:raise ValueError(\'source_limit\')\n  body=path.read_bytes();tree=ast.parse(body);found={}\n  for n in ast.walk(tree):\n   if isinstance(n,(ast.Assign,ast.AnnAssign)):\n    targets=n.targets if isinstance(n,ast.Assign) else [n.target]\n    for target in targets:\n     if not isinstance(target,ast.Name) or target.id not in wanted:continue\n     try:value=ast.literal_eval(n.value)\n     except (ValueError,TypeError):value={\'expression\':ast.unparse(n.value)[:2500],\'evaluated\':False}\n     found[target.id]=value\n  print(json.dumps({\'file\':name,\'sha256\':hashlib.sha256(body).hexdigest(),\'definitions\':found},ensure_ascii=False,default=lambda v:sorted(v) if isinstance(v,set) else str(v)),flush=True)\n except Exception as e:print(json.dumps({\'file\':name,\'error_type\':type(e).__name__}),flush=True)\ntry:\n from app.marketplace_discovery.primary.collector import folder\n for source in (\'pik\',\'akvilon\',\'level\',\'gpb\',\'metal_it\',\'tektorg\',\'fabrikant\',\'glavstroy\',\'samolet\',\'bidzaar\',\'roseltorg\',\'estp\'):\n  path=folder()/(source+\'.json\')\n  if not path.is_file():continue\n  if path.stat().st_size>5_000_000:continue\n  d=json.loads(path.read_text());searches=[]\n  for row in (d.get(\'searches\') or [])[:24]:\n   searches.append({k:row[k] for k in (\'query\',\'filter\',\'ids\',\'field\',\'filter_type\',\'state\',\'stage\',\'complete\') if k in row})\n  print(json.dumps({\'source\':source,\'last_report_time\':d.get(\'checked_at\'),\'query\':d.get(\'query\'),\'searches\':searches,\'classifier_filter\':d.get(\'classifier_filter\'),\'filter_mapping\':d.get(\'filter_mapping\')},ensure_ascii=False),flush=True)\nexcept Exception as e:print(\'LAST_SEARCH_REPORTS_UNAVAILABLE:\',type(e).__name__,flush=True)\nprint(\'FILTERS_READ_ONLY: no HTTP, DB, task submissions, OCR, LLM or configuration changes\',flush=True)\n'

def show_search_filters():
 print(SEARCH_FILTER_MEMO,flush=True)
 try:
  services=run(['docker','compose','ps','--services','--status','running'],capture_output=True,text=True,timeout=20).stdout.splitlines()
  if 'app' not in services:
   print('SERVER_FILTERS_UNAVAILABLE: app not running; memo reflects package code, not a live audit',flush=True);return
  run(['docker','compose','exec','-T','app','python','-'],input=SEARCH_FILTER_RUNTIME,text=True,timeout=40)
 except (OSError,subprocess.CalledProcessError,subprocess.TimeoutExpired) as exc:
  print('SERVER_FILTERS_UNAVAILABLE:',type(exc).__name__,'; no services started',flush=True)

CHECK_DEVELOPER_PUBLIC = "import json\nfrom app.sources.developer_graphql import HOSTS,collect_readonly\nfor source in HOSTS:\n    print('CHECKING_PUBLIC_DEVELOPER:',source,flush=True)\n    report=collect_readonly(source)\n    report['items']=[{k:item.get(k) for k in ('external_id','title','submission_deadline')} for item in report['items']]\n    print(json.dumps(report,ensure_ascii=False,default=str),flush=True)\nprint('READ_ONLY_DEVELOPER_CHECK: public search/cards; no documents, DB writes, report writes, queues, OCR or LLM')\n"

PUBLIC_DEVELOPER_TESTS = "# Focused offline regression suite for the new public sources.\nimport copy as _copy\nimport tempfile as _tempfile\nimport unittest as _unittest\nfrom unittest.mock import patch as _patch, MagicMock as _MagicMock\nfrom datetime import datetime as _datetime, timezone as _timezone, timedelta as _timedelta\nfrom pathlib import Path as _Path\nfrom app.sources import developer_graphql as _dg\n\nclass PublicDeveloperTests(_unittest.TestCase):\n    def setUp(self):\n        self.now = _datetime(2026, 10, 27, 12, tzinfo=_timezone.utc)\n        self.end = int((self.now + _timedelta(days=5)).timestamp()*1000)\n        row={'id':10,'number':1,'title':'Лист алюминиевый АМГ2','productTitle':None,'quantity':500,\n             'unit':{'title':'кг','code':'166'},'canceled':False,'characteristics':None}\n        lot={'id':2,'processStatus':'BID_SUBMISSION','purchaseItems':[row],**{f:[] for f in _dg.LOT_FIELDS}}\n        self.trade={'id':1,'title':'Поставка алюминиевого листа','published':True,'request':False,\n                    'processStatus':'BID_SUBMISSION','status':{'code':'active'},'bidSubmissionEndDate':self.end,\n                    'lots':[lot],**{f:[] for f in _dg.TRADE_FIELDS}}\n        self.trade['technicalSpecificationAttachments']=[{'id':20,'name':'ТЗ.docx','href':'/files/get/public-id/TZ.docx'}]\n    def test_mass_pieces_and_no_sum(self):\n        row=self.trade['lots'][0]['purchaseItems'][0]\n        for qty,unit,want in ((44,'кг',False),(499,'кг',False),(500,'кг',True),(0.5,'т',True),(199,'шт',False),(200,'шт',True),(4000,'шт',True),(200.5,'шт',False),(600,'м2',False)):\n            row['quantity']=qty;row['unit']['title']=unit\n            self.assertEqual(bool(_dg.evaluate(self.trade,self.now)[0]),want,(qty,unit))\n        row['unit']['title']='кг';row['quantity']=300\n        second=_copy.deepcopy(row);second['id']=11;self.trade['lots'][0]['purchaseItems'].append(second)\n        self.assertEqual(_dg.evaluate(self.trade,self.now)[1],'below_position_threshold')\n    def test_objects_not_material_mentions(self):\n        for name in ('Профиль COMPACFOAM для алюминиевых конструкций','Система дверная из алюминиевых профилей',\n                     'ВН1 Витраж наружный. Алюминиевый профиль','Стальная труба','Монтаж алюминиевого профиля','Линейка алюминиевая'):\n            self.assertIsNot(_dg.position_material({'title':name}),True,name)\n        for name in ('Лист алюминиевый окрашенный','Профиль алюминиевый АД31','Труба АМГ2М'):\n            self.assertTrue(_dg.position_material({'title':name}),name)\n    def test_subject_works(self):\n        for title in ('Комплекс работ по изготовлению, поставке и монтажу окон','Выполнение комплекса работ по поставке дверей','Поставка канцелярских товаров'):\n            self.trade['title']=title;self.assertIsNone(_dg.evaluate(self.trade,self.now)[0])\n    def test_earlier_confirmation(self):\n        self.trade['processStatus']='PARTICIPATION_CONFIRMATION'\n        self.assertIsNone(_dg.active_deadline(self.trade,self.now))\n        early=int((self.now+_timedelta(hours=1)).timestamp()*1000)\n        self.trade['participationConfirmationEndDate']=early\n        self.assertEqual(_dg.active_deadline(self.trade,self.now).timestamp()*1000,early)\n        self.trade['participationConfirmationEndDate']=int(self.now.timestamp()*1000)-1\n        self.assertIsNone(_dg.active_deadline(self.trade,self.now))\n    def test_closed_and_cancelled(self):\n        for key,value in (('published',False),('request',True),('processStatus','FINISHED'),('status',{'code':'closed'})):\n            t=_copy.deepcopy(self.trade);t[key]=value;self.assertIsNone(_dg.evaluate(t,self.now)[0])\n        self.trade['lots'][0]['purchaseItems'][0]['canceled']=True\n        self.assertEqual(_dg.evaluate(self.trade,self.now)[1],'no_target_material_positions')\n    def test_lot_and_duplicate_guards(self):\n        lot=_copy.deepcopy(self.trade['lots'][0]);lot['id']=3;self.trade['lots'].append(lot)\n        self.assertEqual(_dg.evaluate(self.trade,self.now)[1],'multiple_lots_require_mapping')\n        self.trade['lots'].pop();self.trade['lots'][0]['purchaseItems']*=2\n        with self.assertRaisesRegex(ValueError,'duplicate_position'):_dg.evaluate(self.trade,self.now)\n    def test_document_all_or_nothing(self):\n        docs=_dg.references('pik',self.trade);self.assertEqual(len(docs),1)\n        self.trade['otherAttachments']=[{'id':21,'name':'extra.exe','href':'/files/get/x/extra.exe'}]\n        with self.assertRaisesRegex(ValueError,'format_unverified'):_dg.references('pik',self.trade)\n        self.trade['otherAttachments']=[];del self.trade['contractDraftAttachments']\n        with self.assertRaisesRegex(ValueError,'list_missing'):_dg.references('pik',self.trade)\n    def test_host_paths_operation_guards(self):\n        for url in ('http://etp.pik.ru/files/get/x/a.docx','https://etp.pik.ru.evil.test/files/get/x/a.docx',\n                    'https://etp.pik.ru/files/get/%2e%2e/a.docx','https://etp.pik.ru/login',\n                    'https://user@etp.pik.ru/files/get/x/a.docx'):\n            with self.assertRaises(ValueError):_dg.safe_url('pik',url,True)\n        with self.assertRaisesRegex(ValueError,'operation_not_allowed'):_dg.request('pik','deleteTrade',{})\n    def test_identity_and_dismissal(self):\n        a=_dg.PublicDeveloperAdapter('pik')\n        with _patch('app.reports.review_dismissals.is_dismissed',return_value=True),_patch.object(_dg,'request') as r:\n            self.assertIsNone(a.fetch_by_id('1',_dg.card_url('pik','1')));r.assert_not_called()\n        with self.assertRaisesRegex(ValueError,'identity_mismatch'):a.fetch_by_id('1','https://etp.level.ru/trades/1/info')\n        with _patch('app.reports.review_dismissals.is_dismissed',return_value=False),_patch.object(_dg,'request',return_value={'trade':dict(self.trade,id=99)}):\n            with self.assertRaisesRegex(ValueError,'identity_mismatch'):a.fetch_by_id('1')\n    def test_source_tender_and_preparer(self):\n        from app.sources.document_preparer import prepare_tender_documents\n        for source in _dg.HOSTS:\n            with _patch('app.reports.review_dismissals.is_dismissed',return_value=False),_patch.object(_dg,'clock',return_value=self.now),_patch.object(_dg,'request',return_value={'trade':self.trade}):\n                card=_dg.PublicDeveloperAdapter(source).fetch_by_id('1')\n            self.assertEqual(card.source,source);self.assertTrue(card.raw_payload['suppress_notifications'])\n            self.assertEqual(len(card.raw_payload['positions']),1)\n            with _patch.object(_dg,'materialize',return_value=[]) as m:\n                self.assertEqual(prepare_tender_documents(card),[]);m.assert_called_once_with(card)\n    def test_partial_files_cleanup(self):\n        from app.core.config import settings\n        with _patch('app.reports.review_dismissals.is_dismissed',return_value=False),_patch.object(_dg,'clock',return_value=self.now),_patch.object(_dg,'request',return_value={'trade':self.trade}):\n            card=_dg.PublicDeveloperAdapter('pik').fetch_by_id('1')\n        with _tempfile.TemporaryDirectory() as tmp,_patch.object(settings,'storage_path',tmp),_patch.object(_dg.PublicDeveloperAdapter,'fetch_by_id',return_value=card),_patch.object(_dg,'read',side_effect=ValueError('developer_http_403')):\n            with self.assertRaises(ValueError):_dg.materialize(card)\n            self.assertEqual(list((_Path(tmp)/'developer_prepared').iterdir()),[])\n    def test_listing_and_repeated_page(self):\n        listings=[dict(self.trade,id=i,title='Поставка алюминиевого листа') for i in range(1,6)]\n        def fetch(source,op,var):\n            return {'trades':{'items':listings,'total':15}} if op=='trades' else {'trade':dict(self.trade,id=var['id'])}\n        with _patch.object(_dg.time,'sleep'):\n            r=_dg.collect_readonly('pik',fetch=fetch,now=self.now,dismissed=lambda *a:False)\n        self.assertEqual(r['errors'][0]['reason'],'developer_repeated_page');self.assertFalse(r['searches'][0]['complete'])\n        self.assertEqual(len(r['items']),5);self.assertEqual(r['pipeline_status'],'not_run')\n    def test_access_stop_no_second_query(self):\n        fetch=_MagicMock(side_effect=ValueError('developer_http_403'))\n        r=_dg.collect_readonly('pik',fetch=fetch,now=self.now,dismissed=lambda *a:False)\n        self.assertEqual(fetch.call_count,1);self.assertEqual(r['status'],'partial');self.assertEqual(r['items'],[])\n    def test_paging_cursor_empty_and_detail_limit(self):\n        calls=[]\n        def fetch(source,op,var):\n            calls.append((op,var))\n            if op=='trades':\n                skip=var['skip'];return {'trades':{'items':[dict(self.trade,id=i) for i in range(skip+1,min(skip+6,16))],'total':15}}\n            return {'trade':dict(self.trade,id=var['id'])}\n        with _patch.object(_dg.time,'sleep'):\n            r=_dg.collect_readonly('pik',fetch=fetch,now=self.now,dismissed=lambda *a:False)\n        self.assertEqual(r['cards_checked'],10);self.assertEqual(r['errors'][0]['reason'],'developer_detail_limit')\n        self.assertEqual(r['next_offsets']['алюм'],10)\n        r=_dg.collect_readonly('level',fetch=lambda *a:{'trades':{'items':[],'total':0}},now=self.now,dismissed=lambda *a:False)\n        self.assertEqual(r['status'],'no_matches_in_checked_filters');self.assertEqual(r['cards_checked'],0)\n    def test_qualified_materialization_shared_unpack(self):\n        import io,zipfile\n        from app.core.config import settings\n        b=io.BytesIO()\n        with zipfile.ZipFile(b,'w') as z:\n            z.writestr('[Content_Types].xml','<Types/>');z.writestr('word/document.xml','<doc/>')\n        with _patch('app.reports.review_dismissals.is_dismissed',return_value=False),_patch.object(_dg,'clock',return_value=self.now),_patch.object(_dg,'request',return_value={'trade':self.trade}):\n            card=_dg.PublicDeveloperAdapter('pik').fetch_by_id('1')\n        with _tempfile.TemporaryDirectory() as tmp,_patch.object(settings,'storage_path',tmp),_patch.object(_dg.PublicDeveloperAdapter,'fetch_by_id',return_value=card),_patch.object(_dg,'read',return_value=b.getvalue()):\n            docs=_dg.materialize(card)\n            self.assertEqual(len(docs),2);self.assertTrue(all(_Path(d.local_path).is_file() for d in docs))\n    def test_two_handoffs_and_duplicate_lease(self):\n        from app.sources import developer_portals as dp\n        from app.sources.schemas import SourceTender\n        from app.workers.tasks_parsing import process_new_tender\n        items=[{'source':'pik','external_id':str(i),'title':'Лист алюминиевый АМГ2','source_url':_dg.card_url('pik',i),'submission_deadline':(self.now+_timedelta(days=5)).isoformat()} for i in range(1,5)]\n        redis=_MagicMock();redis.get.return_value=None;redis.set.return_value=True\n        session=_MagicMock();session.__enter__.return_value=session;session.execute.return_value.scalar_one_or_none.return_value=None\n        class Adapter:\n            def __init__(self,source):self.source=source\n            def fetch_by_id(self,uid,url):return SourceTender(source=self.source,external_id=uid,title='Лист алюминиевый АМГ2',source_url=url,submission_deadline=items[0]['submission_deadline'],raw_payload={'suppress_notifications':True})\n        with _patch('redis.Redis.from_url',return_value=redis),_patch('app.db.session.SyncSessionLocal',return_value=session),_patch('app.reports.review_dismissals.is_dismissed',return_value=False),_patch.object(dp,'now',return_value=self.now),_patch.object(process_new_tender,'delay',return_value=_MagicMock(id='fake-task')) as submit:\n            out=dp.enqueue('pik',items,adapter_factory=Adapter)\n            self.assertEqual(submit.call_count,2);self.assertEqual([r['status'] for r in out],['queued','queued','batch_limit','batch_limit'])\n            submit.reset_mock();redis.set.return_value=False\n            out=dp.enqueue('pik',items,adapter_factory=Adapter)\n            submit.assert_not_called();self.assertTrue(all(r['status']=='already_queued_or_attempted' for r in out))\n\n    def test_registry_schedule_and_saved_gate(self):\n        from app.sources.registry import get_adapter\n        from app.workers.celery_app import celery_app\n        from app.sources.eis_freshness import eligibility\n        for source,minute in (('pik',56),('akvilon',57),('level',58)):\n            self.assertIsInstance(get_adapter(source),_dg.PublicDeveloperAdapter)\n            entry=celery_app.conf.beat_schedule['primary-'+source+'-4h']\n            self.assertEqual(entry['schedule'].minute,{minute});self.assertEqual(tuple(entry['args']),(source,))\n            self.assertEqual(eligibility(source,None,{},True,self.now),'closed_stage')\n\n_outcome=_unittest.TextTestRunner(verbosity=1).run(_unittest.defaultTestLoader.loadTestsFromTestCase(PublicDeveloperTests))\nif not _outcome.wasSuccessful():raise SystemExit('PUBLIC_DEVELOPER_TESTS_FAILED')\nprint('PUBLIC_DEVELOPER_TESTS_OK: separate positions, mass/pieces, no sums, assemblies, deadlines, identity, pages, access stop, complete documents, shared queue routing; no live DB/broker/LLM')\n"
PUBLIC_DEVELOPER_VERIFY = "from app.sources.registry import get_adapter\nfrom app.sources.developer_graphql import PublicDeveloperAdapter\nfrom app.workers.celery_app import celery_app\nfor source,minute in (('pik',56),('akvilon',57),('level',58)):\n    assert isinstance(get_adapter(source),PublicDeveloperAdapter)\n    entry=celery_app.conf.beat_schedule.get('primary-'+source+'-4h')\n    assert entry and tuple(entry.get('args') or ())==(source,)\n    assert entry['task']=='app.workers.tasks_primary_discovery.collect_primary'\n    assert entry['schedule'].minute=={minute}\n    print('PUBLIC_DEVELOPER_RUNTIME_OK:',source,'minute',minute,'; no business tasks submitted',flush=True)\n"
def install_public_developers(root):
    # Use only this change set. Earlier installation payloads are retained in the
    # same file for existing modes but are not reapplied by this mode.
    global FILES
    paths={'app/sources/developer_graphql.py','app/sources/registry.py',
           'app/marketplace_discovery/primary/collector.py','app/sources/document_preparer.py',
           'app/sources/developer_portals.py','app/sources/eis_freshness.py','app/workers/tasks_ocr.py'}
    previous_files=FILES
    try:
        FILES=[row for row in FILES if row[0] in paths]
        pending=check_files(root)
    finally:FILES=previous_files
    backup=root/'backups'/('public-developers-'+datetime.now(timezone.utc).strftime('%Y%m%d-%H%M%S-%f'))
    try:
        for rel,content,current in pending:
            if current is not None:atomic(backup/rel,current)
        if pending:
            atomic(backup/'manifest.json',json.dumps({'files':[{'path':rel,'new_file':old is None} for rel,_,old in pending]},indent=2).encode())
            for rel,content,current in pending:atomic(root/rel,content.encode('utf-8'))
            print('BACKUP:',backup,flush=True)
        run(['docker','compose','build','app','celery_worker','celery_discovery','celery_beat'])
        run(['docker','compose','run','--rm','--no-deps','-T','app','python','-'],input=PUBLIC_DEVELOPER_TESTS,text=True,timeout=120)
    except BaseException:
        for rel,_,old in pending:
            if old is None:(root/rel).unlink(missing_ok=True)
            else:atomic(root/rel,old)
        print('PUBLIC_DEVELOPER_BUILD_OR_TEST_FAILED: source restored; running containers not restarted',flush=True)
        raise
    # Complete existing tasks; never force-kill a worker or delete a message.
    running=run(['docker','compose','ps','--services','--status','running'],capture_output=True,text=True,timeout=20).stdout.split()
    services=[s for s in ('celery_beat','celery_discovery','celery_worker') if s in running]
    ids=[]
    for service in services:
        ids.extend(run(['docker','compose','ps','-q',service],capture_output=True,text=True,timeout=20).stdout.split())
    if services:
        print('Waiting for workers to finish existing tasks; no forced kill or queue purge.',flush=True)
        run(['docker','compose','kill','--signal','SIGTERM',*services],timeout=30)
        until=time.monotonic()+300
        while ids:
            states=run(['docker','inspect','--format','{{.State.Running}}',*ids],capture_output=True,text=True,timeout=20).stdout.split()
            if len(states)==len(ids) and all(state=='false' for state in states):break
            if time.monotonic()>until:raise SystemExit('WARM_SHUTDOWN_PENDING: no forced stop; rerun the same command after tasks finish')
            time.sleep(3)
    run(['docker','compose','up','-d','--no-deps','app','celery_worker','celery_discovery'])
    run(['docker','compose','exec','-T','app','python','-'],input=PUBLIC_DEVELOPER_VERIFY,text=True,timeout=45)
    run(['docker','compose','exec','-T','app','python','-'],input=WORKER_PING,text=True,timeout=45)
    run(['docker','compose','up','-d','--no-deps','celery_beat'])
    print('PUBLIC_DEVELOPERS_INSTALLED: pik, akvilon, level; shared documents/OCR/LLM; two handoffs/source/run; no immediate collection or notifications. Existing schedules retained; new schedules enabled.',flush=True)

FEDERAL_CHECK = '"""One read-only terminal check; reuses deployed public parsers, no installation."""\nimport json\nimport re\nimport time\nfrom datetime import datetime, timezone\nfrom urllib.parse import urljoin, urlsplit, parse_qsl\n\nVERSION = \'federal-access-check-20261027-1\'\n\n\ndef clean_url(url):\n    p = urlsplit(url)\n    return p._replace(query=\'\', fragment=\'\', netloc=p.hostname or \'\').geturl()\n\n\ndef script_links(html, base, allowed):\n    from bs4 import BeautifulSoup\n    soup = BeautifulSoup(html, \'html.parser\')\n    urls = []\n    for tag in soup.select(\'script[src]\'):\n        url = urljoin(base, tag[\'src\'])\n        p = urlsplit(url)\n        if (p.hostname == urlsplit(base).hostname and allowed(url)\n                and not any(re.search(r\'token|secret|password|session|key|signature\', k, re.I) for k,v in parse_qsl(p.query))\n                and p.path.endswith(\'.js\')\n                and not re.search(r\'jquery|captcha|analytics|metrika|bootstrap|polyfills|runtime|chat\', p.path, re.I)):\n            if url not in urls:\n                urls.append(url)\n    urls.sort(key=lambda u: (not bool(re.search(r\'main|bundle|search|purchase|core\', urlsplit(u).path, re.I)), u))\n    return urls[:2]\n\n\ndef evidence(text):\n    result = []\n    for label, pattern in (\n        (\'search\', r\'Processing/main|SearchPurchase|PurchaseSearch|SearchTender|TenderSearch|SearchProcedure|api/[^\\s\\"\\\'<>]{0,100}(?:search|purchase|tender)\'),\n        (\'documents\', r\'Processing/file|DownloadFile|DownloadDocument\'),\n    ):\n        # Only endpoint names, not JS values, tokens, cookies or whole responses.\n        matches = list(dict.fromkeys(re.findall(pattern, text, re.I)))[:15]\n        result.append({\'kind\': label, \'markers\': matches})\n    return result\n\n\nclass Transport:\n    def __init__(self, allowed, max_requests=12, fetch=None):\n        self.allowed = allowed\n        self.max_requests = max_requests\n        self.fetch = fetch\n        self.requests = []\n        self.stopped = False\n        self.started = time.monotonic()\n\n    def __call__(self, url, *, payload=None, headers=None, limit=2_000_000):\n        from app.sources.sber_public_check import ProbeError\n        if payload is not None and not (isinstance(payload,dict) and payload.get(\'windowCode\') == \'/EsOpenUnitedPurchaseList\' and payload.get(\'actionType\') == \'MONITOR\' and payload.get(\'actionCode\') == \'default\' and urlsplit(url).path.endswith(\'/Processing/main\')):\n            raise ProbeError(\'non_read_operation_refused\')\n        if self.stopped:\n            raise ProbeError(\'source_stopped_after_error\')\n        if not self.allowed(url):\n            self.stopped = True\n            raise ProbeError(\'unapproved_endpoint\')\n        if len(self.requests) >= self.max_requests or time.monotonic() - self.started > 110:\n            self.stopped = True\n            raise ProbeError(\'check_budget_exhausted\')\n        item = {\'url\': clean_url(url), \'method\': \'POST\' if payload is not None else \'GET\'}\n        self.requests.append(item)\n        try:\n            if self.fetch is not None:\n                result = self.fetch(url, payload=payload, headers=headers, limit=limit)\n            else:\n                result = http_read(url, payload=payload, headers=headers, limit=limit)\n            item.update(http=result[\'http\'], bytes=len(result[\'body\']))\n            return result\n        except Exception as exc:\n            self.stopped = True\n            item.update(error_type=type(exc).__name__, reason=getattr(exc, \'reason\', \'transport_error\'), http=getattr(exc, \'http\', None))\n            raise\n\n\ndef http_read(url, *, payload=None, headers=None, limit=2_000_000):\n    import httpx\n    from app.sources.sber_public_check import ProbeError\n    start = time.monotonic()\n    with httpx.Client(verify=True, follow_redirects=False, timeout=httpx.Timeout(12, connect=5)) as client:\n        with client.stream(\'POST\' if payload is not None else \'GET\', url, json=payload, headers=headers or {}) as r:\n            if r.status_code != 200:\n                reason = (\'access_refused\' if r.status_code in (401,403,429) else\n                          \'redirect_requires_review\' if 300 <= r.status_code < 400 else \'http_error\')\n                raise ProbeError(reason, r.status_code)\n            body = bytearray()\n            for block in r.iter_bytes():\n                body.extend(block)\n                if len(body) > limit:\n                    raise ProbeError(\'response_too_large\', r.status_code)\n                if time.monotonic() - start > 25:\n                    raise ProbeError(\'response_time_limit\', r.status_code)\n            if not body:\n                raise ProbeError(\'empty_response\', r.status_code)\n            return {\'body\': bytes(body), \'http\': r.status_code, \'content_type\': r.headers.get(\'content-type\',\'\'), \'url\':url}\n\n\ndef check_sber(fetch=None):\n    from app.sources.sber_public_check import approved, run_check\n    transport = Transport(approved, fetch=fetch)\n    report = run_check(fetch=transport)\n    # Existing parser checks live keyword results, identity and public card HTML.\n    # Do not equate a generic HTML shell or HTTP 200 with document/LLM readiness.\n    report[\'transport\'] = transport.requests\n    report[\'requests\'] = len(transport.requests)\n    report[\'pipeline_ready\'] = False\n    report[\'automatic_collection_enabled_by_check\'] = False\n    return report\n\n\ndef check_rts(fetch=None):\n    from app.sources.federal_check import SITES, safe_url, page_info, search_from_form\n    from app.sources.sber_public_check import ProbeError\n    source = \'rts_tender\'\n    url = SITES[source][1]\n    transport = Transport(lambda u: safe_url(u,source) and not re.search(r\'/(?:login|logout|auth|captcha|register)(?:/|\\.|$)\', urlsplit(u).path, re.I), max_requests=5, fetch=fetch)\n    report = {\'source\':source, \'status\':\'not_checked\', \'pipeline_ready\':False,\n              \'keyword_search\':\'not_verified\', \'documents\':\'not_checked\',\n              \'automatic_collection_enabled_by_check\':False, \'errors\':[]}\n    try:\n        response = transport(url)\n        response[\'url\'] = url\n        links = script_links(response[\'body\'], url, transport.allowed)\n        soup, info = page_info(response,source)\n        report[\'page\'] = info\n        if any(f.get(\'has_password\') for f in info.get(\'forms\',[])):\n            raise ProbeError(\'interactive_access_required\')\n        search = search_from_form(soup,url,source)\n        if search and re.search(r\'search\',urlsplit(search).path,re.I):\n            response = transport(search)\n            response[\'url\'] = search\n            _, info = page_info(response,source)\n            report[\'search\'] = {\'query\':\'алюминий\', **info}\n            report[\'keyword_search\'] = \'form_submitted_results_unverified\'\n            links = script_links(response[\'body\'], search, transport.allowed) or links\n        report[\'scripts\'] = []\n        for script in links:\n            response = transport(script, limit=8_000_000)\n            text = response[\'body\'].decode(\'utf-8\', errors=\'replace\')\n            if \'html\' in response[\'content_type\'].lower() or re.match(r\'\\s*<(?:html|!doctype)\',text,re.I):\n                raise ProbeError(\'script_returned_html\', response[\'http\'])\n            report[\'scripts\'].append({\'url\':clean_url(script),\'bytes\':len(response[\'body\']),\'contract_evidence\':evidence(text)})\n        report[\'status\'] = \'public_evidence_collected_adapter_not_verified\'\n    except Exception as exc:\n        report[\'status\'] = getattr(exc,\'reason\',None) or getattr(exc,\'status\',None) or \'check_incomplete\'\n        if not isinstance(report[\'status\'],str):\n            report[\'status\'] = \'check_incomplete\'\n        report[\'errors\'].append({\'error_type\':type(exc).__name__, \'reason\':getattr(exc,\'reason\',\'check_incomplete\'),\n                                 \'http\':getattr(exc,\'http\',None)})\n    report[\'transport\'] = transport.requests\n    report[\'requests\'] = len(transport.requests)\n    return report\n\n\ndef sanitize(value):\n    if isinstance(value,dict):\n        return {k:(\'[hidden]\' if re.search(r\'token|password|cookie|secret|authorization|session|api.?key\',k,re.I) else sanitize(v)) for k,v in value.items()}\n    if isinstance(value,list):\n        return [sanitize(v) for v in value]\n    if isinstance(value,str):\n        return re.sub(r\'https?://[^\\s\\"\\\'<>]+\',lambda m:clean_url(m[0]),value)\n    return value\n\n\ndef main():\n    import signal\n    # Bounded process lifetime even if DNS or a library call stalls.\n    signal.signal(signal.SIGALRM, lambda *_: (_ for _ in ()).throw(SystemExit(\'FEDERAL_CHECK_TIMEOUT: result incomplete; no retries\')))\n    signal.alarm(260)\n    print(\'FEDERAL_CHECK_UTC:\',datetime.now(timezone.utc).isoformat(),flush=True)\n    print(\'MODE: public read-only; existing application parsers; no installation\',flush=True)\n    for name, check in ((\'sberbank_ast\',check_sber), (\'rts_tender\',check_rts)):\n        print(\'CHECKING:\',name,flush=True)\n        try:\n            result = check()\n        except Exception as exc:\n            result = {\'source\':name,\'status\':\'check_incomplete\',\'error_type\':type(exc).__name__,\'pipeline_ready\':False}\n        print(json.dumps(sanitize(result),ensure_ascii=False,indent=2,default=str),flush=True)\n    signal.alarm(0)\n    print(\'FEDERAL_CHECK_FINISHED: terminal output only; no files, DB writes, queues, documents, OCR, LLM, installs or restarts\',flush=True)\n\n\nif __name__ == \'__main__\':\n    main()\n'

def check_federal_platforms():
 services=run(['docker','compose','ps','--services','--status','running'],capture_output=True,text=True,timeout=20).stdout.splitlines()
 if 'app' not in services:raise SystemExit('APP_NOT_RUNNING: no services started; public check not performed')
 try:
  run(['docker','compose','exec','-T','app','python','-'],input=FEDERAL_CHECK,text=True,timeout=280)
 except (subprocess.TimeoutExpired,subprocess.CalledProcessError,OSError) as exc:
  raise SystemExit('FEDERAL_CHECK_INCOMPLETE: '+type(exc).__name__+'; no automatic retry or installation')


CORPORATE_CHECK = '"""Bounded public corporate-source check, terminal only; no business writes."""\nimport hashlib\nimport io\nimport json\nimport re\nimport signal\nimport time\nfrom collections import Counter\nfrom datetime import datetime, timezone\nfrom urllib.parse import urlsplit, urljoin, urlencode, quote, parse_qsl\n\nLUKOIL=\'https://lukoil.ru\'\nLISTING=LUKOIL+\'/Company/Tendersandauctions/Tenders\'\nNORN=\'https://nornickel.ru\'\nNORN_PAGES=[NORN+\'/suppliers/tenders/central/\',NORN+\'/suppliers/tenders/local/\']\nVERSION=\'corporate-public-check-20261029-1\'\nNORN_QUERIES=(\'алюм\',\'металлопродукц\',\'металлопрокат\',\'цветной металл\')\n\nclass Stop(ValueError):pass\n\nclass Reader:\n    def __init__(self,fetch=None):\n        self.fetch=fetch;self.requests=[];self.allowed={LISTING,*NORN_PAGES}\n        self.failed_hosts=set();self.started=time.monotonic();self.clients={};self.search_params=None;self.max_requests=24;self.read_retries=0\n    def close(self):\n        for client in self.clients.values():client.cookies.clear();client.close()\n        self.clients.clear()\n    def get(self,url,data=None,limit=4_000_000):\n        # Exactly one additional attempt, only a read timeout on the public\n        # LUKOIL listing. No retry for POST, TLS, access refusal or documents.\n        import httpx\n        try:return self._get_once(url,data=data,limit=limit)\n        except httpx.ReadTimeout:\n            if url!=LISTING or data is not None or self.read_retries>=1:raise\n            self.read_retries+=1\n            self.failed_hosts.discard(\'lukoil.ru\')\n            client=self.clients.pop(\'lukoil.ru\',None)\n            if client is not None:client.close()\n            return self._get_once(url,data=data,limit=limit)\n    def _get_once(self,url,data=None,limit=4_000_000):\n        p=urlsplit(url)\n        if p.scheme!=\'https\' or p.hostname not in (\'lukoil.ru\',\'nornickel.ru\') or p.username or p.password or p.port not in (None,443) or p.fragment:\n            raise Stop(\'unapproved_url\')\n        if p.hostname in self.failed_hosts:raise Stop(\'host_stopped_after_error\')\n        if url not in self.allowed:raise Stop(\'unobserved_url\')\n        if data is not None:\n            expected=self.search_params\n            if url!=LUKOIL+\'/api/tenders/SearchTenders\' or not expected or not isinstance(data,dict):raise Stop(\'unapproved_operation\')\n            if set(data)!=set(expected)|{\'SearchQuery\'} or any(data[k]!=v for k,v in expected.items()) or data[\'SearchQuery\'] not in (quote(\'алюм\'),quote(\'металлопродукци\')):\n                raise Stop(\'unapproved_search_payload\')\n        if len(self.requests)>=self.max_requests or time.monotonic()-self.started>160:raise Stop(\'request_budget\')\n        row={\'url\':p._replace(query=\'\').geturl(),\'method\':\'POST\' if data is not None else \'GET\',\'attempt\':1+sum(x[\'url\']==p._replace(query=\'\').geturl() and x.get(\'reason\')==\'transport_error\' for x in self.requests)};self.requests.append(row)\n        try:\n            if self.fetch:result=self.fetch(url,data=data,limit=limit)\n            else:\n                import httpx\n                if p.hostname not in self.clients:self.clients[p.hostname]=httpx.Client(verify=True,follow_redirects=False,timeout=httpx.Timeout(18,connect=5))\n                client=self.clients[p.hostname]\n                headers={\'Accept-Encoding\':\'identity\'}\n                if data is not None:headers.update({\'Referer\':LISTING,\'X-Requested-With\':\'XMLHttpRequest\'})\n                with client.stream(row[\'method\'],url,data=data,headers=headers) as r:\n                    row[\'http\']=r.status_code\n                    if r.status_code!=200:raise Stop(\'http_\'+str(r.status_code))\n                    b=bytearray();started=time.monotonic()\n                    for block in r.iter_bytes():\n                        b.extend(block)\n                        if len(b)>limit:raise Stop(\'body_limit\')\n                        if time.monotonic()-started>25 or time.monotonic()-self.started>180:raise Stop(\'time_limit\')\n                    result={\'body\':bytes(b),\'http\':r.status_code,\'content_type\':r.headers.get(\'content-type\',\'\')}\n            row[\'http\']=result[\'http\']\n            if result[\'http\']!=200:raise Stop(\'http_\'+str(result[\'http\']))\n            if not result[\'body\'] or len(result[\'body\'])>limit:raise Stop(\'empty_or_large_body\')\n            row.update(bytes=len(result[\'body\']),sha256=hashlib.sha256(result[\'body\']).hexdigest())\n            return result\n        except Exception as e:\n            self.failed_hosts.add(p.hostname);row.update(error_type=type(e).__name__,reason=str(e) if isinstance(e,Stop) else \'transport_error\');raise\n\ndef page(body):\n    from bs4 import BeautifulSoup\n    s=BeautifulSoup(body,\'html.parser\')\n    text=\' \'.join(s.stripped_strings)\n    title=s.title.get_text(\' \',strip=True) if s.title else \'\'\n    if re.search(r\'captcha|anti.bot|verify you are human|access denied|проверка.{0,20}робот\',title+\' \'+text[:5000],re.I):raise Stop(\'access_challenge\')\n    if s.select(\'input[type=password]\'):raise Stop(\'login_required\')\n    return s\n\ndef initial_lukoil(body):\n    s=page(body)\n    scripts=\'\\n\'.join(t.get_text() for t in s.select(\'script:not([src])\'))\n    m=re.search(r\'\\bvar Tenders\\s*=\\s*\',scripts)\n    if not m:raise Stop(\'lukoil_native_listing_missing\')\n    data=json.JSONDecoder().raw_decode(scripts[m.end():])[0]\n    config=re.search(r\'searchDataUrl:\\s*"(/api/tenders/SearchTenders)"\',scripts)\n    constructor=re.search(r\'new TenderListViewModel\\(container,\\s*Tenders,\\s*(\\d+),\\s*(\\d+),\\s*(\\d+),\\s*(\\d+),\',scripts)\n    if not config or not constructor or \'method: "post"\' not in scripts or \'SearchQuery\' not in scripts:raise Stop(\'lukoil_search_contract_changed\')\n    # First-page Take=10 is the native listing size observed on this page.\n    if not isinstance(data,dict) or not isinstance(data.get(\'Items\'),dict):raise Stop(\'lukoil_listing_shape\')\n    params=dict(zip((\'Organization\',\'customer\',\'Country\',\'Region\'),constructor.groups()))\n    params.update(Take=\'10\',Tab=\'1\')\n    return data,params\n\ndef listing_rows(data):\n    if not isinstance(data,dict) or not isinstance(data.get(\'Items\'),dict) or not isinstance(data.get(\'Count\'),dict):raise Stop(\'lukoil_search_shape\')\n    rows=data[\'Items\'].get(\'AllItems\');count=data[\'Count\'].get(\'AllTotalCount\')\n    if not isinstance(rows,list) or type(count) is not int or count<0 or len(rows)>10 or count<len(rows):raise Stop(\'lukoil_search_shape\')\n    seen=set()\n    for r in rows:\n        if not isinstance(r,dict) or type(r.get(\'TenderId\')) is not int or r[\'TenderId\']<=0 or not r.get(\'Number\') or not r.get(\'Topic\'):raise Stop(\'lukoil_identity_missing\')\n        if r[\'TenderId\'] in seen:raise Stop(\'lukoil_duplicate_identity\')\n        seen.add(r[\'TenderId\'])\n    return rows,count\n\ndef summary(r):\n    from app.scoring.selection_policy import material_status\n    material=material_status({\'name\':r[\'Topic\']})\n    # Explicitly reject aluminium salts/chemicals even with very large weights.\n    if re.search(r\'сульфат|оксид|гидроксид|коагулянт|полиоксихлорид|реагент\',r[\'Topic\'],re.I):material=False\n    open_flags=all(r.get(k) is False for k in (\'IsCanceled\',\'IsFinished\',\'NeedToHide\',\'IsDisabled\'))\n    return {\'external_id\':str(r[\'TenderId\']),\'number\':r[\'Number\'],\'title\':r[\'Topic\'],\n            \'deadline_raw\':r.get(\'DateFinish\'),\'deadline_timezone_verified\':False,\n            \'native_open_flags\':open_flags,\'aluminium_material_confirmed\':material,\n            \'eligibility\':\'not_verified\',\'documents_count\':len(r.get(\'Files\') or [])}\n\ndef documents(r):\n    docs=r.get(\'Files\')\n    if not isinstance(docs,list):raise Stop(\'lukoil_documents_shape\')\n    out=[];seen=set()\n    for d in docs:\n        if not isinstance(d,dict) or d.get(\'TenderId\')!=r[\'TenderId\'] or type(d.get(\'FileId\')) is not int or d[\'FileId\']<=0 or d.get(\'AllowDownload\') is not True:raise Stop(\'lukoil_document_identity_or_access\')\n        if d[\'FileId\'] in seen:raise Stop(\'lukoil_duplicate_document_id\')\n        seen.add(d[\'FileId\']);u=d.get(\'FileDownloadUrl\') or \'\';p=urlsplit(u)\n        m=re.fullmatch(r\'/FileSystem/(\\d+)/(\\d+)\\.([A-Za-z0-9]+)\',p.path)\n        if p.scheme!=\'https\' or p.netloc!=\'lukoil.ru\' or not m or int(m[2])!=d[\'FileId\'] or int(m[1])!=d.get(\'LibraryType\') or p.fragment or parse_qsl(p.query)!=[(\'dl\',\'1\')]:raise Stop(\'lukoil_document_url\')\n        if m[3].lower() not in (\'pdf\',\'xls\',\'xlsx\',\'doc\',\'docx\',\'zip\',\'rar\',\'7z\'):raise Stop(\'lukoil_document_format\')\n        out.append({\'id\':str(d[\'FileId\']),\'name\':d.get(\'Title\') or d.get(\'FileName\'),\'extension\':\'.\'+m[3].lower(),\'url\':u})\n    return out\n\n\n# xlrd 2.0.1, BSD licence retained inside the compressed source bundle.\n# Isolated in-memory package; no pip, files or changes to application imports.\n\n\ndef inspect_document(data,ext):\n    import tempfile\n    from pathlib import Path\n    from app.ocr.document_formats import read_document,validate_document_bytes\n    validate_document_bytes(data,ext)\n    with tempfile.TemporaryDirectory(prefix=\'corporate-document-check-\') as folder:\n        path=Path(folder)/(\'document\'+ext);path.write_bytes(data)\n        extracted=read_document(path,allow_ocr=False)\n    text=extracted.full_text\n    return {\'bytes\':len(data),\'sha256\':hashlib.sha256(data).hexdigest(),\'signature_verified\':True,\n            \'extraction\':\'shared_document_reader_no_ocr\',\'quality_status\':extracted.status.value,\n            \'text_characters\':len(text),\'pages\':extracted.pages_count,\n            \'aluminium_mentions\':[line[:500] for line in text.splitlines() if re.search(r\'алюмин|(?<!\\w)АМ[гГЦц]\\d|АД31\',line)][:12],\n            \'mentions_are_not_position_approval\':True,\'temporary_files_removed\':True,\n            \'full_documentation_requires_request\':bool(re.search(r\'полный\\s+комплект.{0,100}документации.{0,120}(?:после|по\\s+запросу)\', \' \'.join(text.split()), re.I)),\n            \'access_note\':\'public_attachments_do_not_prove_full_tender_documentation\'}\n\ndef check_lukoil(reader):\n    result={\'source\':\'lukoil\',\'pipeline_ready\':False,\'queued_count\':0,\'status\':\'not_checked\',\'searches\':[],\'errors\':[]}\n    try:\n        initial,params=initial_lukoil(reader.get(LISTING)[\'body\']);rows,total=listing_rows(initial)\n        result[\'listing\']={\'count_on_page\':len(rows),\'total\':total,\'coverage\':\'first_page\'}\n        reader.search_params=params;reader.allowed.add(LUKOIL+\'/api/tenders/SearchTenders\')\n        candidates={}\n        for q in (\'алюм\',\'металлопродукци\'):\n            data=json.loads(reader.get(LUKOIL+\'/api/tenders/SearchTenders\',data={**params,\'SearchQuery\':quote(q)})[\'body\'])\n            found,count=listing_rows(data)\n            result[\'searches\'].append({\'query\':q,\'total\':count,\'complete\':len(found)==count,\'items\':[summary(r) for r in found]})\n            for r in found:\n                info=summary(r)\n                if info[\'native_open_flags\'] and info[\'aluminium_material_confirmed\'] is not False:candidates[r[\'TenderId\']]=r\n        # Check one material candidate, all listed files within the request budget.\n        # No result is labelled suitable before per-position eligibility and LLM.\n        selected=next(iter(candidates.values()),None)\n        if selected:\n            docs=documents(selected);result[\'sample_card\']=summary(selected);result[\'documents\']=docs;result[\'document_checks\']=[]\n            for d in docs:\n                try:\n                    reader.allowed.add(d[\'url\'])\n                    body=reader.get(d[\'url\'],limit=15_000_000)[\'body\']\n                    result[\'document_checks\'].append({\'id\':d[\'id\'],\'name\':d[\'name\'],**inspect_document(body,d[\'extension\'])})\n                except Exception as exc:\n                    result[\'errors\'].append({\'document_id\':d[\'id\'],\'type\':type(exc).__name__,\'reason\':str(exc) if isinstance(exc,(Stop,ValueError)) else \'document_read_failed\'})\n            result[\'all_documents_checked\']=len(docs)==len(result[\'document_checks\'])\n            result[\'full_documentation_requires_request\']=any(d.get(\'full_documentation_requires_request\') for d in result[\'document_checks\'])\n            result[\'all_documents_quality_accepted\']=result[\'all_documents_checked\'] and all(d[\'quality_status\'] in (\'done\',\'not_required\') and d[\'text_characters\']>0 for d in result[\'document_checks\'])\n        result[\'status\']=\'incomplete\' if result[\'errors\'] else \'public_search_verified_adapter_not_installed\'\n    except Exception as e:\n        result[\'status\']=\'incomplete\';result[\'errors\'].append({\'type\':type(e).__name__,\'reason\':str(e) if isinstance(e,Stop) else \'check_failed\',**({\'missing_module\':e.name} if isinstance(e,ModuleNotFoundError) else {})})\n    return result\n\ndef norn_evidence(body,url):\n    # Inspect before pruning navigation: earlier pruning could discard content.\n    s=page(body)\n    def clean_url(raw):\n        p=urlsplit(urljoin(url,raw))\n        if p.scheme!=\'https\' or p.username or p.password or p.hostname!=\'nornickel.ru\':return None\n        if any(re.search(r\'token|session|auth|password|secret|signature|key\',k,re.I) for k,v in parse_qsl(p.query)):return None\n        return p._replace(fragment=\'\').geturl()\n    markers=re.compile(r\'tender|закуп|тендер|procure|purchase|ajax|__NEXT_DATA__|__NUXT__\',re.I)\n    scripts=[]\n    for node in s.select(\'script\'):\n        raw=node.string or node.get_text();src=clean_url(node.get(\'src\',\'\')) if node.get(\'src\') else None\n        entry={\'id\':node.get(\'id\'),\'type\':node.get(\'type\'),\'src\':src,\'characters\':len(raw)}\n        # Do not execute or import site scripts, and do not print cookies/tokens.\n        hits=list(markers.finditer(raw))[:3]\n        excerpts=[]\n        for hit in hits:\n            fragment=raw[max(0,hit.start()-150):hit.end()+650]\n            if not re.search(r\'cookie|password|authorization|access.?token|secret\',fragment,re.I):excerpts.append(fragment)\n        if excerpts:entry[\'public_contract_excerpts\']=excerpts\n        if src or excerpts or node.get(\'type\')==\'application/json\':scripts.append(entry)\n    links=[]\n    for a in s.select(\'a[href]\'):\n        u=clean_url(a[\'href\'])\n        if u and (re.search(r\'\\.(?:zip|rar|7z|docx?|xlsx?|pdf)$\',urlsplit(u).path,re.I) or \'/suppliers/tenders/\' in u):\n            links.append({\'text\':a.get_text(\' \',strip=True)[:180],\'url\':u})\n    roots=[{\'tag\':t.name,\'id\':t.get(\'id\'),\'class\':t.get(\'class\'),\'attributes\':{k:str(v)[:500] for k,v in t.attrs.items() if k.startswith(\'data-\') and not re.search(\'token|auth|secret|key\',k,re.I)}} for t in s.find_all([\'main\',\'div\',\'section\']) if markers.search(str(t.get(\'id\',\'\'))+\' \'+str(t.get(\'class\',\'\')))][:20]\n    title=s.title.get_text(\' \',strip=True) if s.title else \'\'\n    forms=[{\'action\':clean_url(f.get(\'action\',\'\')),\'method\':f.get(\'method\',\'get\'),\'fields\':[{\'name\':i.get(\'name\'),\'type\':i.get(\'type\',\'text\')} for i in f.select(\'input[name]\')[:20]]} for f in s.select(\'form\')[:5]]\n    for tag in s([\'script\',\'style\']):tag.decompose()\n    main=s.find(\'main\') or s\n    text=main.get_text(\' \',strip=True)\n    return {\'url\':url,\'title\':title,\'text_characters\':len(text),\'public_text_excerpt\':text[:14000],\'links\':links[:40],\'forms\':forms,\'script_evidence\':scripts[:30],\'tender_containers\':roots,\'tables\':len(s.select(\'table\')),\'links_found\':len(links),\'scripts_found\':len(scripts),\'coverage\':\'page_structure_only_not_full_procurement_listing\'}\n\ndef norn_app(body):\n    s=page(body)\n    values=[]\n    for tag in s.select(\'script:not([src])\'):\n        raw=tag.string or tag.get_text()\n        match=re.search(r\'(?:^|;)\\s*(?:var\\s+)?(?:window\\.)?App\\s*=\\s*\',raw)\n        if match:\n            try:value,end=json.JSONDecoder().raw_decode(raw[match.end():])\n            except (ValueError,RecursionError):raise Stop(\'norn_app_not_literal_json\')\n            if not isinstance(value,dict) or not isinstance(value.get(\'components\'),dict):raise Stop(\'norn_app_components_missing\')\n            values.append(value[\'components\'])\n    if len(values)!=1:raise Stop(\'norn_app_assignment_missing_or_ambiguous\')\n    # Do not expose or use App.system, cookie/session data or contact fields.\n    return values[0]\n\n\ndef norn_text(raw):\n    from html import unescape\n    from bs4 import BeautifulSoup\n    if not isinstance(raw,str):return \'\'\n    # Plain titles/filenames are not markup; avoid BeautifulSoup\'s locator warning.\n    return BeautifulSoup(raw,\'html.parser\').get_text(\' \',strip=True) if re.search(r\'</?[A-Za-z][^>]*>\',raw) else unescape(raw).strip()\n\n\ndef norn_document(raw):\n    if not isinstance(raw,dict):return None,\'documentation_missing\'\n    href=raw.get(\'link\')\n    if not isinstance(href,str) or not href.strip():return None,\'document_link_missing\'\n    try:\n        u=urlsplit(urljoin(NORN,href.strip()))\n        if u.scheme!=\'https\' or u.hostname!=\'nornickel.ru\' or u.username or u.password or u.port not in (None,443):return None,\'external_or_unapproved_document_link\'\n        if any(re.search(r\'token|auth|session|secret|key|password|signature\',k,re.I) for k,v in parse_qsl(u.query)):return None,\'restricted_document_link\'\n        if not u.path or u.path==\'/\':return None,\'document_link_missing\'\n        return u._replace(fragment=\'\').geturl(),\'public_link_not_downloaded\'\n    except ValueError:return None,\'invalid_document_link\'\n\n\ndef norn_component(data,section):\n    from app.scoring.selection_policy import material_status\n    if not isinstance(data,dict) or not isinstance(data.get(\'items\'),list):raise Stop(\'norn_tender_items_shape\')\n    items=data[\'items\']\n    if len(items)>100:raise Stop(\'norn_tender_items_limit\')\n    out=[]\n    for item in items:\n        if not isinstance(item,dict) or not isinstance(item.get(\'name\'),str):raise Stop(\'norn_tender_item_shape\')\n        title=norn_text(item[\'name\'])\n        doc=item.get(\'documentation\');document,doc_reason=norn_document(doc)\n        # A printed reference is not a platform ID. Never fabricate one from a hash.\n        match=re.match(r\'^(?:№\\s*)?(\\d{5,}(?:/\\d+)?)\\s*(?::|[«\\s])\',title)\n        raw_date=item.get(\'activeTo\');date_utc=None\n        if type(raw_date) in (int,float) and 946684800<=raw_date<=4102444800:\n            date_utc=datetime.fromtimestamp(raw_date,timezone.utc).isoformat()\n        material=material_status({\'name\':title})\n        if re.search(r\'сульфат|оксид|гидроксид|коагулянт|полиоксихлорид|реагент\',title,re.I):material=False\n        out.append({\'source\':\'nornickel\',\'section\':section,\'native_id\':item.get(\'id\') if type(item.get(\'id\')) in (str,int) else None,\n                    \'reference_from_title\':match.group(1) if match else None,\'identity_basis\':\'unverified_public_listing\',\n                    \'title\':title[:1500],\'deadline_raw\':raw_date if type(raw_date) in (str,int,float) else None,\n                    \'deadline_timestamp_utc\':date_utc,\'deadline_precision\':\'site_displays_date_only\',\'deadline_verified\':False,\n                    \'aluminium_material_confirmed\':material,\'document_url\':document,\'document_state\':doc_reason,\n                    \'documentation_fields\':sorted(k for k in doc if k in (\'link\',\'type\',\'size\')) if isinstance(doc,dict) else [],\n                    \'identity_and_freshness_verified\':False})\n    nav=data.get(\'nav\')\n    return {\'count_on_page\':len(items),\'items\':out,\'navigation\':{k:v for k,v in (nav.items() if isinstance(nav,dict) else []) if k in (\'current\',\'total\',\'count\',\'pageSize\') and isinstance(v,(int,str))},\'coverage\':\'first_page_only\',\'documents_verified\':False}\n\n\ndef check_nornickel(reader):\n    result={\'source\':\'nornickel\',\'pipeline_ready\':False,\'queued_count\':0,\'status\':\'not_checked\',\'pages\':[],\'errors\':[]}\n    script=None;script_url=NORN+\'/local/templates/z-template/static/javascripts/app.js\'\n    try:\n        for section,url in zip((\'central\',\'local\'),NORN_PAGES):\n            body=reader.get(url)[\'body\'];components=norn_app(body)\n            key=section+\'-tenders\'\n            row={\'url\':url,\'component\':key,\'available_tender_components\':[k for k in components if k in (\'central-tenders\',\'local-tenders\')],\n                 \'initial\':norn_component(components.get(key),section)}\n            result[\'pages\'].append(row)\n            if script is None:\n                soup=page(body)\n                observed={urljoin(url,t[\'src\']) for t in soup.select(\'script[src]\')}\n                if script_url not in observed:raise Stop(\'norn_public_script_not_linked\')\n                reader.allowed.add(script_url)\n                script=reader.get(script_url,limit=6_000_000)[\'body\'].decode(\'utf-8\')\n            endpoint=\'/api/\'+key+\'/\'\n            if \'url:"\'+endpoint+\'",method:"get",params:\' not in script or \'["\'+key+\'"]\' not in script:\n                raise Stop(\'norn_public_search_contract_changed\')\n            row[\'searches\']=[]\n            for query in NORN_QUERIES:\n                u=NORN+endpoint+\'?\'+urlencode({\'q\':query,\'page\':1})\n                reader.allowed.add(u)\n                data=json.loads(reader.get(u)[\'body\'])\n                parsed=norn_component(data,section)\n                nav=parsed[\'navigation\']\n                count=nav.get(\'count\')\n                complete=type(count) is int and count==parsed[\'count_on_page\'] and nav.get(\'current\')==1\n                row[\'searches\'].append({\'query\':query,\'complete\':complete,**parsed})\n            row[\'keyword_search\']=row[\'searches\'][0]\n        result[\'status\']=\'public_items_read_adapter_not_installed\'\n    except Exception as exc:\n        result[\'status\']=\'incomplete\';result[\'errors\'].append({\'type\':type(exc).__name__,\'reason\':str(exc) if isinstance(exc,Stop) else \'public_read_failed\'})\n    return result\n\ndef main():\n    signal.signal(signal.SIGALRM,lambda *_: (_ for _ in ()).throw(SystemExit(\'CORPORATE_CHECK_TIME_LIMIT: incomplete; no business tasks\')))\n    signal.alarm(240)\n    try:\n        from app.ocr.document_formats import VERSION as reader_version\n    except ImportError:\n        raise SystemExit(\'DOCUMENT_FORMATS_NOT_INSTALLED: run this file with --install-document-formats first; no HTTP or tasks started\')\n    print(\'SHARED_DOCUMENT_READER:\',reader_version,flush=True)\n    reader=None\n    try:\n        print(\'CORPORATE_CHECK_BEGIN:\',VERSION,datetime.now(timezone.utc).isoformat(),flush=True)\n        for check in (check_lukoil,check_nornickel):\n            reader=Reader();out=check(reader);out[\'requests\']=reader.requests\n            out[\'transport\']={\'max_requests\':reader.max_requests,\'listing_read_retries\':reader.read_retries,\'retry_limit\':1}\n            print(json.dumps(out,ensure_ascii=False,indent=2),flush=True)\n            reader.close()\n    finally:\n        if reader is not None:reader.close()\n        signal.alarm(0)\n    print(\'READ_ONLY_CORPORATE: no installs, DB writes, business tasks, OCR, LLM or notifications; temporary document/conversion files removed. No sources enabled by this check.\',flush=True)\n\nif __name__==\'__main__\':main()\n'

def check_corporate_platforms():
 try:
  services=run(['docker','compose','ps','--services','--status','running'],capture_output=True,text=True,timeout=20).stdout.splitlines()
  if 'app' not in services:raise SystemExit('APP_NOT_RUNNING: no services started; public check not performed')
  run(['docker','compose','exec','-T','app','python','-'],input=CORPORATE_CHECK,text=True,timeout=270)
 except (subprocess.TimeoutExpired,subprocess.CalledProcessError,OSError) as exc:
  raise SystemExit('CORPORATE_CHECK_INCOMPLETE: '+type(exc).__name__+'; no automatic retry or installation')


DOCUMENT_MODULES = {'app/ocr/document_formats.py': '"""Shared bounded document extraction; no network, queues, database or LLM."""\nimport csv\nimport io\nimport zipfile\nimport tempfile\nfrom pathlib import Path\n\nVERSION = \'shared-document-formats-20261028-1\'\nTEXT = {\'.txt\', \'.md\', \'.csv\', \'.tsv\'}\nIMAGES = {\'.jpg\', \'.jpeg\', \'.png\', \'.tif\', \'.tiff\', \'.bmp\', \'.webp\'}\nARCHIVES = {\'.zip\', \'.rar\', \'.7z\'}\nDOCUMENTS = TEXT | IMAGES | {\'.pdf\', \'.doc\', \'.docx\', \'.xls\', \'.xlsx\'}\nMAX_BYTES = 20 * 1024 * 1024\nMAX_EXPANDED = 80 * 1024 * 1024\nMAX_CELLS = 500_000\nMAX_TEXT = 2_000_000\n\n\ndef decode_text(data):\n    if data.startswith((b\'\\xff\\xfe\', b\'\\xfe\\xff\')):\n        text = data.decode(\'utf-16\')\n    else:\n        try: text = data.decode(\'utf-8-sig\')\n        except UnicodeDecodeError: text = data.decode(\'cp1251\')\n    if any(ord(c)<32 and c not in \'\\r\\n\\t\' for c in text):\n        raise ValueError(\'document_binary_content_in_text\')\n    return text\n\n\ndef validate_document_bytes(data, suffix):\n    suffix = suffix.lower()\n    if suffix not in DOCUMENTS | ARCHIVES:\n        raise ValueError(\'document_format_not_supported:\' + suffix)\n    if not data or len(data)>MAX_BYTES:\n        raise ValueError(\'document_empty_or_size_limit\')\n    if data.lstrip().lower().startswith((b\'<html\', b\'<!doctype html\')):\n        raise ValueError(\'document_html_instead_of_attachment\')\n    valid = False\n    if suffix in TEXT:\n        decode_text(data); valid=True\n    elif suffix in {\'.docx\',\'.xlsx\',\'.zip\'}:\n        with zipfile.ZipFile(io.BytesIO(data)) as z:\n            members=z.infolist()\n            if len(members)>2000 or sum(x.file_size for x in members)>MAX_EXPANDED:\n                raise ValueError(\'document_unpacked_size_limit\')\n            if any(x.flag_bits & 1 for x in members):raise ValueError(\'document_password_required\')\n            names=z.namelist()\n            valid = suffix==\'.zip\' or (\'[Content_Types].xml\' in names and (\'word/document.xml\' if suffix==\'.docx\' else \'xl/workbook.xml\') in names)\n    elif suffix in {\'.doc\',\'.xls\'}:valid=data.startswith(bytes.fromhex(\'D0CF11E0A1B11AE1\'))\n    elif suffix==\'.pdf\':valid=data.startswith(b\'%PDF-\')\n    elif suffix==\'.rar\':valid=data.startswith((b\'Rar!\\x1a\\x07\\x00\',b\'Rar!\\x1a\\x07\\x01\\x00\'))\n    elif suffix==\'.7z\':valid=data.startswith(b\'7z\\xbc\\xaf\\x27\\x1c\')\n    elif suffix in IMAGES:\n        from PIL import Image\n        expected={\'.jpg\':\'JPEG\',\'.jpeg\':\'JPEG\',\'.png\':\'PNG\',\'.tif\':\'TIFF\',\'.tiff\':\'TIFF\',\'.bmp\':\'BMP\',\'.webp\':\'WEBP\'}\n        with Image.open(io.BytesIO(data)) as image:\n            valid=image.format==expected[suffix]\n            if not 1<=getattr(image,\'n_frames\',1)<=100:raise ValueError(\'document_image_page_limit\')\n            image.verify()\n    if not valid:raise ValueError(\'document_signature_mismatch:\' + suffix)\n\n\ndef result_from_pages(pages, uncertain=False):\n    from app.ocr.pipeline import ExtractionResult, OCRStatus, TESSERACT_CONFIDENCE_THRESHOLD\n    full=\'\\n\\n\'.join(p.text for p in pages)\n    if len(full)>MAX_TEXT:raise ValueError(\'document_text_limit_no_partial_result\')\n    bad=uncertain or not pages or any(not p.text.strip() or p.confidence<TESSERACT_CONFIDENCE_THRESHOLD for p in pages)\n    status=OCRStatus.LOW_CONFIDENCE if bad else (OCRStatus.DONE if any(p.is_scanned for p in pages) else OCRStatus.NOT_REQUIRED)\n    return ExtractionResult(full_text=full,pages=pages,status=status,pages_count=len(pages))\n\n\ndef spreadsheet(path):\n    from app.ocr.pipeline import PageExtraction\n    from openpyxl.utils.cell import get_column_letter\n    pages=[];cells=0;uncertain=False\n    if path.suffix.lower()==\'.xls\':\n        from app.ocr.xls_reader import xls_reader\n        book=xls_reader().open_workbook(file_contents=path.read_bytes(),on_demand=True)\n        try:\n            for i in range(book.nsheets):\n                sh=book.sheet_by_index(i);cells+=sh.nrows*sh.ncols\n                if cells>MAX_CELLS:raise ValueError(\'document_sheet_cell_limit\')\n                lines=[]\n                for rn in range(sh.nrows):\n                    vals=[]\n                    for cn in range(sh.ncols):\n                        c=sh.cell(rn,cn)\n                        if c.ctype==5:uncertain=True\n                        if c.value not in (\'\',None):vals.append(f\'{get_column_letter(cn+1)}{rn+1}={c.value}\')\n                    if vals:lines.append(\' | \'.join(vals))\n                if lines:pages.append(PageExtraction(len(pages)+1,\'=== Лист: \'+sh.name+\' ===\\n\'+\'\\n\'.join(lines),100.0,False))\n        finally:book.release_resources()\n    else:\n        from openpyxl import load_workbook\n        book=load_workbook(path,read_only=True,data_only=True,keep_links=False)\n        formulas=load_workbook(path,read_only=True,data_only=False,keep_links=False)\n        try:\n            for sh in book:\n                cells+=(sh.max_row or 0)*(sh.max_column or 0)\n                if cells>MAX_CELLS:raise ValueError(\'document_sheet_cell_limit\')\n                lines=[]\n                from itertools import zip_longest\n                for row,frow in zip_longest(sh.iter_rows(),formulas[sh.title].iter_rows(),fillvalue=()):\n                    vals=[]\n                    for c,fc in zip_longest(row,frow):\n                        if fc is not None and fc.data_type==\'f\' and (c is None or c.value is None):uncertain=True\n                        if c is not None and c.data_type==\'e\':uncertain=True\n                        if c is not None and c.value is not None:vals.append(f\'{c.coordinate}={c.value}\')\n                    if vals:lines.append(\' | \'.join(vals))\n                if lines:pages.append(PageExtraction(len(pages)+1,\'=== Лист: \'+sh.title+\' ===\\n\'+\'\\n\'.join(lines),100.0,False))\n            with zipfile.ZipFile(path) as z:\n                if any(n.startswith(\'xl/media/\') for n in z.namelist()):uncertain=True\n        finally:book.close();formulas.close()\n    return result_from_pages(pages,uncertain)\n\n\ndef read_document(file_path, *, allow_ocr=True):\n    from app.ocr import pipeline as p\n    path=Path(file_path);suffix=path.suffix.lower()\n    if not path.is_file() or path.stat().st_size>MAX_BYTES:raise ValueError(\'document_missing_or_size_limit\')\n    data=path.read_bytes();validate_document_bytes(data,suffix)\n    if suffix in ARCHIVES:\n        from app.sources.gpb.archives import unpack\n        from app.sources.schemas import SourceDocument\n        pages=[];uncertain=False\n        with tempfile.TemporaryDirectory(prefix=\'tender-archive-read-\') as tmp:\n            docs,_,_=unpack(data,SourceDocument(name=path.name,external_id=\'local-document\',url=None),Path(tmp),0,0)\n            for d in docs:\n                child=read_document(d.local_path,allow_ocr=allow_ocr)\n                if child.status not in (p.OCRStatus.DONE,p.OCRStatus.NOT_REQUIRED):uncertain=True\n                if not child.full_text.strip():uncertain=True\n                for page in child.pages:\n                    # Keep actual blank pages blank for the quality gate.\n                    text=(\'=== Файл: \'+d.name+\'; страница/лист: \'+str(page.page_number)+\' ===\\n\'+page.text) if page.text.strip() else \'\'\n                    pages.append(p.PageExtraction(len(pages)+1,text,page.confidence,page.is_scanned))\n        return result_from_pages(pages,uncertain)\n    if suffix in {\'.xls\',\'.xlsx\'}:return spreadsheet(path)\n    if suffix in TEXT:\n        text=decode_text(data)\n        if len(text)>MAX_TEXT:raise ValueError(\'document_text_limit_no_partial_result\')\n        if suffix in {\'.csv\',\'.tsv\'}:\n            delimiter=\'\\t\' if suffix==\'.tsv\' else None\n            if delimiter is None:\n                try:delimiter=csv.Sniffer().sniff(text[:8192],delimiters=\',;\\t\').delimiter\n                except csv.Error:delimiter=\',\'\n            lines=[];cells=0\n            for i,row in enumerate(csv.reader(io.StringIO(text),delimiter=delimiter,strict=True),1):\n                cells+=len(row)\n                if cells>MAX_CELLS:raise ValueError(\'document_sheet_cell_limit\')\n                if any(row):lines.append(\' | \'.join(f\'R{i}C{j}={v}\' for j,v in enumerate(row,1) if v))\n            text=\'\\n\'.join(lines)\n        return result_from_pages([p.PageExtraction(1,text,100.0,False)])\n    if suffix==\'.pdf\':\n        if allow_ocr:result=p.extract_pdf(str(path))\n        else:result=result_from_pages(p._extract_pdf_text_layer(str(path)))\n    elif suffix in IMAGES:\n        if not allow_ocr:raise ValueError(\'document_requires_ocr_not_run_in_read_check\')\n        result=p.extract_image(str(path))\n    elif suffix in {\'.doc\',\'.docx\'}:\n        if suffix==\'.doc\':\n            from app.ocr.legacy_word import converted_docx\n            with converted_docx(str(path)) as converted:return read_document(converted,allow_ocr=allow_ocr)\n        result=p.extract_docx(str(path))\n        with zipfile.ZipFile(path) as z:\n            media=any(n.startswith(\'word/media/\') for n in z.namelist())\n        # Embedded scans/drawings are not silently treated as fully extracted.\n        if media:return result_from_pages(result.pages,uncertain=True)\n    else:raise ValueError(\'document_format_not_supported:\' + suffix)\n    uncertain=result.status not in (p.OCRStatus.DONE,p.OCRStatus.NOT_REQUIRED)\n    if not allow_ocr and any(pg.is_scanned for pg in result.pages):uncertain=True\n    return result_from_pages(result.pages,uncertain)\n', 'app/ocr/xls_reader.py': '"""Bundled BSD-licensed xlrd 2.0.1; isolated in-memory package."""\n\nimport hashlib, json\n\nclass Stop(ValueError): pass\n\nXLRD_BUNDLE = \'\'\n\nXLRD_SHA256 = \'5c13b855a1322ef44cfec9768419e48b415fc78da60021e8da6b5ba97247c1e7\'\n\ndef xls_reader():\n    import base64,zlib,sys,importlib.abc,importlib.util,importlib\n    packed=base64.b64decode(XLRD_BUNDLE)\n    if hashlib.sha256(packed).hexdigest()!=XLRD_SHA256:raise Stop(\'bundled_xls_reader_checksum\')\n    sources=json.loads(zlib.decompress(packed))[\'sources\']\n    prefix=\'_corporate_audit_xlrd\'\n    class MemoryReader(importlib.abc.MetaPathFinder,importlib.abc.Loader):\n        def find_spec(self,fullname,path=None,target=None):\n            if fullname==prefix:key=\'__init__\'\n            elif fullname.startswith(prefix+\'.\'):key=fullname[len(prefix)+1:]\n            else:return None\n            if key not in sources:return None\n            return importlib.util.spec_from_loader(fullname,self,is_package=key==\'__init__\')\n        def create_module(self,spec):return None\n        def exec_module(self,module):\n            key=\'__init__\' if module.__name__==prefix else module.__name__[len(prefix)+1:]\n            exec(compile(sources[key],\'<bundled-xlrd>/\'+key+\'.py\',\'exec\'),module.__dict__)\n    if prefix not in sys.modules:sys.meta_path.insert(0,MemoryReader())\n    return importlib.import_module(prefix)\n'}
DOCUMENT_OLD_ENTRY = 'def extract_document(file_path: str) -> ExtractionResult:\n    """\n    Универсальная точка входа — определяет тип файла по расширению\n    и вызывает соответствующий обработчик.\n    """\n    if Path(file_path).suffix.lower() in {\'.txt\', \'.md\'}:\n        return _extract_plain_text_v20261019(file_path)\n    suffix = Path(file_path).suffix.lower()\n\n    handlers = {\n        ".pdf": extract_pdf,\n        ".docx": extract_docx,\n        ".doc": extract_doc,\n        ".xlsx": extract_xlsx,\n        ".jpg": extract_image,\n        ".jpeg": extract_image,\n        ".png": extract_image,\n        ".tiff": extract_image,\n        ".tif": extract_image,\n    }\n\n    handler = handlers.get(suffix)\n    if not handler:\n        raise ValueError(f"Неподдерживаемый тип файла: {suffix}")\n\n    logger.info("extracting_document", path=file_path, type=suffix)\n    return handler(file_path)'
DOCUMENT_ENTRY = 'def extract_document(file_path: str) -> ExtractionResult:\n    """Shared format reader; retains the existing document quality gate."""\n    from app.ocr.document_formats import read_document\n    return read_document(file_path)\n'
DOCUMENT_LOADER_PATCHES = [('EXTENSIONS', "EXTENSIONS={'.pdf','.doc','.docx','.xls','.xlsx','.txt','.png','.jpg','.jpeg','.tif','.tiff'}", "EXTENSIONS={'.pdf','.doc','.docx','.xls','.xlsx','.txt','.md','.csv','.tsv','.png','.jpg','.jpeg','.tif','.tiff','.bmp','.webp'}"), ('validate_bytes', "def validate_bytes(data,suffix):\n    if not data:raise ValueError('metal_it_empty_document')\n    if data.lstrip().lower().startswith((b'<html',b'<!doctype html')):raise ValueError('metal_it_html_document')\n    if suffix in ('.docx','.xlsx','.zip'):\n        valid=zipfile.is_zipfile(io.BytesIO(data))\n        if valid:\n            with zipfile.ZipFile(io.BytesIO(data)) as z:\n                valid=(sum(x.file_size for x in z.infolist())<=MAX_TOTAL and len(z.infolist())<=2000)\n                if suffix!='.zip':valid=valid and '[Content_Types].xml' in z.namelist() and any(n.startswith('word/' if suffix=='.docx' else 'xl/') for n in z.namelist())\n    elif suffix=='.pdf':valid=data.startswith(b'%PDF-')\n    elif suffix in ('.doc','.xls'):valid=data.startswith(bytes.fromhex('D0CF11E0A1B11AE1'))\n    elif suffix=='.png':valid=data.startswith(b'\\x89PNG\\r\\n\\x1a\\n')\n    elif suffix in ('.jpg','.jpeg'):valid=data.startswith(b'\\xff\\xd8\\xff')\n    elif suffix in ('.tif','.tiff'):\n        from PIL import Image\n        valid=False\n        if data.startswith((b'II\\x2a\\x00',b'MM\\x00\\x2a',b'II\\x2b\\x00',b'MM\\x00\\x2b')):\n            with Image.open(io.BytesIO(data)) as image:\n                if image.format!='TIFF':raise ValueError('metal_it_document_signature_mismatch')\n                if not 1<=image.n_frames<=100:raise ValueError('metal_it_image_page_limit')\n                image.verify()\n            valid=True\n    elif suffix=='.txt':\n        try:data.decode('utf-8-sig');valid=b'\\x00' not in data\n        except UnicodeError:valid=False\n    else:valid=False\n    if not valid:raise ValueError('metal_it_document_signature_mismatch')", 'def validate_bytes(data,suffix):\n    from app.ocr.document_formats import validate_document_bytes\n    return validate_document_bytes(data,suffix)'), ('references', "def references(trade):\n    docs={}\n    groups=[(trade,TRADE_FIELDS)]+[(lot,LOT_FIELDS) for lot in trade.get('lots',[])]\n    for parent,fields in groups:\n      for field in fields:\n          rows=parent.get(field)\n          if not isinstance(rows,list):raise ValueError('metal_it_document_list_missing')\n          for d in rows:\n              name=filename(d.get('name'));url=urljoin('https://etp.metal-it.ru',d.get('href') or '')\n              if not safe_url(url):raise ValueError('metal_it_invalid_document_url')\n              if Path(name).suffix.lower() not in EXTENSIONS|{'.zip'}:\n                  raise ValueError('metal_it_unsupported_document_format')\n              uid=str(d.get('id') or '')\n              if not uid.isdigit():raise ValueError('metal_it_invalid_document_id')\n              doc=SourceDocument(external_id=uid,name=name,url=url)\n              if uid in docs and docs[uid]!=doc:raise ValueError('metal_it_duplicate_document_id')\n              docs[uid]=doc\n    if not docs:raise ValueError('metal_it_no_public_documents')\n    if len(docs)>8:raise ValueError('metal_it_document_limit')\n    return list(docs.values())", "def references(trade):\n    docs={}\n    groups=[(trade,TRADE_FIELDS)]+[(lot,LOT_FIELDS) for lot in trade.get('lots',[])]\n    for parent,fields in groups:\n      for field in fields:\n          rows=parent.get(field)\n          if not isinstance(rows,list):raise ValueError('metal_it_document_list_missing')\n          for d in rows:\n              name=filename(d.get('name'));url=urljoin('https://etp.metal-it.ru',d.get('href') or '')\n              if not safe_url(url):raise ValueError('metal_it_invalid_document_url')\n              if Path(name).suffix.lower() not in EXTENSIONS|{'.zip','.rar','.7z'}:\n                  raise ValueError('metal_it_unsupported_document_format')\n              uid=str(d.get('id') or '')\n              if not uid.isdigit():raise ValueError('metal_it_invalid_document_id')\n              doc=SourceDocument(external_id=uid,name=name,url=url)\n              if uid in docs and docs[uid]!=doc:raise ValueError('metal_it_duplicate_document_id')\n              docs[uid]=doc\n    if not docs:raise ValueError('metal_it_no_public_documents')\n    if len(docs)>8:raise ValueError('metal_it_document_limit')\n    return list(docs.values())")]
DOCUMENT_TESTS = 'REQUIRE_OFFICE=True\n"""Offline format fixtures. No database, broker, HTTP, business OCR or LLM calls."""\nimport base64, zlib, io, tempfile, unittest, zipfile, shutil, subprocess\nfrom pathlib import Path\nfrom unittest.mock import patch\nfrom app.ocr import pipeline as p\nfrom app.ocr import document_formats as f\nfrom PIL import Image\nfrom openpyxl import Workbook\nfrom docx import Document\nimport fitz\n\nFIXTURES = {\'xls\': \'\', \'rar\': \'UmFyIRoHAM+QcwAADQAAAAAAAAAa0HQAgC0AKQAAACkAAAADDgmsfAAAAAAUMA0ApIEAAHBvc2l0aW9ucy50eHTQkNC70Y7QvNC40L3QuNC10LLRi9C5INC70LjRgdGCIDYwMCDQutCzCsQ9ewBABwA=\', \'7z\': \'N3q8ryccAANGzAijMQAAAAAAAABOAAAAAAAAANoj48EAaCQWC7WGw2AammH7kSw8FzA/AFbnUvh//Vw7Fry+IlUaRkaQaJm7T7lCv//q3gAAAQQGAAEJMQAHCwEAASMDAQEFXQAAgAAMKQAICgEOCax8AAAFAREdAHAAbwBzAGkAdABpAG8AbgBzAC4AdAB4AHQAAAAVBgEAIICkgQAA\'}\nclass Tests(unittest.TestCase):\n    def setUp(self):self.tmp=tempfile.TemporaryDirectory();self.root=Path(self.tmp.name)\n    def tearDown(self):self.tmp.cleanup()\n    def save(self,name,data):\n        path=self.root/name;path.write_bytes(data);return path\n    def result(self,path):return p.extract_document(str(path))\n    def test_xls_real_without_installed_xlrd(self):\n        with patch.dict(\'sys.modules\',{\'xlrd\':None}):\n            r=self.result(self.save(\'real.xls\',zlib.decompress(base64.b64decode(FIXTURES[\'xls\']))))\n        self.assertIn(\'A\',r.full_text);self.assertIn(\'=== Лист:\',r.full_text);self.assertGreater(len(r.full_text),1000)\n    def test_xlsx_all_sheets_and_coordinates(self):\n        w=Workbook();w.active.title=\'Размеры\';w.active[\'B3\']=\'Алюминий\';w.create_sheet(\'Объём\')[\'C4\']=600\n        path=self.root/\'sheet.xlsx\';w.save(path);r=self.result(path)\n        self.assertEqual(r.pages_count,2);self.assertIn(\'B3=Алюминий\',r.full_text);self.assertIn(\'C4=600\',r.full_text)\n    def test_formula_without_cached_result_requires_review(self):\n        w=Workbook();w.active[\'A1\']=\'=500+100\';w.active[\'B1\']=\'алюминий\';path=self.root/\'f.xlsx\';w.save(path)\n        self.assertEqual(self.result(path).status,p.OCRStatus.LOW_CONFIDENCE)\n    def test_docx_text_and_table(self):\n        d=Document();d.add_paragraph(\'Поставка алюминия\');d.add_table(rows=1,cols=1).cell(0,0).text=\'600 кг\';path=self.root/\'a.docx\';d.save(path)\n        r=self.result(path);self.assertIn(\'600 кг\',r.full_text);self.assertEqual(r.status,p.OCRStatus.NOT_REQUIRED)\n    def test_doc_real_conversion(self):\n        executable=shutil.which(\'libreoffice\') or shutil.which(\'soffice\')\n        if not executable:\n            if REQUIRE_OFFICE: self.fail(\'LibreOffice required for DOC support\')\n            self.skipTest(\'local environment lacks LibreOffice; mandatory in server build test\')\n        from app.ocr.legacy_word import run_office\n        d=Document();d.add_paragraph(\'Aluminium supply 600 kg\');source=self.root/\'original.docx\';d.save(source)\n        output=self.root/\'converted\';run_office(source,output,self.root/\'profile\',\'doc:MS Word 97\')\n        r=self.result(output/\'original.doc\');self.assertIn(\'Aluminium supply\',r.full_text)\n    def test_docx_embedded_image_not_silently_complete(self):\n        im=self.save(\'image.png\',self.image_bytes(\'PNG\'));d=Document();d.add_paragraph(\'Contract\');d.add_picture(str(im));path=self.root/\'a.docx\';d.save(path)\n        self.assertEqual(self.result(path).status,p.OCRStatus.LOW_CONFIDENCE)\n    def test_text_pdf(self):\n        path=self.root/\'p.pdf\'\n        with fitz.open() as d:\n            page=d.new_page();page.insert_text((50,50),\'Aluminium sheet quantity 600 kilograms\');d.save(path)\n        with patch.object(p,\'_ocr_pdf_page\',side_effect=AssertionError(\'unexpected OCR\')):r=self.result(path)\n        self.assertIn(\'600\',r.full_text);self.assertEqual(r.status,p.OCRStatus.NOT_REQUIRED)\n    def test_scanned_pdf_keeps_quality_gate(self):\n        path=self.root/\'scan.pdf\'\n        with fitz.open() as d:d.new_page();d.save(path)\n        with patch.object(p,\'_ocr_pdf_page\',return_value=p.PageExtraction(1,\'uncertain\',20,True)):\n            self.assertEqual(self.result(path).status,p.OCRStatus.LOW_CONFIDENCE)\n        with patch.object(p,\'_ocr_pdf_page\',side_effect=AssertionError(\'OCR forbidden\')):\n            self.assertEqual(f.read_document(path,allow_ocr=False).status,p.OCRStatus.LOW_CONFIDENCE)\n    def image_bytes(self,fmt):\n        b=io.BytesIO();Image.new(\'RGB\',(40,40),\'white\').save(b,format=fmt);return b.getvalue()\n    def test_image_formats_dispatch(self):\n        for ext,fmt in [(\'png\',\'PNG\'),(\'jpg\',\'JPEG\'),(\'jpeg\',\'JPEG\'),(\'bmp\',\'BMP\'),(\'webp\',\'WEBP\')]:\n            with self.subTest(ext=ext),patch.object(p,\'_ocr_image\',return_value=p.PageExtraction(1,\'600 kg\',95,True)) as mocked:\n                r=self.result(self.save(\'x.\'+ext,self.image_bytes(fmt)));self.assertEqual(r.status,p.OCRStatus.DONE);mocked.assert_called_once()\n    def test_both_tiff_pages_order_and_confidence(self):\n        path=self.root/\'pages.tif\';im=Image.new(\'RGB\',(40,40),\'white\');im.save(path,save_all=True,append_images=[im])\n        with patch.object(p,\'_ocr_image\',side_effect=lambda im,n:p.PageExtraction(n,\'page \'+str(n),95 if n==1 else 20,True)):\n            r=self.result(path)\n        self.assertEqual([x.page_number for x in r.pages],[1,2]);self.assertEqual(r.status,p.OCRStatus.LOW_CONFIDENCE)\n    def test_plain_encodings(self):\n        for encoding in (\'utf-8-sig\',\'utf-16\',\'cp1251\'):\n            self.assertIn(\'Алюминий\',self.result(self.save(\'p.txt\',\'Алюминий 600 кг\'.encode(encoding))).full_text)\n    def test_csv_tsv_md(self):\n        for ext,text in [(\'csv\',\'name;quantity\\n"Алюминий; лист";600\'),(\'tsv\',\'name\\tquantity\\nАлюминий\\t600\'),(\'md\',\'# Алюминий 600 кг\')]:\n            self.assertIn(\'600\',self.result(self.save(\'p.\'+ext,text.encode())).full_text)\n    def test_empty_text_not_approved(self):\n        self.assertEqual(self.result(self.save(\'blank.txt\',b\'  \\n\')).status,p.OCRStatus.LOW_CONFIDENCE)\n    def test_binary_text_rejected(self):\n        with self.assertRaises(ValueError):self.result(self.save(\'binary.txt\',b\'a\\0b\'))\n    def test_zip_all_members(self):\n        path=self.root/\'bundle.zip\'\n        with zipfile.ZipFile(path,\'w\') as z:z.writestr(\'one.txt\',\'Aluminium 600 kg\');z.writestr(\'two.csv\',\'quantity;unit\\n600;kg\')\n        r=self.result(path);self.assertIn(\'one.txt\',r.full_text);self.assertIn(\'two.csv\',r.full_text);self.assertEqual(r.pages_count,2)\n    def test_rar_7z_real_members(self):\n        for ext in (\'rar\',\'7z\'):\n            r=self.result(self.save(\'bundle.\'+ext,base64.b64decode(FIXTURES[ext])));self.assertIn(\'600 кг\',r.full_text);self.assertEqual(r.status,p.OCRStatus.NOT_REQUIRED)\n    def test_archive_unknown_member_no_partial_result(self):\n        path=self.root/\'bad.zip\'\n        with zipfile.ZipFile(path,\'w\') as z:z.writestr(\'a.txt\',\'600 kg\');z.writestr(\'unknown.dwg\',b\'unsupported\')\n        with self.assertRaises(ValueError):self.result(path)\n    def test_archive_traversal_rejected(self):\n        path=self.root/\'bad.zip\'\n        with zipfile.ZipFile(path,\'w\') as z:z.writestr(\'../outside.txt\',\'600 kg\')\n        with self.assertRaises(ValueError):self.result(path)\n        self.assertFalse((self.root.parent/\'outside.txt\').exists())\n    def test_archive_empty_member_is_not_complete(self):\n        path=self.root/\'bad.zip\'\n        with zipfile.ZipFile(path,\'w\') as z:z.writestr(\'a.txt\',\'600 kg\');z.writestr(\'empty.txt\',\'  \')\n        self.assertEqual(self.result(path).status,p.OCRStatus.LOW_CONFIDENCE)\n    def test_mismatch_and_unsupported(self):\n        for name,body in [(\'p.pdf\',b\'<html>login</html>\'),(\'p.xls\',b\'not xls\'),(\'p.dwg\',b\'not supported\')]:\n            with self.subTest(name=name),self.assertRaises(ValueError):self.result(self.save(name,body))\n    def test_limits_no_partial_success(self):\n        path=self.save(\'p.txt\',b\'long text\')\n        with patch.object(f,\'MAX_BYTES\',4),self.assertRaises(ValueError):self.result(path)\n        with patch.object(f,\'MAX_TEXT\',4),self.assertRaises(ValueError):self.result(path)\n    def test_read_check_never_runs_image_ocr(self):\n        path=self.save(\'p.png\',self.image_bytes(\'PNG\'))\n        with patch.object(p,\'_ocr_image\',side_effect=AssertionError(\'OCR forbidden\')),self.assertRaises(ValueError):f.read_document(path,allow_ocr=False)\n\nsuite=unittest.defaultTestLoader.loadTestsFromTestCase(Tests)\nr=unittest.TextTestRunner(verbosity=2).run(suite)\nif not r.wasSuccessful():raise SystemExit(\'DOCUMENT_FORMAT_TESTS_FAILED\')\nprint(\'DOCUMENT_FORMAT_TESTS_OK: real PDF/DOCX/XLS/XLSX/TXT/CSV/ZIP/RAR/7z; image OCR mocked; no business tasks, DB or LLM. Skipped: \'+str(len(r.skipped)),flush=True)\n'
DOCUMENT_VERIFY = "import inspect,json,shutil,subprocess\nfrom app.ocr.pipeline import extract_document\nfrom app.ocr.document_formats import VERSION,DOCUMENTS,ARCHIVES\nfrom app.ocr.xls_reader import xls_reader\nfrom app.sources.gpb.archives import library\nfrom app.sources.metal_it.documents import EXTENSIONS\nassert 'read_document' in inspect.getsource(extract_document),'shared dispatch not active'\nassert DOCUMENTS <= EXTENSIONS,'loader extensions lag behind extraction'\nassert xls_reader().open_workbook\nlibrary()\nassert shutil.which('libreoffice') or shutil.which('soffice'),'DOC converter missing'\nrun=subprocess.run(['tesseract','--list-langs'],capture_output=True,text=True,timeout=15,check=True)\nlanguages=set((run.stdout+'\\n'+run.stderr).split())\nassert {'rus','eng'}<=languages,'OCR languages missing'\nprint('DOCUMENT_FORMATS_RUNTIME_OK:',json.dumps({'version':VERSION,'documents':sorted(DOCUMENTS),'archives':sorted(ARCHIVES),'ocr_quality_gate':'retained','embedded_media':'requires_review','temporary_files':'removed'},ensure_ascii=False),flush=True)\n"

DOCUMENT_PREVIOUS_XLS_ENTRY = 'def extract_document(file_path: str) -> ExtractionResult:\n    """\n    Универсальная точка входа — определяет тип файла по расширению\n    и вызывает соответствующий обработчик.\n    """\n    if Path(file_path).suffix.lower() in {\'.txt\', \'.md\'}:\n        return _extract_plain_text_v20261019(file_path)\n    suffix = Path(file_path).suffix.lower()\n\n    handlers = {\n        ".pdf": extract_pdf,\n        ".docx": extract_docx,\n        ".doc": extract_doc,\n        ".xls": extract_xls,\n        ".xlsx": extract_xlsx,\n        ".jpg": extract_image,\n        ".jpeg": extract_image,\n        ".png": extract_image,\n        ".tiff": extract_image,\n        ".tif": extract_image,\n    }\n\n    handler = handlers.get(suffix)\n    if not handler:\n        raise ValueError(f"Неподдерживаемый тип файла: {suffix}")\n\n    logger.info("extracting_document", path=file_path, type=suffix)\n    return handler(file_path)'

def document_format_changes(root, earlier=()):
    """Merge narrowly scoped changes with a pending installation, preserving originals."""
    entries={rel:(content,old) for rel,content,old in earlier}
    def current(rel):
        path=root/rel
        if path.is_symlink():raise SystemExit('DOCUMENT_FORMAT_SYMLINK: '+rel)
        return entries[rel][0].encode('utf8') if rel in entries else (path.read_bytes() if path.is_file() else None)
    def put(rel,content):
        raw=current(rel)
        if raw==content.encode('utf8'):return
        original=entries[rel][1] if rel in entries else raw
        compile(content,rel,'exec');entries[rel]=(content,original)
    for rel,content in DOCUMENT_MODULES.items():
        raw=current(rel)
        if raw is not None and raw!=content.encode('utf8'):
            raise SystemExit('DOCUMENT_MODULE_VERSION_MISMATCH: '+rel+'; no files changed')
        put(rel,content)
    rel='app/ocr/pipeline.py';raw=current(rel)
    if raw is None:raise SystemExit('DOCUMENT_PIPELINE_MISSING: no files changed')
    source=raw.decode('utf8');tree=ast.parse(source)
    nodes=[n for n in tree.body if isinstance(n,ast.FunctionDef) and n.name=='extract_document']
    if len(nodes)!=1:raise SystemExit('DOCUMENT_DISPATCH_MISSING: no files changed')
    node=nodes[0]
    actual=ast.dump(node,include_attributes=False)
    wanted=ast.parse(DOCUMENT_ENTRY).body[0]
    accepted_dispatches={ast.dump(ast.parse(text).body[0],include_attributes=False)
                         for text in (DOCUMENT_OLD_ENTRY,DOCUMENT_PREVIOUS_XLS_ENTRY)}
    if actual!=ast.dump(wanted,include_attributes=False):
        if actual not in accepted_dispatches:raise SystemExit('DOCUMENT_DISPATCH_VERSION_MISMATCH: no files changed')
        lines=source.splitlines(keepends=True)
        source=''.join(lines[:node.lineno-1])+DOCUMENT_ENTRY+'\n'+''.join(lines[node.end_lineno:])
    put(rel,source)
    rel='app/sources/metal_it/documents.py';raw=current(rel)
    if raw is None:raise SystemExit('DOCUMENT_VALIDATOR_MISSING: no files changed')
    source=raw.decode('utf8');tree=ast.parse(source)
    changes=[]
    for name,original,desired in DOCUMENT_LOADER_PATCHES:
        if name=='EXTENSIONS':nodes=[n for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(x,ast.Name) and x.id==name for x in n.targets)]
        else:nodes=[n for n in tree.body if isinstance(n,ast.FunctionDef) and n.name==name]
        if len(nodes)!=1:raise SystemExit('DOCUMENT_LOADER_NODE_MISSING: '+name)
        node=nodes[0];actual=ast.dump(node,include_attributes=False)
        if actual==ast.dump(ast.parse(desired).body[0],include_attributes=False):continue
        if actual!=ast.dump(ast.parse(original).body[0],include_attributes=False):raise SystemExit('DOCUMENT_LOADER_VERSION_MISMATCH: '+name+'; no files changed')
        changes.append((node.lineno,node.end_lineno,desired+'\n'))
    lines=source.splitlines(keepends=True)
    for begin,end,replacement in sorted(changes,reverse=True):lines[begin-1:end]=[replacement]
    put(rel,''.join(lines))
    return [(rel,content,old) for rel,(content,old) in entries.items()]


def install_document_formats(root):
    running=set(run(['docker','compose','ps','--services','--status','running'],capture_output=True,text=True,timeout=20).stdout.split())
    if 'app' not in running:raise SystemExit('APP_NOT_RUNNING: no files changed or services started')
    pending=document_format_changes(root)
    backup=root/'backups'/('document-formats-'+datetime.now(timezone.utc).strftime('%Y%m%d-%H%M%S-%f'))
    try:
        for rel,content,old in pending:
            if old is not None:atomic(backup/rel,old)
        if pending:
            atomic(backup/'manifest.json',json.dumps({'files':[{'path':rel,'new_file':old is None} for rel,_,old in pending]},indent=2).encode())
            for rel,content,old in pending:atomic(root/rel,content.encode('utf8'))
            print('BACKUP:',backup,flush=True)
        run(['docker','compose','build','app','celery_worker','celery_discovery','celery_beat'])
        run(['docker','compose','run','--rm','--no-deps','-T','app','python','-'],input=DOCUMENT_TESTS+'\n'+DOCUMENT_VERIFY,text=True,timeout=240)
    except BaseException:
        for rel,_,old in pending:
            if old is None:(root/rel).unlink(missing_ok=True)
            else:atomic(root/rel,old)
        print('DOCUMENT_BUILD_OR_TEST_FAILED: sources restored; running services not restarted',flush=True)
        raise
    services=[s for s in ('celery_beat','celery_discovery','celery_worker') if s in running]
    ids=[]
    for service in services:ids.extend(run(['docker','compose','ps','-q',service],capture_output=True,text=True,timeout=20).stdout.split())
    if services:
        print('Waiting for existing tasks to finish; no forced stop or queue purge.',flush=True)
        run(['docker','compose','kill','--signal','SIGTERM',*services],timeout=30)
        until=time.monotonic()+300
        while ids:
            states=run(['docker','inspect','--format','{{.State.Running}}',*ids],capture_output=True,text=True,timeout=20).stdout.split()
            if len(states)==len(ids) and all(v=='false' for v in states):break
            if time.monotonic()>until:raise SystemExit('WARM_SHUTDOWN_PENDING: no forced stop; rerun this same command when tasks finish')
            time.sleep(3)
    restore=[s for s in ('app','celery_worker','celery_discovery') if s in running]
    run(['docker','compose','up','-d','--no-deps',*restore])
    run(['docker','compose','exec','-T','app','python','-'],input=DOCUMENT_VERIFY,text=True,timeout=45)
    if 'celery_beat' in running:run(['docker','compose','up','-d','--no-deps','celery_beat'])
    print('DOCUMENT_FORMATS_INSTALLED: shared readers and archive members; existing OCR quality gates; no collection, requeue, DB edits or notifications. Previously stopped services remain stopped.',flush=True)


LUKOIL_MODULE = '"""Bounded public corporate-source check, terminal only; no business writes."""\nimport hashlib\nimport io\nimport json\nimport re\nimport signal\nimport time\nfrom collections import Counter\nfrom datetime import datetime, timezone\nfrom urllib.parse import urlsplit, urljoin, urlencode, quote, parse_qsl\n\nLUKOIL=\'https://lukoil.ru\'\nLISTING=LUKOIL+\'/Company/Tendersandauctions/Tenders\'\nNORN=\'https://nornickel.ru\'\nNORN_PAGES=[NORN+\'/suppliers/tenders/central/\',NORN+\'/suppliers/tenders/local/\']\nVERSION=\'corporate-public-check-20261029-1\'\nNORN_QUERIES=(\'алюм\',\'металлопродукц\',\'металлопрокат\',\'цветной металл\')\n\nclass Stop(ValueError):pass\n\nclass Reader:\n    def __init__(self,fetch=None):\n        self.fetch=fetch;self.requests=[];self.allowed={LISTING,*NORN_PAGES}\n        self.failed_hosts=set();self.started=time.monotonic();self.clients={};self.search_params=None;self.max_requests=24;self.read_retries=0\n    def close(self):\n        for client in self.clients.values():client.cookies.clear();client.close()\n        self.clients.clear()\n    def get(self,url,data=None,limit=4_000_000):\n        # Exactly one additional attempt, only a read timeout on the public\n        # LUKOIL listing. No retry for POST, TLS, access refusal or documents.\n        import httpx\n        try:return self._get_once(url,data=data,limit=limit)\n        except httpx.ReadTimeout:\n            if url!=LISTING or data is not None or self.read_retries>=1:raise\n            self.read_retries+=1\n            self.failed_hosts.discard(\'lukoil.ru\')\n            client=self.clients.pop(\'lukoil.ru\',None)\n            if client is not None:client.close()\n            return self._get_once(url,data=data,limit=limit)\n    def _get_once(self,url,data=None,limit=4_000_000):\n        p=urlsplit(url)\n        if p.scheme!=\'https\' or p.hostname not in (\'lukoil.ru\',\'nornickel.ru\') or p.username or p.password or p.port not in (None,443) or p.fragment:\n            raise Stop(\'unapproved_url\')\n        if p.hostname in self.failed_hosts:raise Stop(\'host_stopped_after_error\')\n        if url not in self.allowed:raise Stop(\'unobserved_url\')\n        if data is not None:\n            expected=self.search_params\n            if url!=LUKOIL+\'/api/tenders/SearchTenders\' or not expected or not isinstance(data,dict):raise Stop(\'unapproved_operation\')\n            if set(data)!=set(expected)|{\'SearchQuery\'} or any(data[k]!=v for k,v in expected.items()) or data[\'SearchQuery\'] not in (quote(\'алюм\'),quote(\'металлопродукци\')):\n                raise Stop(\'unapproved_search_payload\')\n        if len(self.requests)>=self.max_requests or time.monotonic()-self.started>160:raise Stop(\'request_budget\')\n        row={\'url\':p._replace(query=\'\').geturl(),\'method\':\'POST\' if data is not None else \'GET\',\'attempt\':1+sum(x[\'url\']==p._replace(query=\'\').geturl() and x.get(\'reason\')==\'transport_error\' for x in self.requests)};self.requests.append(row)\n        try:\n            if self.fetch:result=self.fetch(url,data=data,limit=limit)\n            else:\n                import httpx\n                if p.hostname not in self.clients:self.clients[p.hostname]=httpx.Client(verify=True,follow_redirects=False,timeout=httpx.Timeout(18,connect=5))\n                client=self.clients[p.hostname]\n                headers={\'Accept-Encoding\':\'identity\'}\n                if data is not None:headers.update({\'Referer\':LISTING,\'X-Requested-With\':\'XMLHttpRequest\'})\n                with client.stream(row[\'method\'],url,data=data,headers=headers) as r:\n                    row[\'http\']=r.status_code\n                    if r.status_code!=200:raise Stop(\'http_\'+str(r.status_code))\n                    b=bytearray();started=time.monotonic()\n                    for block in r.iter_bytes():\n                        b.extend(block)\n                        if len(b)>limit:raise Stop(\'body_limit\')\n                        if time.monotonic()-started>25 or time.monotonic()-self.started>180:raise Stop(\'time_limit\')\n                    result={\'body\':bytes(b),\'http\':r.status_code,\'content_type\':r.headers.get(\'content-type\',\'\')}\n            row[\'http\']=result[\'http\']\n            if result[\'http\']!=200:raise Stop(\'http_\'+str(result[\'http\']))\n            if not result[\'body\'] or len(result[\'body\'])>limit:raise Stop(\'empty_or_large_body\')\n            row.update(bytes=len(result[\'body\']),sha256=hashlib.sha256(result[\'body\']).hexdigest())\n            return result\n        except Exception as e:\n            self.failed_hosts.add(p.hostname);row.update(error_type=type(e).__name__,reason=str(e) if isinstance(e,Stop) else \'transport_error\');raise\n\ndef page(body):\n    from bs4 import BeautifulSoup\n    s=BeautifulSoup(body,\'html.parser\')\n    text=\' \'.join(s.stripped_strings)\n    title=s.title.get_text(\' \',strip=True) if s.title else \'\'\n    if re.search(r\'captcha|anti.bot|verify you are human|access denied|проверка.{0,20}робот\',title+\' \'+text[:5000],re.I):raise Stop(\'access_challenge\')\n    if s.select(\'input[type=password]\'):raise Stop(\'login_required\')\n    return s\n\ndef initial_lukoil(body):\n    s=page(body)\n    scripts=\'\\n\'.join(t.get_text() for t in s.select(\'script:not([src])\'))\n    m=re.search(r\'\\bvar Tenders\\s*=\\s*\',scripts)\n    if not m:raise Stop(\'lukoil_native_listing_missing\')\n    data=json.JSONDecoder().raw_decode(scripts[m.end():])[0]\n    config=re.search(r\'searchDataUrl:\\s*"(/api/tenders/SearchTenders)"\',scripts)\n    constructor=re.search(r\'new TenderListViewModel\\(container,\\s*Tenders,\\s*(\\d+),\\s*(\\d+),\\s*(\\d+),\\s*(\\d+),\',scripts)\n    if not config or not constructor or \'method: "post"\' not in scripts or \'SearchQuery\' not in scripts:raise Stop(\'lukoil_search_contract_changed\')\n    # First-page Take=10 is the native listing size observed on this page.\n    if not isinstance(data,dict) or not isinstance(data.get(\'Items\'),dict):raise Stop(\'lukoil_listing_shape\')\n    params=dict(zip((\'Organization\',\'customer\',\'Country\',\'Region\'),constructor.groups()))\n    params.update(Take=\'10\',Tab=\'1\')\n    return data,params\n\ndef listing_rows(data):\n    if not isinstance(data,dict) or not isinstance(data.get(\'Items\'),dict) or not isinstance(data.get(\'Count\'),dict):raise Stop(\'lukoil_search_shape\')\n    rows=data[\'Items\'].get(\'AllItems\');count=data[\'Count\'].get(\'AllTotalCount\')\n    if not isinstance(rows,list) or type(count) is not int or count<0 or len(rows)>10 or count<len(rows):raise Stop(\'lukoil_search_shape\')\n    seen=set()\n    for r in rows:\n        if not isinstance(r,dict) or type(r.get(\'TenderId\')) is not int or r[\'TenderId\']<=0 or not r.get(\'Number\') or not r.get(\'Topic\'):raise Stop(\'lukoil_identity_missing\')\n        if r[\'TenderId\'] in seen:raise Stop(\'lukoil_duplicate_identity\')\n        seen.add(r[\'TenderId\'])\n    return rows,count\n\ndef summary(r):\n    from app.scoring.selection_policy import material_status\n    material=material_status({\'name\':r[\'Topic\']})\n    # Explicitly reject aluminium salts/chemicals even with very large weights.\n    if re.search(r\'сульфат|оксид|гидроксид|коагулянт|полиоксихлорид|реагент\',r[\'Topic\'],re.I):material=False\n    open_flags=all(r.get(k) is False for k in (\'IsCanceled\',\'IsFinished\',\'NeedToHide\',\'IsDisabled\'))\n    return {\'external_id\':str(r[\'TenderId\']),\'number\':r[\'Number\'],\'title\':r[\'Topic\'],\n            \'deadline_raw\':r.get(\'DateFinish\'),\'deadline_timezone_verified\':False,\n            \'native_open_flags\':open_flags,\'aluminium_material_confirmed\':material,\n            \'eligibility\':\'not_verified\',\'documents_count\':len(r.get(\'Files\') or [])}\n\ndef documents(r):\n    docs=r.get(\'Files\')\n    if not isinstance(docs,list):raise Stop(\'lukoil_documents_shape\')\n    out=[];seen=set()\n    for d in docs:\n        if not isinstance(d,dict) or d.get(\'TenderId\')!=r[\'TenderId\'] or type(d.get(\'FileId\')) is not int or d[\'FileId\']<=0 or d.get(\'AllowDownload\') is not True:raise Stop(\'lukoil_document_identity_or_access\')\n        if d[\'FileId\'] in seen:raise Stop(\'lukoil_duplicate_document_id\')\n        seen.add(d[\'FileId\']);u=d.get(\'FileDownloadUrl\') or \'\';p=urlsplit(u)\n        m=re.fullmatch(r\'/FileSystem/(\\d+)/(\\d+)\\.([A-Za-z0-9]+)\',p.path)\n        if p.scheme!=\'https\' or p.netloc!=\'lukoil.ru\' or not m or int(m[2])!=d[\'FileId\'] or int(m[1])!=d.get(\'LibraryType\') or p.fragment or parse_qsl(p.query)!=[(\'dl\',\'1\')]:raise Stop(\'lukoil_document_url\')\n        if m[3].lower() not in (\'pdf\',\'xls\',\'xlsx\',\'doc\',\'docx\',\'zip\',\'rar\',\'7z\'):raise Stop(\'lukoil_document_format\')\n        out.append({\'id\':str(d[\'FileId\']),\'name\':d.get(\'Title\') or d.get(\'FileName\'),\'extension\':\'.\'+m[3].lower(),\'url\':u})\n    return out\n\n\n# xlrd 2.0.1, BSD licence retained inside the compressed source bundle.\n# Isolated in-memory package; no pip, files or changes to application imports.\n\n\ndef inspect_document(data,ext):\n    import tempfile\n    from pathlib import Path\n    from app.ocr.document_formats import read_document,validate_document_bytes\n    validate_document_bytes(data,ext)\n    with tempfile.TemporaryDirectory(prefix=\'corporate-document-check-\') as folder:\n        path=Path(folder)/(\'document\'+ext);path.write_bytes(data)\n        extracted=read_document(path,allow_ocr=False)\n    text=extracted.full_text\n    return {\'bytes\':len(data),\'sha256\':hashlib.sha256(data).hexdigest(),\'signature_verified\':True,\n            \'extraction\':\'shared_document_reader_no_ocr\',\'quality_status\':extracted.status.value,\n            \'text_characters\':len(text),\'pages\':extracted.pages_count,\n            \'aluminium_mentions\':[line[:500] for line in text.splitlines() if re.search(r\'алюмин|(?<!\\w)АМ[гГЦц]\\d|АД31\',line)][:12],\n            \'mentions_are_not_position_approval\':True,\'temporary_files_removed\':True,\n            \'full_documentation_requires_request\':bool(re.search(r\'полный\\s+комплект.{0,100}документации.{0,120}(?:после|по\\s+запросу)\', \' \'.join(text.split()), re.I)),\n            \'access_note\':\'public_attachments_do_not_prove_full_tender_documentation\'}\n\ndef check_lukoil(reader):\n    result={\'source\':\'lukoil\',\'pipeline_ready\':False,\'queued_count\':0,\'status\':\'not_checked\',\'searches\':[],\'errors\':[]}\n    try:\n        initial,params=initial_lukoil(reader.get(LISTING)[\'body\']);rows,total=listing_rows(initial)\n        result[\'listing\']={\'count_on_page\':len(rows),\'total\':total,\'coverage\':\'first_page\'}\n        reader.search_params=params;reader.allowed.add(LUKOIL+\'/api/tenders/SearchTenders\')\n        candidates={}\n        for q in (\'алюм\',\'металлопродукци\'):\n            data=json.loads(reader.get(LUKOIL+\'/api/tenders/SearchTenders\',data={**params,\'SearchQuery\':quote(q)})[\'body\'])\n            found,count=listing_rows(data)\n            result[\'searches\'].append({\'query\':q,\'total\':count,\'complete\':len(found)==count,\'items\':[summary(r) for r in found]})\n            for r in found:\n                info=summary(r)\n                if info[\'native_open_flags\'] and info[\'aluminium_material_confirmed\'] is not False:candidates[r[\'TenderId\']]=r\n        # Check one material candidate, all listed files within the request budget.\n        # No result is labelled suitable before per-position eligibility and LLM.\n        selected=next(iter(candidates.values()),None)\n        if selected:\n            docs=documents(selected);result[\'sample_card\']=summary(selected);result[\'documents\']=docs;result[\'document_checks\']=[]\n            for d in docs:\n                try:\n                    reader.allowed.add(d[\'url\'])\n                    body=reader.get(d[\'url\'],limit=15_000_000)[\'body\']\n                    result[\'document_checks\'].append({\'id\':d[\'id\'],\'name\':d[\'name\'],**inspect_document(body,d[\'extension\'])})\n                except Exception as exc:\n                    result[\'errors\'].append({\'document_id\':d[\'id\'],\'type\':type(exc).__name__,\'reason\':str(exc) if isinstance(exc,(Stop,ValueError)) else \'document_read_failed\'})\n            result[\'all_documents_checked\']=len(docs)==len(result[\'document_checks\'])\n            result[\'full_documentation_requires_request\']=any(d.get(\'full_documentation_requires_request\') for d in result[\'document_checks\'])\n            result[\'all_documents_quality_accepted\']=result[\'all_documents_checked\'] and all(d[\'quality_status\'] in (\'done\',\'not_required\') and d[\'text_characters\']>0 for d in result[\'document_checks\'])\n        result[\'status\']=\'incomplete\' if result[\'errors\'] else \'public_search_verified_adapter_not_installed\'\n    except Exception as e:\n        result[\'status\']=\'incomplete\';result[\'errors\'].append({\'type\':type(e).__name__,\'reason\':str(e) if isinstance(e,Stop) else \'check_failed\',**({\'missing_module\':e.name} if isinstance(e,ModuleNotFoundError) else {})})\n    return result\n\ndef norn_evidence(body,url):\n    # Inspect before pruning navigation: earlier pruning could discard content.\n    s=page(body)\n    def clean_url(raw):\n        p=urlsplit(urljoin(url,raw))\n        if p.scheme!=\'https\' or p.username or p.password or p.hostname!=\'nornickel.ru\':return None\n        if any(re.search(r\'token|session|auth|password|secret|signature|key\',k,re.I) for k,v in parse_qsl(p.query)):return None\n        return p._replace(fragment=\'\').geturl()\n    markers=re.compile(r\'tender|закуп|тендер|procure|purchase|ajax|__NEXT_DATA__|__NUXT__\',re.I)\n    scripts=[]\n    for node in s.select(\'script\'):\n        raw=node.string or node.get_text();src=clean_url(node.get(\'src\',\'\')) if node.get(\'src\') else None\n        entry={\'id\':node.get(\'id\'),\'type\':node.get(\'type\'),\'src\':src,\'characters\':len(raw)}\n        # Do not execute or import site scripts, and do not print cookies/tokens.\n        hits=list(markers.finditer(raw))[:3]\n        excerpts=[]\n        for hit in hits:\n            fragment=raw[max(0,hit.start()-150):hit.end()+650]\n            if not re.search(r\'cookie|password|authorization|access.?token|secret\',fragment,re.I):excerpts.append(fragment)\n        if excerpts:entry[\'public_contract_excerpts\']=excerpts\n        if src or excerpts or node.get(\'type\')==\'application/json\':scripts.append(entry)\n    links=[]\n    for a in s.select(\'a[href]\'):\n        u=clean_url(a[\'href\'])\n        if u and (re.search(r\'\\.(?:zip|rar|7z|docx?|xlsx?|pdf)$\',urlsplit(u).path,re.I) or \'/suppliers/tenders/\' in u):\n            links.append({\'text\':a.get_text(\' \',strip=True)[:180],\'url\':u})\n    roots=[{\'tag\':t.name,\'id\':t.get(\'id\'),\'class\':t.get(\'class\'),\'attributes\':{k:str(v)[:500] for k,v in t.attrs.items() if k.startswith(\'data-\') and not re.search(\'token|auth|secret|key\',k,re.I)}} for t in s.find_all([\'main\',\'div\',\'section\']) if markers.search(str(t.get(\'id\',\'\'))+\' \'+str(t.get(\'class\',\'\')))][:20]\n    title=s.title.get_text(\' \',strip=True) if s.title else \'\'\n    forms=[{\'action\':clean_url(f.get(\'action\',\'\')),\'method\':f.get(\'method\',\'get\'),\'fields\':[{\'name\':i.get(\'name\'),\'type\':i.get(\'type\',\'text\')} for i in f.select(\'input[name]\')[:20]]} for f in s.select(\'form\')[:5]]\n    for tag in s([\'script\',\'style\']):tag.decompose()\n    main=s.find(\'main\') or s\n    text=main.get_text(\' \',strip=True)\n    return {\'url\':url,\'title\':title,\'text_characters\':len(text),\'public_text_excerpt\':text[:14000],\'links\':links[:40],\'forms\':forms,\'script_evidence\':scripts[:30],\'tender_containers\':roots,\'tables\':len(s.select(\'table\')),\'links_found\':len(links),\'scripts_found\':len(scripts),\'coverage\':\'page_structure_only_not_full_procurement_listing\'}\n\ndef norn_app(body):\n    s=page(body)\n    values=[]\n    for tag in s.select(\'script:not([src])\'):\n        raw=tag.string or tag.get_text()\n        match=re.search(r\'(?:^|;)\\s*(?:var\\s+)?(?:window\\.)?App\\s*=\\s*\',raw)\n        if match:\n            try:value,end=json.JSONDecoder().raw_decode(raw[match.end():])\n            except (ValueError,RecursionError):raise Stop(\'norn_app_not_literal_json\')\n            if not isinstance(value,dict) or not isinstance(value.get(\'components\'),dict):raise Stop(\'norn_app_components_missing\')\n            values.append(value[\'components\'])\n    if len(values)!=1:raise Stop(\'norn_app_assignment_missing_or_ambiguous\')\n    # Do not expose or use App.system, cookie/session data or contact fields.\n    return values[0]\n\n\ndef norn_text(raw):\n    from html import unescape\n    from bs4 import BeautifulSoup\n    if not isinstance(raw,str):return \'\'\n    # Plain titles/filenames are not markup; avoid BeautifulSoup\'s locator warning.\n    return BeautifulSoup(raw,\'html.parser\').get_text(\' \',strip=True) if re.search(r\'</?[A-Za-z][^>]*>\',raw) else unescape(raw).strip()\n\n\ndef norn_document(raw):\n    if not isinstance(raw,dict):return None,\'documentation_missing\'\n    href=raw.get(\'link\')\n    if not isinstance(href,str) or not href.strip():return None,\'document_link_missing\'\n    try:\n        u=urlsplit(urljoin(NORN,href.strip()))\n        if u.scheme!=\'https\' or u.hostname!=\'nornickel.ru\' or u.username or u.password or u.port not in (None,443):return None,\'external_or_unapproved_document_link\'\n        if any(re.search(r\'token|auth|session|secret|key|password|signature\',k,re.I) for k,v in parse_qsl(u.query)):return None,\'restricted_document_link\'\n        if not u.path or u.path==\'/\':return None,\'document_link_missing\'\n        return u._replace(fragment=\'\').geturl(),\'public_link_not_downloaded\'\n    except ValueError:return None,\'invalid_document_link\'\n\n\ndef norn_component(data,section):\n    from app.scoring.selection_policy import material_status\n    if not isinstance(data,dict) or not isinstance(data.get(\'items\'),list):raise Stop(\'norn_tender_items_shape\')\n    items=data[\'items\']\n    if len(items)>100:raise Stop(\'norn_tender_items_limit\')\n    out=[]\n    for item in items:\n        if not isinstance(item,dict) or not isinstance(item.get(\'name\'),str):raise Stop(\'norn_tender_item_shape\')\n        title=norn_text(item[\'name\'])\n        doc=item.get(\'documentation\');document,doc_reason=norn_document(doc)\n        # A printed reference is not a platform ID. Never fabricate one from a hash.\n        match=re.match(r\'^(?:№\\s*)?(\\d{5,}(?:/\\d+)?)\\s*(?::|[«\\s])\',title)\n        raw_date=item.get(\'activeTo\');date_utc=None\n        if type(raw_date) in (int,float) and 946684800<=raw_date<=4102444800:\n            date_utc=datetime.fromtimestamp(raw_date,timezone.utc).isoformat()\n        material=material_status({\'name\':title})\n        if re.search(r\'сульфат|оксид|гидроксид|коагулянт|полиоксихлорид|реагент\',title,re.I):material=False\n        out.append({\'source\':\'nornickel\',\'section\':section,\'native_id\':item.get(\'id\') if type(item.get(\'id\')) in (str,int) else None,\n                    \'reference_from_title\':match.group(1) if match else None,\'identity_basis\':\'unverified_public_listing\',\n                    \'title\':title[:1500],\'deadline_raw\':raw_date if type(raw_date) in (str,int,float) else None,\n                    \'deadline_timestamp_utc\':date_utc,\'deadline_precision\':\'site_displays_date_only\',\'deadline_verified\':False,\n                    \'aluminium_material_confirmed\':material,\'document_url\':document,\'document_state\':doc_reason,\n                    \'documentation_fields\':sorted(k for k in doc if k in (\'link\',\'type\',\'size\')) if isinstance(doc,dict) else [],\n                    \'identity_and_freshness_verified\':False})\n    nav=data.get(\'nav\')\n    return {\'count_on_page\':len(items),\'items\':out,\'navigation\':{k:v for k,v in (nav.items() if isinstance(nav,dict) else []) if k in (\'current\',\'total\',\'count\',\'pageSize\') and isinstance(v,(int,str))},\'coverage\':\'first_page_only\',\'documents_verified\':False}\n\n\ndef check_nornickel(reader):\n    result={\'source\':\'nornickel\',\'pipeline_ready\':False,\'queued_count\':0,\'status\':\'not_checked\',\'pages\':[],\'errors\':[]}\n    script=None;script_url=NORN+\'/local/templates/z-template/static/javascripts/app.js\'\n    try:\n        for section,url in zip((\'central\',\'local\'),NORN_PAGES):\n            body=reader.get(url)[\'body\'];components=norn_app(body)\n            key=section+\'-tenders\'\n            row={\'url\':url,\'component\':key,\'available_tender_components\':[k for k in components if k in (\'central-tenders\',\'local-tenders\')],\n                 \'initial\':norn_component(components.get(key),section)}\n            result[\'pages\'].append(row)\n            if script is None:\n                soup=page(body)\n                observed={urljoin(url,t[\'src\']) for t in soup.select(\'script[src]\')}\n                if script_url not in observed:raise Stop(\'norn_public_script_not_linked\')\n                reader.allowed.add(script_url)\n                script=reader.get(script_url,limit=6_000_000)[\'body\'].decode(\'utf-8\')\n            endpoint=\'/api/\'+key+\'/\'\n            if \'url:"\'+endpoint+\'",method:"get",params:\' not in script or \'["\'+key+\'"]\' not in script:\n                raise Stop(\'norn_public_search_contract_changed\')\n            row[\'searches\']=[]\n            for query in NORN_QUERIES:\n                u=NORN+endpoint+\'?\'+urlencode({\'q\':query,\'page\':1})\n                reader.allowed.add(u)\n                data=json.loads(reader.get(u)[\'body\'])\n                parsed=norn_component(data,section)\n                nav=parsed[\'navigation\']\n                count=nav.get(\'count\')\n                complete=type(count) is int and count==parsed[\'count_on_page\'] and nav.get(\'current\')==1\n                row[\'searches\'].append({\'query\':query,\'complete\':complete,**parsed})\n            row[\'keyword_search\']=row[\'searches\'][0]\n        result[\'status\']=\'public_items_read_adapter_not_installed\'\n    except Exception as exc:\n        result[\'status\']=\'incomplete\';result[\'errors\'].append({\'type\':type(exc).__name__,\'reason\':str(exc) if isinstance(exc,Stop) else \'public_read_failed\'})\n    return result\n\ndef collect(*,persist=True,fetch=None):\n    from app.marketplace_discovery.primary.collector import folder,save_report\n    reader=Reader(fetch)\n    try:\n        report=check_lukoil(reader)\n        report.update(checked_at=datetime.now(timezone.utc).isoformat(),name=\'ЛУКОЙЛ\',\n                      requests=len(reader.requests),request_details=reader.requests,items=[],pipeline=[],\n                      pipeline_status=\'candidates_only_no_automatic_analysis\',backlog_pending=0,\n                      collection_mode=\'public_search_and_documents_no_ocr\',coverage=\'first_page_per_keyword\')\n        report[\'read_check_status\']=report[\'status\']\n        report[\'status\']=\'partial\' if report.get(\'errors\') or any(not x.get(\'complete\') for x in report.get(\'searches\',[])) else \'ok\'\n        report[\'adapter_status\']=\'public_monitor_only\'\n        candidates=[];seen=set()\n        from app.reports.review_dismissals import is_dismissed\n        for search in report.get(\'searches\',[]):\n            for item in search.get(\'items\',[]):\n                number=item[\'external_id\']\n                if number in seen:continue\n                seen.add(number)\n                if item.get(\'native_open_flags\') is not True or item.get(\'aluminium_material_confirmed\') is False:continue\n                if is_dismissed(\'lukoil\',number):continue\n                candidates.append(dict(item,reason=\'documents_and_volume_require_confirmation\',llm_queued=False))\n        report[\'candidates\']=candidates\n        report[\'candidate_count\']=len(candidates)\n        if persist:save_report(\'lukoil\',report)\n        return report\n    finally:reader.close()\n'
LUKOIL_BRANCH = "if site == 'lukoil':\n    from app.sources.lukoil_public import collect as collect_lukoil\n    return collect_lukoil(persist=persist,fetch=fetch)"
LUKOIL_SCHEDULE = "# LUKOIL public monitoring only; no automatic analysis or document submissions.\ncelery_app.conf.beat_schedule['primary-lukoil-4h'] = {\n    'task':'app.workers.tasks_primary_discovery.collect_primary',\n    'schedule':crontab(minute=39,hour='*/4'),\n    'args':('lukoil',),\n    'options':{'expires':3600},\n}\n"
LUKOIL_TESTS = 'import json,unittest,io,tempfile\nfrom pathlib import Path\nfrom unittest.mock import patch\nfrom app.sources import lukoil_public as m\n\nclass Tests(unittest.TestCase):\n def test_literal_app_only(self):\n  b=b\'<script>App = {"components":{"central-tenders":{"items":[]}},"system":{"cookie":"private"}}; if(true){}</script>\'\n  self.assertEqual(m.norn_app(b),{\'central-tenders\':{\'items\':[]}})\n def test_no_javascript_execution(self):\n  with self.assertRaises(m.Stop):m.norn_app(b\'<script>App = getData();</script>\')\n def test_no_duplicate_app(self):\n  with self.assertRaises(m.Stop):m.norn_app(b\'<script>App={"components":{}}</script><script>App={"components":{}}</script>\')\n def test_component_sanitizes_contacts_and_unknown_identity(self):\n  data={\'items\':[{\'name\':\'<b>Алюминиевый лист</b>\',\'activeTo\':\'2026-11-15\',\'email\':{\'value\':\'private@example.invalid\'},\'documentation\':{\'link\':\'/files/public.zip\'}}],\'nav\':{\'current\':1,\'total\':3}}\n  r=m.norn_component(data,\'central\');self.assertEqual(r[\'items\'][0][\'title\'],\'Алюминиевый лист\');self.assertIsNone(r[\'items\'][0][\'native_id\']);self.assertNotIn(\'email\',json.dumps(r));self.assertFalse(r[\'items\'][0][\'identity_and_freshness_verified\'])\n def test_token_document_not_used(self):\n  r=m.norn_component({\'items\':[{\'name\':\'Лист\',\'documentation\':{\'link\':\'/f.zip?token=secret\'}}]},\'central\');self.assertIsNone(r[\'items\'][0][\'document_url\'])\n def test_native_public_search_flow(self):\n  calls=[]\n  def fetch(u,**kwargs):\n   calls.append(u)\n   if u.endswith(\'/app.js\'):return {\'http\':200,\'body\':b\'["central-tenders"] url:"/api/central-tenders/",method:"get",params:e; ["local-tenders"] url:"/api/local-tenders/",method:"get",params:e;\'}\n   if \'/api/\' in u:return {\'http\':200,\'body\':json.dumps({\'items\':[{\'id\':\'x\',\'name\':\'Алюминиевый лист\',\'activeTo\':\'2026-11-15\'}],\'nav\':{\'current\':1,\'total\':1}}).encode()}\n   sec=\'central\' if \'/central/\' in u else \'local\';app={\'components\':{sec+\'-tenders\':{\'items\':[],\'nav\':{\'current\':1,\'total\':1}}}}\n   body=\'<script>App=\'+json.dumps(app)+\'</script><script src="/local/templates/z-template/static/javascripts/app.js"></script>\'\n   return {\'http\':200,\'body\':body.encode()}\n  r=m.check_nornickel(m.Reader(fetch));self.assertEqual(r[\'errors\'],[]);self.assertEqual(len(calls),11);self.assertEqual(len(r[\'pages\']),2);self.assertFalse(r[\'pipeline_ready\']);self.assertEqual(r[\'queued_count\'],0)\n def test_contract_change_stops_api(self):\n  calls=[]\n  def fetch(u,**kwargs):\n   calls.append(u)\n   if u.endswith(\'app.js\'):return {\'http\':200,\'body\':b\'changed script\'}\n   return {\'http\':200,\'body\':b\'<script>App={"components":{"central-tenders":{"items":[]}}}</script><script src="/local/templates/z-template/static/javascripts/app.js"></script>\'}\n  r=m.check_nornickel(m.Reader(fetch));self.assertEqual(len(calls),2);self.assertEqual(r[\'status\'],\'incomplete\')\n def test_403_stops_source(self):\n  calls=[]\n  def fetch(u,**kwargs):calls.append(u);return {\'http\':403,\'body\':b\'Forbidden\'}\n  r=m.check_nornickel(m.Reader(fetch));self.assertEqual(len(calls),1);self.assertFalse(r[\'pipeline_ready\'])\n def test_monitor_no_business_handoff(self):\n  report={\'source\':\'lukoil\',\'status\':\'public_search_verified_adapter_not_installed\',\'searches\':[{\'items\':[\n   {\'external_id\':\'1\',\'title\':\'Сульфат алюминия\',\'native_open_flags\':True,\'aluminium_material_confirmed\':False},\n   {\'external_id\':\'2\',\'title\':\'Алюминиевый лист\',\'native_open_flags\':True,\'aluminium_material_confirmed\':True},\n   {\'external_id\':\'3\',\'title\':\'Алюминиевый лист\',\'native_open_flags\':True,\'aluminium_material_confirmed\':True}]}]}\n  with patch.object(m,\'check_lukoil\',return_value=report),patch(\'app.reports.review_dismissals.is_dismissed\',side_effect=lambda s,n:n==\'3\'),patch(\'app.marketplace_discovery.primary.collector.save_report\') as save:\n   out=m.collect(persist=True)\n  self.assertEqual(out[\'items\'],[]);self.assertEqual(out[\'pipeline\'],[]);self.assertEqual(out[\'candidate_count\'],1);self.assertFalse(out[\'candidates\'][0][\'llm_queued\']);save.assert_called_once()\n def test_no_import_or_call_to_business_queue(self):\n  import ast,inspect\n  tree=ast.parse(inspect.getsource(m))\n  for n in ast.walk(tree):\n   if isinstance(n,ast.ImportFrom):self.assertFalse(any(s in (n.module or \'\') for s in (\'app.workers\',\'app.db\',\'app.llm\')))\n   if isinstance(n,ast.Call) and isinstance(n.func,ast.Attribute):self.assertNotIn(n.func.attr,(\'delay\',\'apply_async\',\'send_task\',\'commit\'))\n\n def test_public_listing_timeout_retries_once(self):\n  import httpx\n  calls=[]\n  def fetch(u,**kw):\n   calls.append(u)\n   if len(calls)==1:raise httpx.ReadTimeout(\'slow\')\n   return {\'http\':200,\'body\':b\'public\'}\n  r=m.Reader(fetch);self.assertEqual(r.get(m.LISTING)[\'body\'],b\'public\');self.assertEqual(len(calls),2);self.assertEqual(r.read_retries,1)\n def test_repeated_timeout_stops(self):\n  import httpx\n  calls=[]\n  def fetch(u,**kw):calls.append(u);raise httpx.ReadTimeout(\'slow\')\n  r=m.Reader(fetch)\n  with self.assertRaises(httpx.ReadTimeout):r.get(m.LISTING)\n  self.assertEqual(len(calls),2)\n  with self.assertRaises(m.Stop):r.get(m.LISTING)\n  self.assertEqual(len(calls),2)\n def test_no_retry_for_access_refusal_or_other_host(self):\n  import httpx\n  for err in (403,429):\n   calls=[]\n   def fetch(u,**kw):calls.append(u);return {\'http\':err,\'body\':b\'not public\'}\n   with self.assertRaises(m.Stop):m.Reader(fetch).get(m.LISTING)\n   self.assertEqual(len(calls),1)\n  calls=[]\n  def fetch(u,**kw):calls.append(u);raise httpx.ReadTimeout(\'slow\')\n  with self.assertRaises(httpx.ReadTimeout):m.Reader(fetch).get(m.NORN_PAGES[0])\n  self.assertEqual(len(calls),1)\n def test_reference_not_native_id_and_date_not_approved(self):\n  data={\'items\':[{\'name\':\'20060001/2: Поставка алюминия\',\'activeTo\':1794344400,\'documentation\':{\'link\':\'\'}}]}\n  v=m.norn_component(data,\'local\')[\'items\'][0]\n  self.assertEqual(v[\'reference_from_title\'],\'20060001/2\');self.assertIsNone(v[\'native_id\'])\n  self.assertIsNotNone(v[\'deadline_timestamp_utc\']);self.assertFalse(v[\'deadline_verified\']);self.assertEqual(v[\'document_state\'],\'document_link_missing\')\n def test_plain_title_no_warning(self):\n  import warnings\n  with warnings.catch_warnings(record=True) as w:\n   warnings.simplefilter(\'always\');self.assertEqual(m.norn_text(\'Документация.xlsx\'),\'Документация.xlsx\')\n  self.assertEqual(w,[])\n def test_shape_and_link_guards(self):\n  for link in (\'https://evil.invalid/a.pdf\',\'http://nornickel.ru/a.pdf\',\'//evil.invalid/a.pdf\',\'https://nornickel.ru:bad/a.pdf\',\'/a.pdf?token=x\'):\n   self.assertIsNone(m.norn_document({\'link\':link})[0])\n  self.assertEqual(m.norn_document({\'link\':\'/upload/a.pdf\'})[0],\'https://nornickel.ru/upload/a.pdf\')\n  with self.assertRaises(m.Stop):m.norn_component({\'items\':{}},\'local\')\n def test_norn_monitor_candidates_only(self):\n  try:from app.sources import nornickel_public as n\n  except ImportError:self.skipTest(\'Nornickel monitor not installed by this mode\')\n  rows=[{\'section\':\'local\',\'native_id\':None,\'title\':\'Металлопрокат\',\'reference_from_title\':None,\'aluminium_material_confirmed\':None},\n        {\'section\':\'local\',\'native_id\':None,\'title\':\'Сульфат алюминия\',\'reference_from_title\':None,\'aluminium_material_confirmed\':False}]\n  report={\'source\':\'nornickel\',\'status\':\'public_items_read_adapter_not_installed\',\'errors\':[], \'pages\':[{\'searches\':[{\'complete\':True,\'items\':rows},{\'complete\':True,\'items\':rows}]}]}\n  with patch.object(n,\'check_nornickel\',return_value=report),patch(\'app.marketplace_discovery.primary.collector.save_report\') as save:\n   out=n.collect(persist=True)\n  self.assertEqual(out[\'candidate_count\'],1);self.assertEqual(out[\'queued_count\'],0);self.assertEqual(out[\'items\'],[]);self.assertFalse(out[\'pipeline_ready\']);save.assert_called_once()\n def test_norn_no_business_queue(self):\n  import ast,inspect\n  try:from app.sources import nornickel_public as n\n  except ImportError:self.skipTest(\'Nornickel monitor not installed by this mode\')\n  for node in ast.walk(ast.parse(inspect.getsource(n))):\n   if isinstance(node,ast.ImportFrom):self.assertFalse(any(s in (node.module or \'\') for s in (\'app.workers\',\'app.db\',\'app.llm\')))\n   if isinstance(node,ast.Call) and isinstance(node.func,ast.Attribute):self.assertNotIn(node.func.attr,(\'delay\',\'apply_async\',\'send_task\',\'commit\'))\n\nr=unittest.TextTestRunner(verbosity=2).run(unittest.defaultTestLoader.loadTestsFromTestCase(Tests))\nif not r.wasSuccessful():raise SystemExit(\'CORPORATE_MONITOR_TESTS_FAILED\')\nprint(\'CORPORATE_MONITOR_TESTS_OK: native public search contract, App JSON, stop on access failure, no business handoff; mocked network/queue boundaries\',flush=True)\n'
LUKOIL_VERIFY = "from app.sources import lukoil_public\nfrom app.workers.celery_app import celery_app\nfrom app.marketplace_discovery.primary.collector import collect\nimport inspect\nfrom app.ocr.document_formats import VERSION\nassert 'lukoil_public' in inspect.getsource(collect),'collector route missing'\nentry=celery_app.conf.beat_schedule.get('primary-lukoil-4h')\nassert entry and entry['args']==('lukoil',) and entry['task']=='app.workers.tasks_primary_discovery.collect_primary'\nassert entry['schedule'].minute=={39} and entry['schedule'].hour=={0,4,8,12,16,20}\nprint('LUKOIL_MONITOR_RUNTIME_OK:',str(entry['schedule']),str(celery_app.conf.timezone),'candidates only; no LLM handoff; shared documents:',VERSION,flush=True)\n"

LUKOIL_PREVIOUS_SHA = 'c91e0a848fd33e58abbc716612cb09c95c7712c19d59496af3ffd471bff1df3a'
NORNICKEL_MODULE = '"""Public listing monitor. Does not create tenders or submit analysis tasks."""\nfrom datetime import datetime,timezone\nimport re\nfrom app.sources.lukoil_public import Reader,check_nornickel\nVERSION=\'nornickel-public-monitor-20261029-1\'\n\ndef collect(*,persist=True,fetch=None):\n    from app.marketplace_discovery.primary.collector import save_report\n    from app.reports.review_dismissals import is_dismissed\n    reader=Reader(fetch)\n    try:\n        report=check_nornickel(reader)\n        report.update(version=VERSION,checked_at=datetime.now(timezone.utc).isoformat(),name=\'Норникель\',\n            requests=len(reader.requests),request_details=reader.requests,items=[],pipeline=[],queued_count=0,\n            pipeline_ready=False,pipeline_status=\'candidates_only_no_automatic_analysis\',backlog_pending=0,\n            adapter_status=\'public_monitor_only\',coverage=\'first_page_per_keyword_per_section\')\n        report[\'read_check_status\']=report[\'status\']\n        searches=[s for p in report.get(\'pages\',[]) for s in p.get(\'searches\',[])]\n        report[\'status\']=\'partial\' if report.get(\'errors\') or not searches or any(s.get(\'complete\') is not True for s in searches) else \'ok\'\n        candidates=[];seen=set()\n        for search in searches:\n            for item in search[\'items\']:\n                title=item[\'title\']\n                if item.get(\'aluminium_material_confirmed\') is False:continue\n                if item.get(\'aluminium_material_confirmed\') is not True and not re.search(r\'металлопрокат|металлопродукц|цветн\\w*\\s+металл\',title,re.I):continue\n                if re.search(r\'выполнение\\s+работ|оказание\\s+услуг|сульфат|гидроксид|канцеляр|офисн\',title,re.I):continue\n                # Deduplicate identical reports only. A title reference is not a verified tender ID.\n                key=(item[\'section\'],item.get(\'native_id\'),item.get(\'reference_from_title\'),title)\n                if key in seen:continue\n                seen.add(key)\n                if item.get(\'native_id\') is not None and is_dismissed(\'nornickel\',str(item[\'native_id\'])):continue\n                candidates.append(dict(item,llm_queued=False,reason=\'identity_deadline_documents_and_volume_require_confirmation\'))\n        report[\'candidates\']=candidates;report[\'candidate_count\']=len(candidates)\n        if persist:save_report(\'nornickel\',report)\n        return report\n    finally:reader.close()\n'
NORNICKEL_BRANCH = "if site == 'nornickel':\n    from app.sources.nornickel_public import collect as collect_nornickel\n    return collect_nornickel(persist=persist,fetch=fetch)"
NORNICKEL_SCHEDULE = "# Nornickel public monitoring only; no automatic document/LLM handoff.\ncelery_app.conf.beat_schedule['primary-nornickel-4h'] = {\n    'task':'app.workers.tasks_primary_discovery.collect_primary',\n    'schedule':crontab(minute=38,hour='*/4'),\n    'args':('nornickel',),\n    'options':{'expires':3600},\n}\n"
