def lukoil_monitor_changes(root):
    if not (root/'app/ocr/document_formats.py').is_file():raise SystemExit('DOCUMENT_FORMATS_REQUIRED: install document formats first; no files changed')
    pending=[]
    module=root/'app/sources/lukoil_public.py'
    if module.is_symlink():raise SystemExit('LUKOIL_SYMLINK: no files changed')
    raw=module.read_bytes() if module.exists() else None
    if raw is not None and raw!=LUKOIL_MODULE.encode() and hashlib.sha256(raw).hexdigest()!=LUKOIL_PREVIOUS_SHA:raise SystemExit('LUKOIL_MODULE_VERSION_MISMATCH: no files changed')
    if raw!=LUKOIL_MODULE.encode():pending.append(('app/sources/lukoil_public.py',LUKOIL_MODULE,raw))
    rel='app/marketplace_discovery/primary/collector.py';p=root/rel
    if p.is_symlink():raise SystemExit('LUKOIL_SYMLINK: no files changed')
    original=p.read_bytes();source=original.decode();tree=ast.parse(source)
    nodes=[n for n in tree.body if isinstance(n,ast.FunctionDef) and n.name=='collect']
    if len(nodes)!=1:raise SystemExit('LUKOIL_COLLECTOR_MISSING: no files changed')
    node=nodes[0]
    if [a.arg for a in node.args.args]!=['site'] or not {'persist','fetch'}<={a.arg for a in node.args.kwonlyargs}:raise SystemExit('LUKOIL_COLLECTOR_CONTRACT_CHANGED: no files changed')
    branch=ast.parse(LUKOIL_BRANCH).body[0]
    matches=[n for n in ast.walk(node) if isinstance(n,ast.Constant) and n.value=='lukoil']
    if matches:
        if len(matches)!=1 or not any(ast.dump(n,include_attributes=False)==ast.dump(branch,include_attributes=False) for n in node.body):raise SystemExit('LUKOIL_EXISTING_ROUTE_DIFFERS: no files changed')
    else:
        start=node.body[0].lineno-1
        if isinstance(node.body[0],ast.Expr) and isinstance(node.body[0].value,ast.Constant) and isinstance(node.body[0].value.value,str):start=node.body[0].end_lineno
        lines=source.splitlines(keepends=True);lines[start:start]=[''.join('    '+line+'\n' for line in LUKOIL_BRANCH.splitlines())];source=''.join(lines)
    compile(source,rel,'exec')
    if source.encode()!=original:pending.append((rel,source,original))
    rel='app/workers/celery_app.py';p=root/rel
    if p.is_symlink():raise SystemExit('LUKOIL_SYMLINK: no files changed')
    original=p.read_bytes();source=original.decode()
    if 'primary-lukoil-4h' in source:
        if LUKOIL_SCHEDULE.strip() not in source:raise SystemExit('LUKOIL_EXISTING_SCHEDULE_DIFFERS: no files changed')
    else:source=source.rstrip()+'\n\n'+LUKOIL_SCHEDULE
    compile(source,rel,'exec')
    if source.encode()!=original:pending.append((rel,source,original))
    return pending


def install_lukoil_monitor(root,include_norn=False):
    running=set(run(['docker','compose','ps','--services','--status','running'],capture_output=True,text=True,timeout=20).stdout.split())
    observed_running=set(running)
    if 'app' not in running:raise SystemExit('APP_NOT_RUNNING: no files changed or services started')
    journal=root/'backups'/'corporate-monitor-service-state.json'
    if journal.exists():
        saved=json.loads(journal.read_text())
        if saved.get('version')!=1 or not isinstance(saved.get('running'),list) or not set(saved['running'])<={'app','celery_worker','celery_discovery','celery_beat'}:raise SystemExit('CORPORATE_SERVICE_STATE_INVALID: no files changed')
        running.update(saved['running'])
    pending=corporate_monitor_changes(root) if include_norn else lukoil_monitor_changes(root)
    backup=root/'backups'/('lukoil-monitor-'+datetime.now(timezone.utc).strftime('%Y%m%d-%H%M%S-%f'))
    try:
        for rel,content,old in pending:
            if old is not None:atomic(backup/rel,old)
        if pending:
            atomic(backup/'manifest.json',json.dumps({'files':[{'path':rel,'new_file':old is None} for rel,_,old in pending]},indent=2).encode())
            for rel,content,old in pending:atomic(root/rel,content.encode('utf8'))
            print('BACKUP:',backup,flush=True)
        run(['docker','compose','build','app','celery_worker','celery_discovery','celery_beat'])
        run(['docker','compose','run','--rm','--no-deps','-T','app','python','-'],input=LUKOIL_TESTS+'\n'+(CORPORATE_VERIFY if include_norn else LUKOIL_VERIFY),text=True,timeout=240)
    except BaseException:
        for rel,_,old in pending:
            if old is None:(root/rel).unlink(missing_ok=True)
            else:atomic(root/rel,old)
        print('LUKOIL_BUILD_OR_TEST_FAILED: sources restored; running services not restarted',flush=True)
        raise
    services=[s for s in ('celery_beat','celery_discovery','celery_worker') if s in observed_running]
    ids=[]
    for service in services:ids.extend(run(['docker','compose','ps','-q',service],capture_output=True,text=True,timeout=20).stdout.split())
    atomic(journal,json.dumps({'version':1,'running':sorted(running.intersection({'app','celery_worker','celery_discovery','celery_beat'}))}).encode())
    if services:
        print('Waiting for existing tasks to finish; no forced stop or queue purge.',flush=True)
        run(['docker','compose','kill','--signal','SIGTERM',*services],timeout=30)
        until=time.monotonic()+300
        while ids:
            states=run(['docker','inspect','--format','{{.State.Running}}',*ids],capture_output=True,text=True,timeout=20).stdout.split()
            if len(states)==len(ids) and all(v=='false' for v in states):break
            if time.monotonic()>until:raise SystemExit('WARM_SHUTDOWN_PENDING: no forced stop; rerun this same command when tasks finish')
            time.sleep(3)
    restore=[s for s in ('app','celery_worker','celery_discovery') if s in running]
    run(['docker','compose','up','-d','--no-deps',*restore])
    run(['docker','compose','exec','-T','app','python','-'],input=CORPORATE_VERIFY if include_norn else LUKOIL_VERIFY,text=True,timeout=45)
    if 'celery_beat' in running:run(['docker','compose','up','-d','--no-deps','celery_beat'])
    journal.unlink(missing_ok=True)
    if include_norn:print('CORPORATE_MONITORS_INSTALLED: lukoil 39 */4; nornickel 38 */4; reports/candidates only; no immediate collection, tender DB edits or OCR/LLM submissions.',flush=True)
    print('LUKOIL_MONITOR_INSTALLED: public collection at 39 */4; candidates/report only; no automatic OCR/LLM/dashboard handoff; no immediate collection or DB changes; existing service states retained.',flush=True)



def corporate_monitor_changes(root):
    pending=lukoil_monitor_changes(root)
    module=root/'app/sources/nornickel_public.py'
    if module.is_symlink():raise SystemExit('NORNICKEL_SYMLINK: no files changed')
    raw=module.read_bytes() if module.exists() else None
    if raw is not None and raw!=NORNICKEL_MODULE.encode():raise SystemExit('NORNICKEL_MODULE_VERSION_MISMATCH: no files changed')
    if raw is None:pending.append(('app/sources/nornickel_public.py',NORNICKEL_MODULE,None))
    rel='app/marketplace_discovery/primary/collector.py';p=root/rel
    original=p.read_bytes();source=next((c for r,c,_ in pending if r==rel),original.decode())
    node=next(n for n in ast.parse(source).body if isinstance(n,ast.FunctionDef) and n.name=='collect')
    branch=ast.parse(NORNICKEL_BRANCH).body[0]
    matches=[n for n in ast.walk(node) if isinstance(n,ast.Constant) and n.value=='nornickel']
    if matches:
        if len(matches)!=1 or not any(ast.dump(n,include_attributes=False)==ast.dump(branch,include_attributes=False) for n in node.body):raise SystemExit('NORNICKEL_EXISTING_ROUTE_DIFFERS: no files changed')
    else:
        start=node.body[0].lineno-1
        if isinstance(node.body[0],ast.Expr) and isinstance(node.body[0].value,ast.Constant) and isinstance(node.body[0].value.value,str):start=node.body[0].end_lineno
        lines=source.splitlines(keepends=True);lines[start:start]=[''.join('    '+line+'\n' for line in NORNICKEL_BRANCH.splitlines())];source=''.join(lines)
    compile(source,rel,'exec');pending=[x for x in pending if x[0]!=rel]
    if source.encode()!=original:pending.append((rel,source,original))
    rel='app/workers/celery_app.py';p=root/rel;original=p.read_bytes()
    source=next((c for r,c,_ in pending if r==rel),original.decode())
    if 'primary-nornickel-4h' in source:
        if NORNICKEL_SCHEDULE.strip() not in source:raise SystemExit('NORNICKEL_EXISTING_SCHEDULE_DIFFERS: no files changed')
    else:source=source.rstrip()+'\n\n'+NORNICKEL_SCHEDULE
    compile(source,rel,'exec');pending=[x for x in pending if x[0]!=rel]
    if source.encode()!=original:pending.append((rel,source,original))
    return pending



def main():
 parser=argparse.ArgumentParser(description='Install verified public developer adapters and repair discovery reporting. Existing OCR/LLM, no duplicate models.')
 parser.add_argument('--check-only',action='store_true',help='check source versions without Docker or writes')
 parser.add_argument('--diagnose-only',action='store_true',help='read GPB gate and saved handoff failures; no HTTP, tasks or DB writes')
 parser.add_argument('--guide',action='store_true',help='print the integrated Russian deployment guide')
 parser.add_argument('--status',action='store_true',help='read installed source schedules and reports; no tasks or LLM')
 parser.add_argument('--repair-review-buttons',action='store_true',help='repair review button request validation and errors; restart app only')
 parser.add_argument('--repair-lamoda-queue',action='store_true',help='install, remove only confirmed Lamoda task, preserve history and resume existing worker schedules')
 parser.add_argument('--run-roseltorg',action='store_true',help='install then queue one existing Roseltorg collection; OCR/LLM may follow')
 parser.add_argument('--run-gpb',action='store_true',help='after successful installation queue one bounded GPB collection')
 parser.add_argument('--recover-gpb-large',action='store_true',help='install and resume saved texts of GPB 2081355 once; no OCR/downloads')
 parser.add_argument('--probe-tender-pro',action='store_true',help='one API request and bounded TLS checks, no business tasks')
 parser.add_argument('--audit-backlog',action='store_true',help='read GPB/Bidzaar candidates and worker states')
 parser.add_argument('--check-access',action='store_true',help='install then run access probe and backlog audit')
 parser.add_argument('--compare-tender-pro-network',action='store_true',help='compare DNS/TCP/TLS on host and worker container; no API requests')
 parser.add_argument('--run-priority',action='store_true',help='install, compare network and queue one GPB/Bidzaar collection each')
 parser.add_argument('--check-tender-pro-public',action='store_true',help='check public keyword search without API keys; save diagnostic report only')
 parser.add_argument('--check-sber-card',action='store_true',help='read one Sber purchase through verified public TEMPLATE contract and up to two document samples; terminal only; no installation or tasks')
 parser.add_argument('--check-new-platforms',action='store_true',help='read-only public onboarding checks for Roseltorg/Sberbank-AST/RTS')
 parser.add_argument('--audit-queues',action='store_true',help='observe configured broker, worker tasks and DB processing states via running app; no installation or business tasks')
 parser.add_argument('--check-next-platforms',action='store_true',help='check Sber/Tatneft/PIK/Akvilon/Level and print sanitized contract evidence to terminal; optional diagnostic ZIP; no installation')
